window.FEEDS = [{"id": "ai-2026-10-23", "date": "2026-10-23", "title": "AI in healthcare: today's research roundup — 23 October 2026", "excerpt": "Several new studies test large language models against human performance on diagnosis and documentation tasks. A large-scale study applied ChatGPT-4o to 1,157 colorectal…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Several new studies test large language models against human performance on diagnosis and documentation tasks. A large-scale study applied ChatGPT-4o to 1,157 colorectal surgery electronic health records to flag surgical site infections, reaching 85.7% overall accuracy with sensitivity of 86.3% and specificity of 85.7%. A separate comparison of ChatGPT, Gemini, and DeepSeek on 138 visual internal medicine cases tested how much adding a brief clinical history improved diagnostic accuracy over image alone. In dentistry, ChatGPT-5 showed strong accuracy on text-based reversible pulpitis questions but dropped to about 4.67% accuracy when working from radiographic descriptions, underscoring a persistent text-versus-image gap. On the documentation side, an LLM rewrite of surgical consent forms cut reading level from grade 14.1 to grade 8.8, but content fidelity fell (F1 0.71, recall 0.62), with larger readability gains tied to more content omitted (r=0.73). A 442-question ophthalmology exam comparison found Microsoft Copilot outperformed ChatGPT-4o mini and Gemini 1.5 Flash on both accuracy (89.4% vs. 84.2% and 76.7%) and readability.", "On the prognostic and diagnostic model side, a LightGBM model for early detection of monoclonal immunoglobulin-related disorders from routine labs reached an AUC of 0.945 (87.0% sensitivity, 89.6% specificity) in an independent multi-institutional validation cohort. A model combining phase-rectified signal averaging with machine learning to predict stroke-associated infections reached an AUC of 0.939. A nationwide cohort study predicting hepatocellular carcinoma risk in patients with steatotic liver disease reported an internal validation AUC of 0.923. A meta-analysis of machine learning models predicting proximal junctional pathology after adult spinal deformity surgery pooled sensitivity and specificity at 0.51 and 0.84, rising to 0.63 sensitivity for the best-performing model class, highlighting wide variability across published models.", "Taken together, today's studies reinforce a consistent pattern: both LLMs and traditional ML models perform well on narrow, well-defined tasks but show meaningful drops when context shifts, whether from text to image input or from single-center development to independent validation."], "refs": [{"title": "Validation of ChatGPT-4o for detecting surgical site infections after colorectal surgery from electronic health records", "url": "https://pubmed.ncbi.nlm.nih.gov/41967571/"}, {"title": "Diagnostic accuracy and repeatability of ChatGPT using textual and radiographic data in reversible pulpitis", "url": "https://pubmed.ncbi.nlm.nih.gov/42602192/"}, {"title": "Speaking Patient's Language: Assessment of Readability and Fidelity of Artificial Intelligence-Optimized Consent Forms", "url": "https://pubmed.ncbi.nlm.nih.gov/41990646/"}, {"title": "Evaluating Three Large Language Models in Ophthalmology Education", "url": "https://pubmed.ncbi.nlm.nih.gov/41879107/"}, {"title": "Multi-center validation of a machine learning model for early detection of monoclonal immunoglobulin-related disorders", "url": "https://pubmed.ncbi.nlm.nih.gov/42382760/"}, {"title": "Integrating phase-rectified signal averaging with machine learning to predict stroke-associated infections", "url": "https://pubmed.ncbi.nlm.nih.gov/41607833/"}, {"title": "Machine learning-based prediction of hepatocellular carcinoma risk in steatotic liver disease", "url": "https://pubmed.ncbi.nlm.nih.gov/42207764/"}, {"title": "Machine learning-based prediction of proximal junctional pathology after adult spinal deformity surgery", "url": "https://pubmed.ncbi.nlm.nih.gov/42098465/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-22", "date": "2026-10-22", "title": "AI in healthcare: today's research roundup — 22 October 2026", "excerpt": "Several studies today look at how large language models perform against expert clinicians in time-pressured decisions. A retrospective study gave GPT-4 clinical data on…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Several studies today look at how large language models perform against expert clinicians in time-pressured decisions. A retrospective study gave GPT-4 clinical data on 100 acute stroke patients and found its treatment recommendations agreed with real-world decisions at AUC 0.80 overall, rising to 0.94 for thrombectomy specifically, and with an expert stroke specialist at AUC 0.85. In the emergency department, ChatGPT-4o's triage calls on 60 case scenarios showed moderate-to-substantial agreement with four experienced physicians (kappa 0.695), with perfect sensitivity at the most urgent triage level but a drop to 50% sensitivity at a lower-urgency level. A feasibility study applied a HIPAA-secure GPT-4o to electronic health records to identify and summarize goals-of-care conversations in advanced cancer patients at scale, a task that otherwise requires labor-intensive manual chart review. A broader scoping review of 43 studies on AI agents in healthcare (conversational, workflow, and multimodal decision-support types) found most evaluation still happens in simulated or lab settings, with few real clinical pilots and rare measurement of safety outcomes.", "On the prognostic and diagnostic side, a deep learning study tested whether genetic disease risk can be predicted from summary-level data (linkage disequilibrium matrices) instead of individual-level genotypes, finding most model architectures reached test error comparable to individual-level-data models. A systematic review and meta-analysis of 45 studies on machine learning for endometriosis diagnosis found clinical-feature models reached a pooled validation AUC of about 0.80, while genetic-information models scored much higher on training data (AUC ~0.98) but dropped substantially on validation. A VGG16-based convolutional neural network trained on over 6,300 ocular images plus clinical variables reached 90% accuracy for ocular disease diagnosis. And a wearable single-lead ECG study used an LSTM model to forecast 6-12 month NT-proBNP changes in persistent atrial fibrillation patients, reaching 82% directional accuracy for heart failure progression.", "Across both groups, the recurring theme is a gap between promising discrimination metrics and validated real-world performance, whether that's an LLM's triage judgment under pressure or a diagnostic model's drop from training to validation data."], "refs": [{"title": "GPT-4 as a Clinical Decision Support Tool in Ischemic Stroke Management: Evaluation Study", "url": "https://pubmed.ncbi.nlm.nih.gov/40053715/"}, {"title": "Evaluating the Accuracy of Artificial Intelligence Chatbots in Triaging Emergency Cases: A Comparative Study with Expert Clinicians", "url": "https://pubmed.ncbi.nlm.nih.gov/40972466/"}, {"title": "Feasibility Study for Using Large Language Models to Identify Goals-of-Care Documentation at Scale in Patients With Advanced Cancer", "url": "https://pubmed.ncbi.nlm.nih.gov/40209123/"}, {"title": "Artificial intelligence agents in healthcare research: A scoping review", "url": "https://pubmed.ncbi.nlm.nih.gov/41666194/"}, {"title": "Genetic risk predictions using deep learning models with summary data", "url": "https://pubmed.ncbi.nlm.nih.gov/41584515/"}, {"title": "Diagnostic accuracy of machine learning for endometriosis: a systematic review and meta-analysis", "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12886017/"}, {"title": "Application of convolutional neural networks in the diagnosis of ocular diseases: evaluation of the VGG16 model", "url": "https://doi.org/10.1007/s00521-026-11904-8"}, {"title": "AI-based prediction of heart failure progression in persistent atrial fibrillation using wearable electrocardiography", "url": "https://pubmed.ncbi.nlm.nih.gov/41727311/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-21", "date": "2026-10-21", "title": "AI in healthcare: today's research roundup — 21 October 2026", "excerpt": "Several studies this week test large language models directly against clinicians rather than against benchmarks. A Kenyan cluster-randomized trial across 16 primary care…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Several studies this week test large language models directly against clinicians rather than against benchmarks. A Kenyan cluster-randomized trial across 16 primary care facilities (9,691 patients) found an LLM-based decision support tool embedded in the EMR did not significantly reduce 14-day treatment failure (2.2% vs. 2.0%, P=0.13), though AI-assisted clinicians produced better-documented care with no safety signal. A German/Norwegian rheumatology RCT (82 physicians) found a certified LLM diagnostic copilot did not improve top-1 diagnostic accuracy over conventional resources, but cut case-processing time nearly in half (94 vs. 206 seconds). On imaging, a benchmark of five vision-language models against radiologists on 478 emergency department chest X-rays found one model (AIRead) had a lower serious-discrepancy rate than radiologists themselves (5.3% vs. 13.9%), while a separate DeepSeek-R1 error-detection system caught 84.4% of planted errors in emergency radiology reports in few-shot mode, matching senior radiologists.", "On the prognostic and diagnostic side, a foundation model trained on continuous glucose monitoring data (GluFormer) flagged diabetes and cardiovascular-death risk ahead of HbA1c, placing 66% of incident diabetes cases in its top risk quartile versus 7% in the bottom, validated across 19 external cohorts. An NIH-supported deep learning model analyzing single-lead ECGs recorded during sleep studies predicted 10-year risk of atrial fibrillation, stroke, heart failure, and all-cause mortality, holding up after adjusting for diabetes, hypertension, and sleep apnea severity. A MIMIC-IV cohort of over 11,000 ICU patients with encephalopathy produced mortality and readmission models reaching internal AUROCs near 0.98, though the authors caution these single-database figures need external validation given known leakage and spectrum-bias risks. A systematic review of 34 studies on symptomatic-patient cancer risk models (lung, mesothelioma, GI cancers) found wide heterogeneity in validation quality across the field.", "Taken together, the week's clinical trials are a useful counterweight to the field's imaging and risk-model gains: LLM assistance consistently speeds up clinical workflows, but head-to-head trials are not yet showing it moves hard patient outcomes."], "refs": [{"title": "Generative AI-enabled clinical decision support system in primary care: a pragmatic, cluster-randomized trial", "url": "https://doi.org/10.1038/s41591-026-04503-6"}, {"title": "Certified large language model-based diagnostic decision support in rheumatology: the ALLIANCE multicentre randomised controlled trial", "url": "https://doi.org/10.64898/2026.08.29.26361715"}, {"title": "Comparative Evaluation of Generative AI Models for Chest Radiograph Report Generation in the Emergency Department", "url": "https://doi.org/10.1007/s00330-026-12648-8"}, {"title": "Error Detection in Emergency Radiology Reports Using a Large Language Model: Multistage Evaluation Study", "url": "https://www.jmir.org/2026/1/e86841"}, {"title": "A foundation model for continuous glucose monitoring data", "url": "https://doi.org/10.1038/s41586-025-09925-9"}, {"title": "Deep learning model using ECGs during sleep studies can predict cardiovascular outcomes", "url": "https://www.nih.gov/news-events/news-releases/deep-learning-model-using-ecgs-during-sleep-studies-can-predict-cardiovascular-outcomes"}, {"title": "Machine Learning Models for Mortality and Readmission in Encephalopathy: Performance and Pitfalls From a Large ICU Cohort", "url": "https://index.mirasmart.com/AAN2026/PDFfiles/AAN2026-004876.html"}, {"title": "Cancer Risk Prediction Using Machine Learning for Supporting Early Cancer Diagnosis in Symptomatic Patients: A Systematic Review of Model Types", "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12701559/"}], "lang": "en", "source": "ai"}, {"id": "ph-2026-10-13-unmoved-mover-first-cause", "date": "2026-10-20", "title": "অচল চালক ও প্রথম কারণ: অ্যারিস্টটলের যুক্তি", "title_en": "The Unmoved Mover / First Cause (Aristotle)", "excerpt": "আপনার হাতে একটা লাঠি আছে, আর সেই লাঠি দিয়ে আপনি একটা পাথর ঠেলে নিয়ে যাচ্ছেন। পাথরটা নড়ছে কেন? কারণ লাঠিটা তাকে ধাক্কা দিচ্ছে। লাঠিটা নড়ছে কেন? কারণ আপনার হাত তাকে…", "theme": "faith", "cats": ["স্রষ্টার অস্তিত্বের যুক্তি", "দর্শন"], "body": ["আপনার হাতে একটা লাঠি আছে, আর সেই লাঠি দিয়ে আপনি একটা পাথর ঠেলে নিয়ে যাচ্ছেন। পাথরটা নড়ছে কেন? কারণ লাঠিটা তাকে ধাক্কা দিচ্ছে। লাঠিটা নড়ছে কেন? কারণ আপনার হাত তাকে নড়াচ্ছে। আর আপনার হাত নড়ছে কেন? এখানে এসে প্রশ্নটা থেমে যায় না, বরং আরও গভীরে যায় — আপনার হাতের পেশি, তার স্নায়ু, মস্তিষ্কের সিদ্ধান্ত — একটা জিনিস আরেকটাকে নড়াচ্ছে, সেটা আরেকটাকে। প্রায় আড়াই হাজার বছর আগে গ্রিক দার্শনিক অ্যারিস্টটল ঠিক এই সাধারণ পর্যবেক্ষণটা নিয়েই বসেছিলেন, আর তা থেকে বের করে এনেছিলেন দর্শনের ইতিহাসের সবচেয়ে প্রভাবশালী একটা যুক্তি — \"অচালিত চালক\" বা \"প্রথম কারণ\" (The Unmoved Mover / First Cause) এর যুক্তি। আজ আমরা এই যুক্তিটা নিয়েই কথা বলব — যেটা পরে থমাস অ্যাকুইনাসের \"পাঁচ পথ\"-এর প্রথম পথের ভিত্তি হয়ে উঠেছিল, কিন্তু যার আসল রূপ অ্যারিস্টটলের নিজের লেখা \"ফিজিক্স\" এবং \"মেটাফিজিক্স\" বইয়ে পাওয়া যায়।", "প্রথমে একটা জিনিস স্পষ্ট করে নেওয়া যাক। অ্যারিস্টটল যখন \"গতি\" বা \"পরিবর্তন\" (motion/change, গ্রিক ভাষায় কাইনেসিস) বলেন, তখন তিনি শুধু স্থান বদলানোর কথা বলছেন না। তাঁর কাছে \"পরিবর্তন\" মানে অনেক বিস্তৃত কিছু — তাপ বাড়া-কমা, রঙ বদলানো, বড় হওয়া, এমনকি কাঠ পুড়ে ছাই হয়ে যাওয়াও একরকম পরিবর্তন। এই সব পরিবর্তন বোঝার জন্য তিনি দুটো ধারণা ব্যবহার করেন — \"সম্ভাব্য অবস্থা\" (potentiality, গ্রিক ভাষায় দ্যুনামিস) আর \"প্রকৃত অবস্থা\" (actuality, এনার্জেইয়া)। ধরুন, একটা ম্যাচের কাঠি। সেটার মধ্যে আগুন ধরার \"সম্ভাবনা\" আছে, কিন্তু সে এখনো জ্বলছে না — তার আগুন হয়ে ওঠাটা এখনো \"সম্ভাব্য\" মাত্র, \"প্রকৃত\" নয়। এই সম্ভাবনাটাকে বাস্তবে রূপ দিতে, অর্থাৎ কাঠিটাকে জ্বালাতে, আপনার লাগবে এমন কিছু যা ইতিমধ্যেই \"প্রকৃতভাবে\" জ্বলছে বা উত্তপ্ত — যেমন একটা দেশলাইয়ের ঘর্ষণ-তাপ, বা আরেকটা জ্বলন্ত আগুন। একটা নিভন্ত কাঠি নিজে নিজেকে জ্বালাতে পারে না। অ্যারিস্টটলের মূল কথাটা এখানেই — যা কিছু সম্ভাব্য অবস্থা থেকে প্রকৃত অবস্থায় আসে, তাকে অন্য কিছু দ্বারা, যা নিজে ইতিমধ্যে সেই দিক দিয়ে প্রকৃত, আনতে হয়। নিজের মধ্যে যা নেই, তা নিজেকে নিজে দিতে পারে না।", "এখন মূল যুক্তিটায় আসা যাক। আপনার হাত-লাঠি-পাথরের উদাহরণে ফিরে যাই। পাথরটা নড়ছে, কারণ লাঠি তাকে নড়াচ্ছে, কিন্তু লাঠিটার নিজের মধ্যে নড়ার কোনো সহজাত ক্ষমতা নেই — সে যে শক্তি পাথরে দিচ্ছে, সেটা তার নিজের নয়, সে পাচ্ছে হাত থেকে, ঠিক এই মুহূর্তে, এখনই। এখানে একটা গুরুত্বপূর্ণ পার্থক্য বোঝা জরুরি, যেটা অনেকেই এই যুক্তি পড়তে গিয়ে গুলিয়ে ফেলেন। এটা এমন একটা শৃঙ্খলের কথা বলছে না, যেখানে একটা জিনিস আরেকটাকে জন্ম দিয়ে সরে যায় — যেমন বাবা ছেলেকে জন্ম দেওয়ার পর মারা গেলেও ছেলে বেঁচে থাকতে পারে, এমনকি নাতিও জন্ম নিতে পারে। এটাকে বলা হয় \"আনুষঙ্গিক ক্রম\" (accidentally ordered series) — এখানে প্রতিটা সদস্য স্বাধীনভাবে তার কাজ করে, আগের সদস্যের উপস্থিতি ছাড়াই। কিন্তু লাঠি-পাথরের উদাহরণটা সম্পূর্ণ ভিন্ন রকমের একটা শৃঙ্খল — এখানে লাঠি যদি এই মুহূর্তে হাত থেকে শক্তি না পায়, তাহলে পাথরকে নড়ানোর তার কোনো ক্ষমতাই নেই, এক সেকেন্ডের জন্যও না। এটাকে বলা হয় \"স্বভাবগত ক্রম\" (essentially ordered series, বা ল্যাটিনে \"পের সে\" ক্রম) — এখানে প্রতিটা সদস্যের ক্ষমতা ধার করা, এবং সেই ধার এই মুহূর্তেই, একই সঙ্গে, চলমান থাকতে হয়। অ্যারিস্টটলের যুক্তি হলো, এই ধরনের \"স্বভাবগত ক্রম\" অসীম পর্যন্ত চলতে পারে না। কারণ যদি প্রতিটা সদস্যই নিজের শক্তি ধার করে থাকে, এবং কোথাও এমন একটা সদস্য না থাকে যে নিজেই, নিজের মধ্যে, শক্তির উৎস — তাহলে ধার করার মতো আসলে কোনো শক্তিই কোথাও নেই। একটা ট্রেনের বগির মতো — একটার পর একটা বগি যদি অসীম পর্যন্ত চলতে থাকে, কিন্তু কোথাও একটা নিজ-শক্তিসম্পন্ন ইঞ্জিন না থাকে, তাহলে পুরো ট্রেনটাই স্থির হয়ে থাকবে, যতই বগির সংখ্যা বাড়ানো হোক। তাই শেষ পর্যন্ত এমন একটা কিছু থাকতেই হবে, যে নিজে নড়ে না, কিন্তু অন্য সব কিছুকে নড়ানোর মূল উৎস — একটা \"অচল চালক\" (Unmoved Mover)।", "এখানে একটা জিনিস খুব স্পষ্ট করে বলা দরকার, কারণ এটা নিয়ে সবচেয়ে বেশি ভুল বোঝাবুঝি হয়। এই যুক্তিটা মহাবিশ্বের শুরু নিয়ে কথা বলছে না — এটা \"বিগ ব্যাং-এর আগে কী ছিল\" জাতীয় প্রশ্ন নয় (সেটা হলো কালাম যুক্তি, যা সম্পূর্ণ আলাদা একটা যুক্তি, সময়ের মধ্যে একটা ঐতিহাসিক শুরুর কথা বলে)। অ্যারিস্টটল নিজে বিশ্বাস করতেন, মহাবিশ্ব চিরকাল ধরে ছিল, তার কোনো সাময়িক শুরু নেই। তাঁর যুক্তিটা বরং এই মুহূর্তে, এখনই, যা কিছু ঘটছে তার ব্যাখ্যা নিয়ে — এই মুহূর্তে পাথরটা কেন নড়ছে, এই মুহূর্তে আপনার হৃৎপিণ্ড কেন স্পন্দিত হচ্ছে, এই মুহূর্তে আকাশে সূর্যের আলো কেন জ্বলছে — এগুলোর পেছনে একই সঙ্গে চলমান একটা নির্ভরতার শৃঙ্খল আছে, আর সেই শৃঙ্খলের একটা ভিত্তি লাগবে, এখনই, এই ক্ষণেই।", "অ্যারিস্টটল তাঁর \"মেটাফিজিক্স\" বইয়ের দ্বাদশ খণ্ডে এই অচল চালকের স্বভাব নিয়ে আরও এগিয়ে যান। তাঁর যুক্তি, এই চালককে হতে হবে সম্পূর্ণ \"প্রকৃত\" (pure actuality) — তার মধ্যে কোনো অবাস্তবায়িত সম্ভাবনা থাকতে পারবে না, কারণ থাকলে তাকেও আবার কেউ বাস্তবায়িত করতে হতো, আর তখন শৃঙ্খলটা আরও এক ধাপ পেছনে চলে যেত। তাই এটা হতে হবে অপরিবর্তনীয়, বস্তুহীন (immaterial, কারণ বস্তুর ধর্মই হলো পরিবর্তনের সম্ভাবনা বহন করা), এবং চিরন্তন। সবচেয়ে কাব্যিক অংশটা এখানে — অ্যারিস্টটল বলেন, এই অচল চালক মহাবিশ্বকে নড়ায় \"ধাক্কা দিয়ে\" নয়, বরং \"প্রেমের বস্তু হিসেবে\" (as an object of desire/love)। যেমন একজন মানুষ কোনো আদর্শ বা সৌন্দর্যের প্রতি আকৃষ্ট হয়ে নিজের ইচ্ছায় এগিয়ে যায়, শারীরিকভাবে ধাক্কা না পেয়েও — ঠিক তেমনই পুরো মহাবিশ্ব এই পরম পূর্ণতার দিকে আকৃষ্ট হয়ে চলমান থাকে। এই চালক নিজে শুধু নিজের কথাই চিন্তা করে — \"চিন্তা যা নিজেকেই চিন্তা করে\" (thought thinking itself), কারণ তার চিন্তার যোগ্য সবচেয়ে পূর্ণ বিষয় তো সে নিজেই।", "এই যুক্তি কতটা প্রভাবশালী হয়েছিল, তা বোঝা যায় এই থেকে যে শত শত বছর পরে থমাস অ্যাকুইনাস তাঁর বিখ্যাত \"পাঁচ পথ\"-এর প্রথম পথে এটাকেই ভিত্তি করে নেন, যদিও তিনি \"প্রেমের বস্তু\" ধারণাটা বদলে একজন সক্রিয়, সৃষ্টিকর্তা ঈশ্বরের দিকে নিয়ে যান। সম্ভাবনা-প্রকৃতি কাঠামোটা পরবর্তী দুই হাজার বছরের পশ্চিমা দর্শনে পরিবর্তনের সবচেয়ে গুরুত্বপূর্ণ ব্যাখ্যা-কাঠামো হয়ে থাকে।", "এখন আসি সবচেয়ে গুরুত্বপূর্ণ আপত্তিগুলোর দিকে। সবচেয়ে বেশি শোনা আপত্তিটা আসে আধুনিক পদার্থবিজ্ঞান থেকে। নিউটনের গতির প্রথম সূত্র বলে, কোনো বস্তু যদি একবার সরল রেখায় সমবেগে চলতে থাকে, তাহলে তাকে চলমান রাখার জন্য আর কোনো বাহ্যিক শক্তির দরকার নেই — এটাকে বলে \"জড়তা\" (inertia)। তাহলে কি এটা অ্যারিস্টটলের কথাকে ভুল প্রমাণ করে না, যে \"যা নড়ে তা অন্য কিছু দ্বারা নড়ে\"? অনেক আধুনিক সমালোচক এটাকেই সবচেয়ে বড় আপত্তি বলে মনে করেন। এর জবাবে দার্শনিক এডওয়ার্ড ফেজারের মতো অ্যারিস্টটলপন্থীরা বলেন, জড়তার সূত্র আসলে ব্যাখ্যা করে না কেন একটা বস্তু সমবেগে চলমান থাকার অবস্থাতেই থাকে — এটা শুধু বর্ণনা করে যে থাকে। আর যদি সমবেগে চলাটাকে সত্যিকারের \"পরিবর্তন\" বলে ধরা হয়, তাহলে তার একটা ব্যাখ্যা দরকারই থেকে যায়; আর যদি এটাকে এক ধরনের স্থিতি বা অবস্থা বলে ধরা হয় (পরিবর্তন নয়), তাহলে অ্যারিস্টটলের যুক্তি তাতে প্রয়োগই হয় না, বরং প্রযোজ্য হয় ত্বরণ বা বেগ-পরিবর্তনের ক্ষেত্রে, যেখানে এখনও একটা বাহ্যিক কারণ লাগে। সমালোচকরা পাল্টা বলেন, এই জবাবটা কিছুটা কথার কারসাজি মনে হতে পারে — মূল বিষয়টা হলো, মাঝযুগীয় পদার্থবিজ্ঞানের ধারণা যে গতি বজায় রাখতে সক্রিয় কারণ লাগে, সেটা অনেকাংশে ভুল প্রমাণিত হয়েছে, আর তাই পুরো যুক্তিটার ভৌত ভিত্তি দুর্বল হয়ে পড়ে, যতই রূপান্তরিত করে বাঁচানোর চেষ্টা করা হোক।", "দ্বিতীয় আপত্তিটা দার্শনিক উইলিয়াম প্রায়রের মতো সমালোচকদের কাছ থেকে আসে, এবং এটা অ্যারিস্টটলের নিজের কাঠামোর ভেতরের একটা টানাপোড়েন নিয়ে। অ্যারিস্টটল বলেন, জগতের প্রায় সবকিছুর মধ্যে সম্ভাব্যতা ও প্রকৃতভাব — দুটোই মিশে থাকে। কিন্তু অচল চালককে তিনি বলেন সম্পূর্ণ \"প্রকৃত\", কোনো সম্ভাব্যতা ছাড়াই। প্রশ্ন ওঠে — এমন একটা সত্তা, যার মধ্যে কোনো অব্যবহৃত সম্ভাবনা নেই, সে কি কিছু করতে পারে আদৌ? যদি সে ইতিমধ্যেই পূর্ণ, তাহলে নতুন কিছু করার, নতুন কিছু জানার, বা জগতের সাথে সক্রিয়ভাবে সম্পর্কিত হওয়ার মতো কোনো \"অবকাশ\" তার মধ্যে থাকে কী করে? আর যদি এই চালক শুধু নিজের কথাই চিন্তা করে, যেমন অ্যারিস্টটল বলেছেন, তাহলে সে জগৎ সম্পর্কে জানেই না, জগৎকে পরিচালনাও করে না — তাহলে এটা ধর্মীয় অর্থে \"ঈশ্বর\" বলতে আমরা যা বুঝি, তার থেকে অনেক দূরের একটা ধারণা হয়ে যায়।", "তৃতীয় আপত্তিটা আসে যুক্তির কাঠামো থেকেই। দার্শনিক অ্যান্থনি কেনি সহ অনেকে প্রশ্ন তোলেন — এমনকি যদি মেনেও নেওয়া হয় যে একটা \"স্বভাবগত ক্রম\" অসীম হতে পারে না, এবং কোথাও একটা অচল উৎস থাকতেই হবে, তাহলে কি তা থেকে প্রমাণিত হয় যে সেই উৎস \"অচল\" থেকে \"অচলনীয়\" (unmovable, অর্থাৎ নড়ানোই অসম্ভব এমন) পর্যায়ে চলে যায়? একটা জিনিস এই নির্দিষ্ট মুহূর্তে না নড়লেও, ভবিষ্যতে নড়তে পারার সম্ভাবনা তো থাকতেই পারে। এছাড়া কেনি উদাহরণ দেন, অ্যারিস্টটল নিজেই কিছু জায়গায় মানুষকে \"স্ব-চালক\" (self-mover) বলে স্বীকার করেন — তাহলে কেন ধরে নিতে হবে যে চালকের শৃঙ্খলের শেষে একটাই, একক, মহাজাগতিক সত্তা থাকবে, একাধিক স্বাধীন উৎস নয়?", "চতুর্থ একটা সূক্ষ্ম আপত্তি আসে চূড়ান্ত কারণ (final cause) ধারণাটা নিয়ে। প্রায়র যুক্তি দেন, একজন কাঠমিস্ত্রি যখন একটা বাড়ির নকশা কল্পনা করে কাজ শুরু করেন, তখন সেই \"কল্পিত বাড়ি\"টা তাঁর কাজের একটা ব্যাখ্যা দেয়, যদিও বাড়িটা তখনও বাস্তবে নেই। তাহলে কেন অচল চালককে সত্যিই বাস্তবে, প্রকৃত অবস্থায়, থাকতে হবে মহাবিশ্বের গতির ব্যাখ্যা হওয়ার জন্য? হয়তো এটা শুধু একটা আদর্শ লক্ষ্যবিন্দু হিসেবেই কাজ করতে পারে, সত্যিকারের অস্তিত্ব ছাড়াই। অ্যারিস্টটলপন্থীরা এর জবাবে বলেন, এই তুলনাটা পুরোপুরি মেলে না, কারণ মহাবিশ্বের ক্ষেত্রে আমরা একটা মানুষের মতো কল্পনাশক্তিসম্পন্ন প্রাণীর কথা বলছি না, বরং পুরো বাস্তবতার মৌলিক গঠন নিয়ে কথা বলছি — কিন্তু সমালোচকরা মনে করেন এই জবাবটা পুরো প্রশ্নটাকেই এড়িয়ে যায়, সরাসরি উত্তর দেয় না।", "তাহলে শেষ পর্যন্ত আমরা কোথায় দাঁড়াই? অ্যারিস্টটলের যুক্তিটা একটা গভীর, সহজাত অন্তর্দৃষ্টি থেকে শুরু হয় — কোনো কিছুর ক্ষমতা যদি সবটাই ধার করা হয়, তাহলে কোথাও না কোথাও এমন একটা উৎস থাকতেই হবে যার ক্ষমতা ধার করা নয়, নিজের। প্রশ্নটা হলো, আমাদের চেনা জগতে, সত্যিই এমন \"ধার করা ক্ষমতার শৃঙ্খল\" আছে কি না, আর থাকলেও, সেই শৃঙ্খলের তলানিতে যা আছে, তা কি সত্যিই অ্যারিস্টটলের বর্ণনা করা পরম, চিন্তাশীল, প্রেমের-বস্তু সত্তা, নাকি স্রেফ পদার্থবিজ্ঞানের কিছু মৌলিক নিয়ম, যার আর কোনো গভীর ব্যাখ্যার দরকার নেই? পরের বার যখন আপনি কোনো কিছুকে নড়তে দেখবেন — একটা পাখা ঘুরছে, একটা গাড়ি চলছে, এমনকি আপনার নিজের চিন্তাটাই এক জায়গা থেকে আরেক জায়গায় সরে যাচ্ছে — একটু থেমে ভাবুন, এই ছোট্ট নড়াচড়াটার পেছনে ধার করা শক্তির কতটা দীর্ঘ একটা শৃঙ্খল আছে, এবং সেই শৃঙ্খলটা আসলে কোথায় শেষ হয়। কমেন্টে জানান, আপনার কাছে কোনটা বেশি যুক্তিযুক্ত মনে হয় — একটা তলানি-ভিত্তি থাকতেই হবে, নাকি শৃঙ্খলটা কোনো ভিত্তি ছাড়াই ঝুলে থাকতে পারে?"], "source": "philosophy"}, {"id": "ai-2026-10-20", "date": "2026-10-20", "title": "AI in healthcare: today's research roundup — 20 October 2026", "excerpt": "Several studies this week focus on LLMs taking on clinical workflow tasks beyond chat-style Q&A. A paired acoustic stress test of ambient clinical scribes found…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Several studies this week focus on LLMs taking on clinical workflow tasks beyond chat-style Q&A. A paired acoustic stress test of ambient clinical scribes found background noise raised word error rate by only 0.71 points but nearly doubled unsafe transcription outputs, suggesting WER alone understates real safety risk. In prescription review, a locally deployed open-source model (Qwen3-14B) run on a hospital intranet assisted pharmacists across 213 outpatient prescriptions, cutting review time and improving error-detection sensitivity versus unaided review. A separate blinded evaluation of six LLMs on contraindication, interaction, and dosing questions, rated by 34 physicians, found accuracy held up on simpler queries but varied more on complex multi-drug scenarios. A JMIR AI meta-analysis of generative LLMs in mental health care concluded evidence remains too heterogeneous to support unsupervised use in diagnosis or crisis response.", "On the prognostic and diagnostic side, a Gut-published radiomics model (REDMOD) detected pancreatic cancer on routine CT scans before tumors were visually apparent, reaching an AUC of 0.82 (sensitivity 73%, specificity 81%) up to roughly three years before diagnosis in a 219-patient multi-institutional cohort, far outperforming unaided radiologists. A separate EHR-based Mayo Clinic model, built on over 39,000 patients, reached an AUROC of 0.853 for pancreatic cancer risk three years out, with 88% of high-risk-flagged patients diagnosed within a year. A Cleveland Clinic/IBM foundation model trained on over 9,600 polysomnography recordings stratified sleep patients into risk groups with significantly elevated mortality, where the standard apnea-hypopnea index showed no such association. Elsewhere, a 3.3-million-patient Kaiser Permanente cohort produced a super-learner model predicting 10-year type 2 diabetes risk (AUC 0.883 validation), and a whole-slide-image model (Chemo-prAIdict Breast) showed consistent within-patient predictions of residual disease after neoadjuvant chemotherapy.", "The week's clearest theme: models moving from retrospective benchmarks toward real deployment settings — hospital servers, prospective cohorts, standard-of-care comparators — where the gap between promising metrics and clinical utility gets tested directly."], "refs": [{"title": "Beyond WER: A Paired Acoustic Stress Test for Ambient Clinical Scribes", "url": "https://arxiv.org/abs/2606.05909"}, {"title": "Locally Deployed Large Language Models for AI-Assisted Outpatient Prescription Review: Crossover Study", "url": "https://medinform.jmir.org/2026/1/e97520"}, {"title": "Role of Large Language Models in Patient Safety in an Expert Evaluation Study", "url": "https://jhi.sbis.org.br/index.php/jhi-sbis/1820261570"}, {"title": "Generative Large Language Models in Mental Health Care Settings: Systematic Review and Meta-Analysis", "url": "https://ai.jmir.org/2026/1/e87730"}, {"title": "Next-generation AI for visually occult pancreatic cancer detection in a low-prevalence setting with longitudinal stability and multi-institutional generalisability", "url": "https://doi.org/10.1136/gutjnl-2025-337266"}, {"title": "AI Model Predicts Pancreatic Cancer Risk Up to Three Years Before Diagnosis Using Electronic Health Records", "url": "https://www.newswise.com/articles/artificial-intelligence-model-predicts-pancreatic-cancer-risk-3-years-before-diagnosis"}, {"title": "A foundation model for sleep-based risk stratification and clinical outcomes", "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12036469/"}, {"title": "Chemo-prAIdict Breast: A deep learning solution for predicting residual disease on biopsies of breast cancer patients treated with neoadjuvant chemotherapy", "url": "https://pubmed.ncbi.nlm.nih.gov/41518683/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-19", "date": "2026-10-19", "title": "AI in healthcare: today's research roundup — 19 October 2026", "excerpt": "Several new studies this week compare large language models directly against each other and against clinical benchmarks. In a blinded evaluation of 39 GERD-related…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Several new studies this week compare large language models directly against each other and against clinical benchmarks. In a blinded evaluation of 39 GERD-related questions, gastroenterologists rated Gemini-2.5 and Claude-4 above ChatGPT-5 on accuracy and comprehensiveness, while ChatGPT-5 produced the most readable, high-school-level responses, underscoring a clarity-versus-clinical-richness trade-off. A separate benchmark testing compact, on-device LLMs (gpt-oss-20b/120b) against GPT-5, o4-mini, and DeepSeek-R1 on diagnosis tasks found the smaller models performed comparably to larger cloud models, and fine-tuning closed most of the remaining gap to GPT-5. In psychiatric screening, a 555-interview benchmark found LLM accuracy ranging widely from 0.49 to 0.86 across anxiety, depression, and PTSD, with false negatives often tied to protective-context language overriding explicit symptom evidence in the models' own reasoning.", "On the prognostic and diagnostic modeling side, a deep learning coronary-segmentation system reached Dice scores of 0.95 (heart) and 0.87 (LAD artery) across 283 externally validated patients and, in prospective use, flagged 19% of 1,386 radiotherapy patients for cardiology referral based on cardiac toxicity risk. A dermoscopic skin-lesion classifier using four architectures (ViT-B/16, Swin-S, ConvNeXt-S, EfficientNetV2-S) saw its ROC-AUC drop from 0.95-0.97 internally to 0.80-0.89 on external clinical validation, another reminder of the generalization gap that shows up repeatedly in this literature. Elsewhere, a wearable-only heart-rate model using a genetic-algorithm-tuned LSTM targeted early sepsis detection outside the hospital ward, and an XGBoost model paired with rule-based explanations predicted hospitalization need in COVID-19 outpatients from a 1,278-patient cohort.", "Across both LLM and traditional ML studies, the same tension keeps surfacing: models that look strong in benchmarks or internal cohorts, and a persistent drop when tested externally or against real clinical nuance."], "refs": [{"title": "Do Bots Provide Correct and Adequate Guidance Regarding Acidity: A Blinded Comparison Rated by Patients and Physicians", "url": "https://www.wjgnet.com/2222-0682/full/v16/i3/116022.htm"}, {"title": "Benchmarking and Adapting On-Device Large Language Models for Clinical Decision Support", "url": "https://arxiv.org/abs/2601.03266"}, {"title": "When Symptoms Are Not Enough: Evidence-Weighting Patterns in Large Language Model Psychiatric Screening", "url": "https://arxiv.org/abs/2605.23148"}, {"title": "Clinical Validation and Prospective Deployment of an Automated Deep Learning-Based Coronary Segmentation and Cardiac Toxicity Risk Prediction System", "url": "https://arxiv.org/abs/2511.14971"}, {"title": "Cascade Classification of Dermoscopic Images of Skin Neoplasms with Controllable Sensitivity and External Clinical Validation", "url": "https://arxiv.org/abs/2606.13135"}, {"title": "Early Prediction of Sepsis using Heart Rate Signals and Genetic Optimized LSTM Algorithm", "url": "https://arxiv.org/abs/2512.24253"}, {"title": "Designing an Explainable Algorithm Based on XGBoost and Genetic Algorithm for Predicting Hospitalization Needs of COVID-19 Patients", "url": "https://pubmed.ncbi.nlm.nih.gov/41730967/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-18", "date": "2026-10-18", "title": "AI in healthcare: today's research roundup — 18 October 2026", "excerpt": "Two new benchmarks highlight a gap between LLM agents and real clinical workflows. PhysicianBench tested 13 proprietary and open-source agents on 100 long-horizon EHR…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Two new benchmarks highlight a gap between LLM agents and real clinical workflows. PhysicianBench tested 13 proprietary and open-source agents on 100 long-horizon EHR tasks across 21 specialties; the top model reached only 46% pass@1, with open-source models topping out near 19%. A second benchmark, ART, found GPT-4o-mini and Claude 3.5 Sonnet achieved near-perfect data retrieval from EHRs after prompt refinement but accuracy dropped to 28-64% on aggregation tasks and 32-38% on threshold reasoning. Elsewhere, LLMs showed more promise in narrower documentation roles: Llama 3.3 extracted radiotherapy treatment sites from physician notes with about 94% accuracy, and a GPT-based conversational interface for depression screening (BDI-FS-GPT) correlated moderately with the standard PHQ-9 in a 115-person study.", "On the machine learning side, a random-forest model (PRE-Screen-HCC) trained on over 900,000 UK Biobank participants outperformed existing hepatocellular carcinoma risk scores using only routine clinical data, validated externally in the All of Us cohort. An ECG-based deep learning ensemble for pre-echocardiography triage reached an AUROC of 0.87 internally and 0.84 across 20,053 external patients, though its precision-recall AUC fell from 0.66 to 0.50 outside the development site. A sepsis-prediction model told a cautionary story: an XGBoost model scored an AUROC of 0.82 in development but collapsed to 0.47 on external ICU data.", "Together, these findings point to a familiar pattern: strong internal performance for both LLMs and traditional ML models, but meaningfully weaker results once tested on new agentic tasks or external populations."], "refs": [{"title": "PhysicianBench: Evaluating LLM Agents in Real-World EHR Environments", "url": "https://arxiv.org/pdf/2605.02240"}, {"title": "ART: Action-based Reasoning Task Benchmarking for Medical AI Agents", "url": "https://arxiv.org/pdf/2601.08988"}, {"title": "Automated identification of radiotherapy treatment sites from unstructured physician notes", "url": "https://pubmed.ncbi.nlm.nih.gov/41914356/"}, {"title": "Evaluating the Efficacy of AI-Based Interactive Assessments Using Large Language Models for Depression Screening", "url": "https://formative.jmir.org/2026/1/e78401"}, {"title": "Machine learning predicts hepatocellular carcinoma risk from routine clinical data", "url": "https://doi.org/10.1158/2159-8290.CD-25-1323"}, {"title": "AI-augmented ECG for pre-echocardiography triage", "url": "https://esc365.escardio.org/journal/92469"}, {"title": "Machine Learning Model for Sepsis Prediction in Prolonged and Chronic Critical Illness", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12841784/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-17", "date": "2026-10-17", "title": "AI in Healthcare: Research Roundup — October 17, 2026", "excerpt": "Today's LLM additions leaned toward evaluation and evidence-mapping rather than new deployments. A JAMA Network Open study tested six commercial LLMs (including Claude…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "HealthTech", "ExternalValidation"], "body": ["Today's LLM additions leaned toward evaluation and evidence-mapping rather than new deployments. A JAMA Network Open study tested six commercial LLMs (including Claude Sonnet 4/4.6, Gemini 3 Pro, and GPT-5/GPT-5 mini) on 288 emergency department encounters to screen for missed diagnostic opportunities, finding true misses in 13.5% of cases and model AUCs ranging from 0.57 to 0.82 depending on the cohort, with physicians agreeing with 81.9% of flagged cases. A separate study evaluated DeepSeek-R1 on 7,435 Chinese emergency radiology reports, reaching 84.4% error detection with few-shot prompting versus 60.9% zero-shot against 12 board-certified radiologists. Three systematic/scoping reviews — covering LLMs in cardiology (33 studies), psychiatry, and mental-health prediction (201 studies on bias and clinical-utility reporting) — converged on the same message: performance is promising but inconsistent in high-stakes, acute scenarios, and clinical validation remains thin.", "On the ML/DL side, an XGBoost model for chronic kidney disease progression trained on Chinese retirement-survey data held up well across two independent Western cohorts (AUC 0.867–0.892), outperforming the standard Kidney Failure Risk Equation (AUC 0.745). A cardiac surgery complication model built at a Korean academic hospital maintained its discrimination across two external hospitals, though precision metrics dropped outside the development site — a reminder that external validation often exposes calibration gaps rather than confirming them away. A deep learning model combining dual-modality ultrasound video with clinical data classified benign versus malignant superficial lymphadenopathy with AUCs of 0.91–0.95 across five centers and two external test sets. Rounding out the day, a conference-reported random forest model for sepsis prediction in aneurysmal subarachnoid hemorrhage dropped from AUC 0.915 internally to 0.833 on external eICU data, and a five-algorithm ML comparison improved prognostic prediction for NSTEMI patients across a five-hospital Chinese cohort.", "Taken together, today's crop reinforces a now-familiar pattern: internal performance numbers look strong across both LLM and classical ML approaches, but the external and cross-population validation step continues to be where real-world confidence is won or lost."], "refs": [{"title": "Screening for Missed Opportunities for Diagnosis in the ED Using eTriggers and Large Language Models", "url": "https://doi.org/10.1001/jamanetworkopen.2026.20939"}, {"title": "Error Detection in Emergency Radiology Reports Using a Large Language Model (DeepSeek-R1)", "url": "https://www.jmir.org/2026/1/e86841"}, {"title": "Large Language Models in Cardiology: A Systematic Review", "url": "https://cardio.jmir.org/2026/1/e76734"}, {"title": "A Cross-Ethnicity Validated Machine Learning Model for the Progression of Chronic Kidney Disease", "url": "https://doi.org/10.3390/jcm15020825"}, {"title": "Machine Learning Model for Predicting Severe Immediate Postoperative Complications After Cardiac Surgery", "url": "https://doi.org/10.1186/s12871-026-03841-9"}, {"title": "Deep Learning Analysis of Dual-Modality US Videos for Characterization of Superficial Lymphadenopathy", "url": "https://doi.org/10.1148/ryai.260131"}, {"title": "Machine Learning Models for Sepsis Prediction in Aneurysmal Subarachnoid Hemorrhage (AAN 2026)", "url": "https://index.mirasmart.com/AAN2026/PDFfiles/AAN2026-000250.html"}], "lang": "en", "source": "ai"}, {"id": "ph-2026-10-09-rationalist-proof", "date": "2026-10-16", "title": "রেশনালিস্ট প্রমাণ (এডওয়ার্ড ফেজার)", "title_en": "The Rationalist Proof (Edward Feser, Five Proofs of the Existence of God)", "excerpt": "ধরুন, আপনি রাতে একা বাসায় ফিরলেন, এবং রান্নাঘরে ঢুকে দেখলেন চুলার উপর একটা কেটলিতে পানি টগবগ করে ফুটছে। আপনার মাথায় কী আসবে? \"কেটলিটা এমনি এমনি ফুটছে, এর পেছনে কোনো…", "theme": "faith", "cats": ["স্রষ্টার অস্তিত্বের যুক্তি", "দর্শন"], "body": ["ধরুন, আপনি রাতে একা বাসায় ফিরলেন, এবং রান্নাঘরে ঢুকে দেখলেন চুলার উপর একটা কেটলিতে পানি টগবগ করে ফুটছে। আপনার মাথায় কী আসবে? \"কেটলিটা এমনি এমনি ফুটছে, এর পেছনে কোনো কারণ নেই\" — এই কথাটা আপনার মাথায় আসবে না। আপনি সঙ্গে সঙ্গে ভাববেন, কেউ একজন চুলা জ্বালিয়েছে। এমনকি যদি বাসায় কেউ না থাকে, আপনি ধরে নেবেন কোনো টাইমার সেট করা ছিল, বা অন্য কোনো ব্যাখ্যা আছে। \"এটা এমনি এমনি হয়েছে, কোনো কারণ খোঁজার দরকার নেই\" — এই উত্তরটা আমরা কখনো মেনে নিই না। আমাদের মন সহজাতভাবেই বিশ্বাস করে, যা কিছু ঘটে বা যা কিছু আছে, তার পেছনে একটা ব্যাখ্যা থাকতেই হবে। এই সহজাত বিশ্বাসটাকে দর্শনের ভাষায় বলা হয় \"পর্যাপ্ত কারণের নীতি\" বা \"প্রিন্সিপাল অব সাফিসিয়েন্ট রিজন\" (Principle of Sufficient Reason, সংক্ষেপে PSR)। এবং এই নীতিটাকে ভিত্তি করে দার্শনিক এডওয়ার্ড ফেজার তাঁর \"Five Proofs of the Existence of God\" বইয়ের পঞ্চম ও শেষ প্রমাণটা দাঁড় করিয়েছেন — যাকে বলা হয় \"রেশনালিস্ট প্রমাণ\" (The Rationalist Proof)। আজ আমরা এই যুক্তিটা নিয়েই কথা বলব।", "প্রথমে এই নীতিটা একটু ভালোভাবে বুঝে নেওয়া যাক। লাইবনিজ (Gottfried Leibniz) নামের জার্মান দার্শনিক এই নীতিটাকে বিখ্যাত করেছিলেন — তাঁর ভাষায়, প্রতিটা সত্য ঘটনার একটা পর্যাপ্ত ব্যাখ্যা থাকতে হবে, নাহলে সেটা সত্য হতো না। ফেজার অবশ্য লাইবনিজের চেয়ে একটু সংকীর্ণ, পুরনো ধাঁচের সংস্করণ ব্যবহার করেন, যাকে বলা হয় \"স্কলাস্টিক\" সংস্করণ। এটা বলে যে, যা কিছু অস্তিত্বশীল, তার অস্তিত্বের একটা পর্যাপ্ত, উপযুক্ত ব্যাখ্যা থাকতে হবে, হয় তার নিজের ভেতরেই, না হয় তার বাইরে অন্য কিছুতে। কেন এই পার্থক্যটা গুরুত্বপূর্ণ? কারণ লাইবনিজের সংস্করণ সব \"সত্য\" বা \"ফ্যাক্ট\" নিয়ে কথা বলে, যা থেকে কিছু কঠিন যৌক্তিক জটিলতা তৈরি হয় — আমরা একটু পরে সেটা দেখব। ফেজার তাঁর সংস্করণটাকে শুধু \"অস্তিত্ব\" এর মধ্যে সীমাবদ্ধ রাখেন, যাতে যুক্তিটা আরও শক্ত ভিত্তিতে দাঁড়ায়।", "এখন দুটো শব্দ বুঝে নেওয়া যাক — \"আপতিক\" (contingent) আর \"আবশ্যিক\" (necessary)। আপতিক সত্তা মানে এমন কিছু, যা থাকতে পারত, না-ও থাকতে পারত। আপনার হাতের মোবাইল ফোনটা আপতিক। অর্থাৎ,  এটা না থাকলেও পারত, অন্য রকম হতে পারত, বা কখনো তৈরি না-ও হতে পারত। আপনি নিজেও আপতিক। কেননা,  আপনার মা-বাবা না মিলিত হলে আপনি জন্মাতেন না। পুরো মহাবিশ্বও, বিজ্ঞান যতদূর বলে, আপতিক। এটা অন্যভাবে হতে পারত, বা নাও থাকতে পারত। অন্যদিকে আবশ্যিক সত্তা মানে এমন কিছু, যার না-থাকা অসম্ভব। যে নিজের স্বভাবগুণেই আছে, কারো উপর নির্ভর করে নেই। গণিতের সত্যকে অনেকে এরকম মনে করেন, যেমন ২+২=৪ — এটা যেকোনো পরিস্থিতিতেই সত্য, এর জন্য বাইরের কোনো কারণ লাগে না।", "এবার মূল যুক্তিটা দেখা যাক। ধরুন একটা মালগাড়ির লম্বা লাইন, একটা বগি আরেকটা বগিকে টানছে, সেটা আরেকটাকে এবং এভাবে চলছে। এখন আপনাকে যদি বলা হয়, এই বগির লাইন অসীম দীর্ঘ, কোনো শুরু নেই, তাহলেও একটা প্রশ্ন থেকে যায়। তা হল পুরো লাইনটা আসলে চলছে কেন? প্রতিটা বগি তো শুধু সামনের বগির উপর নির্ভর করে, নিজের মধ্যে চলার ক্ষমতা কারো নেই। তাই লাইনটা যত লম্বাই হোক, যদি তার মধ্যে একটাও আসল ইঞ্জিন না থাকে, যার নিজের শক্তি আছে ও যাকে টানতে হয় না, তাহলে পুরো লাইনটাই নিশ্চল পড়ে থাকবে। ঠিক এই যুক্তিই রেশনালিস্ট প্রমাণের মূলে। প্রতিটা আপতিক সত্তার অস্তিত্বের ব্যাখ্যা থাকে আরেকটা সত্তায়- আপনার অস্তিত্বের ব্যাখ্যা আপনার মা-বাবায়, তাদের ব্যাখ্যা তাদের মা-বাবায়, এভাবে চলতেই থাকে। কিন্তু সব আপতিক সত্তাকে একসাথে নিয়ে, একটা পুরো \"সমষ্টি\" (totality) কল্পনা করুন — অতীত, বর্তমান, ভবিষ্যতের সব আপতিক জিনিস মিলিয়ে। এই পুরো সমষ্টিটাও আপতিক, কারণ এর মধ্যে প্রতিটা সদস্যই আপতিক। তাহলে এই সমষ্টিরও একটা ব্যাখ্যা লাগবে। কিন্তু সেই ব্যাখ্যাটা আরেকটা আপতিক সত্তা দিয়ে দেওয়া যাবে না। কারণ তাহলে সেই সত্তাটাও তো সমষ্টির মধ্যেই পড়ে যাচ্ছে, এবং সমষ্টি নিজেকে নিজে ব্যাখ্যা করছে, যা সার্কুলার বা চক্রাকার যুক্তি হয়ে যায়। তাই শেষ পর্যন্ত এমন একটা সত্তা থাকতেই হবে, যে নিজেই আবশ্যিক। যার অস্তিত্বের উৎস নিজের মধ্যেই আছে, কোনো বাইরের ব্যাখ্যার মুখাপেক্ষী নয়।", "এখানেই যুক্তিটা থেমে যায় না। ফেজার তাঁর বইয়ে একটা দুই-ধাপের পদ্ধতি অনুসরণ করেন — প্রথমে এমন একটা সত্তার অস্তিত্ব প্রমাণ করা, তারপর দেখানো যে সেই সত্তার কী কী গুণ থাকতেই হবে। এই আবশ্যিক সত্তাকে একমাত্র হতে হবে। কারণ,  যদি দুটো আবশ্যিক সত্তা থাকত, তাহলে তাদের মধ্যে পার্থক্য করার মতো অন্তত একটা বৈশিষ্ট্য থাকতে হতো, এবং সেই পার্থক্যটার একটা ব্যাখ্যা দরকার হতো, যা আবশ্যিক সত্তার সংজ্ঞার সাথে সাংঘর্ষিক। একইভাবে এটাকে হতে হবে সরল বা অযৌগিক (simple)। অর্থাৎ এর মধ্যে আলাদা আলাদা অংশ থাকতে পারবে না, কারণ অংশ থাকলে প্রশ্ন আসে, এই অংশগুলো একসাথে জোড়া লাগল কেন, এবং সেই জোড়া লাগানোর জন্যও একটা বাইরের ব্যাখ্যা লাগবে। এটাকে হতে হবে অপরিবর্তনীয় ও চিরন্তন, কারণ পরিবর্তন মানেই আগে না থাকা একটা সম্ভাবনা বাস্তবে রূপ নেওয়া, যার জন্য বাইরের কারণ দরকার। এই সব গুণ মিলিয়ে যা দাঁড়ায়, তা ঐতিহ্যগতভাবে যাকে বলা হয় ঈশ্বর, রেশনালিস্ট দার্শনিকরা তার দিকেই পৌঁছান।", "এখানে একটা মজার ঐতিহাসিক বাঁক আছে। লাইবনিজ এই যুক্তি দিয়ে একজন ব্যক্তিগত, সৃষ্টিকর্তা ঈশ্বরে পৌঁছেছিলেন। কিন্তু আরেক দার্শনিক স্পিনোজা (Baruch Spinoza), যিনিও পর্যাপ্ত কারণের নীতি মানতেন প্রবলভাবে, তিনি ভিন্ন পথে হেঁটে বলেছিলেন — এই আবশ্যিক সত্তাটাই হলো প্রকৃতি বা মহাবিশ্ব নিজে, কোনো আলাদা স্বর্গীয় ব্যক্তিত্ব নয়। এটা দেখায়, পর্যাপ্ত কারণের নীতি মানলেই যে সবাই একই উপসংহারে পৌঁছাবে, তা নয়। ফেজারের দ্বিতীয় ধাপের যুক্তিগুলো (একত্ব, সরলতা, ইত্যাদি) ঠিক এই ফাঁকটাই বন্ধ করার চেষ্টা করে, যাতে দেখানো যায় আবশ্যিক সত্তাটা ভৌত মহাবিশ্বের মতো যৌগিক, পরিবর্তনশীল কিছু হতে পারে না।", "এখন আসি সবচেয়ে গুরুত্বপূর্ণ আপত্তিগুলোর দিকে, কারণ এই যুক্তি একেবারে বিনা প্রতিরোধে পার হয়ে যায়নি। সবচেয়ে প্রচলিত আপত্তিটা দিয়েছেন দার্শনিক বার্ট্রান্ড রাসেল (Bertrand Russell) এবং পরে ডেরেক পারফিট (Derek Parfit)। এটাকে বলা হয় \"নিরেট সত্য\" বা \"ব্রুট ফ্যাক্ট\" আপত্তি। তাঁদের বক্তব্য হলো, কোথাও না কোথাও ব্যাখ্যার চেইন থামতেই হয়, তাহলে কেন সেটা মহাবিশ্ব বা তার মৌলিক উপাদানগুলোতেই থেমে যাবে না? কেন আমাদের আরও এক ধাপ এগিয়ে ঈশ্বর পর্যন্ত যেতে হবে? মহাবিশ্ব হয়তো শুধু আছে, এটাই চূড়ান্ত সত্য, এর পেছনে আর কোনো ব্যাখ্যা খোঁজার দরকার নেই। ফেজারের জবাব হলো, এটা একরকম বেছে বেছে সন্দেহবাদিতা। আমরা কখনো একটা চায়ের কাপ বা একটা পাথরের ব্যাপারে বলি না যে \"এটা এমনি এমনি আছে, কোনো কারণ নেই\", তাহলে পুরো মহাবিশ্বের জন্য আমরা সেই ছাড়টা কেন দেব, শুধু এটা বড় বলে? তাছাড়া ফেজার আরও এক ধাপ এগিয়ে বলেন, যদি আমরা মেনে নিই যে কিছু জিনিস একেবারে বিনা কারণে ঘটতে বা থাকতে পারে, তাহলে আমাদের নিজের যুক্তি-তর্ক করার ক্ষমতার উপরও প্রশ্ন ওঠে। কারণ তখন আমাদের সিদ্ধান্তগুলো প্রকৃতপক্ষে আমাদের যুক্তির সাথে সম্পর্কিত কিনা, তা নিশ্চিত থাকে না। সমালোচকরা পাল্টা বলেন, এটা অতিরঞ্জিত তুলনা — ছোট ছোট জিনিসের জন্য ব্যাখ্যা খোঁজা আর গোটা বাস্তবতার জন্য ব্যাখ্যা খোঁজা, এই দুটো একই মাপের প্রশ্ন নয়।", "দ্বিতীয় আপত্তিটা এসেছে দার্শনিক পিটার ভ্যান ইনওয়াগেনের (Peter van Inwagen) কাছ থেকে, এবং এটা টেকনিক্যালি বেশ জটিল। তাঁর যুক্তি হলো, যদি পর্যাপ্ত কারণের নীতি সব ফ্যাক্টের উপর প্রয়োগ করা হয়, তাহলে সব আপতিক ফ্যাক্ট মিলিয়ে একটা \"মহা-সংযুক্ত ফ্যাক্ট\" কল্পনা করুন। এই মহা-ফ্যাক্টেরও একটা ব্যাখ্যা লাগবে। কিন্তু সেই ব্যাখ্যা যদি আবশ্যিক কিছু হয়, তাহলে মনে হয় পুরো মহা-ফ্যাক্টটাই আসলে আবশ্যিক হয়ে যাচ্ছে, অর্থাৎ পৃথিবীতে যা ঘটেছে সবকিছুই অবশ্যম্ভাবী ছিল। এটাকে বলা হয় \"মডাল ফেটালিজম\" বা নিয়তিবাদ, যা আমাদের স্বাধীন ইচ্ছা ও সত্যিকারের সম্ভাবনার ধারণার সাথে সাংঘর্ষিক মনে হয়। আর যদি ব্যাখ্যাটা আপতিক কিছু হয়, তাহলে সেটা তো মহা-ফ্যাক্টেরই অংশ, তাই এটা নিজেকে নিজে ব্যাখ্যা করছে। অর্থাৎ, আবারও চক্রাকার সমস্যা। দার্শনিক আলেক্সান্ডার প্রুস (Alexander Pruss) এই আপত্তির বিরুদ্ধে পুরো একটা বই লিখেছেন, যেখানে তিনি যুক্তি দেন যে \"একটা সংযুক্ত ফ্যাক্টের ব্যাখ্যা থাকলে তার প্রতিটা অংশেরও আলাদা ব্যাখ্যা থাকতে হবে\" — এই অনুমানটাই প্রশ্নসাপেক্ষ, এবং এটা বাতিল করলে সমস্যাটা এড়ানো সম্ভব।", "তৃতীয় আপত্তিটা আসে পদার্থবিজ্ঞান থেকে। কোয়ান্টাম মেকানিক্সে কিছু ঘটনা, যেমন রেডিওঅ্যাকটিভ পরমাণুর ক্ষয় (decay), সম্পূর্ণ এলোমেলো বা সম্ভাবনাভিত্তিক মনে হয় — কোনো নির্দিষ্ট কারণ ছাড়াই একটা পরমাণু একটা নির্দিষ্ট মুহূর্তে ভেঙে যায়, আগে নয়, পরেও নয়। যদি প্রকৃতিতে সত্যিই এমন ঘটনা থাকে যার কোনো কারণ নেই, তাহলে পর্যাপ্ত কারণের নীতি অন্তত কিছু ক্ষেত্রে ভুল প্রমাণিত হয়। এর জবাবে কেউ কেউ বলেন, কোয়ান্টাম অনিশ্চয়তা আমাদের জ্ঞানের সীমাবদ্ধতা মাত্র, বাস্তবতায় সত্যিকারের কারণহীনতা নয়।  অর্থাৎ হয়তো একটা অন্তর্নিহিত ব্যাখ্যা আছে, আমরা এখনো সেটা জানি না। কিন্তু এটা স্বীকার করতেই হবে, এটা একটা অমীমাংসিত বৈজ্ঞানিক প্রশ্ন, দার্শনিক তর্কে সহজে মিটে যাওয়ার মতো নয়।", "সবশেষে আরেকটা স্বাভাবিক প্রশ্ন থাকে — এমনকি যদি আমরা মেনেও নিই একটা আবশ্যিক সত্তা থাকতেই হবে, কেন সেটাকে ধর্মের ঈশ্বরের মতো একজন ব্যক্তিত্ব, জ্ঞানী, ইচ্ছাশক্তিসম্পন্ন সত্তা বলে ভাবতে হবে? কেন সেটা স্পিনোজার মতো নিরাকার প্রকৃতি নিজেই নয়, বা পদার্থবিজ্ঞানের মৌলিক নিয়মগুলোই নয়? ফেজার ও তাঁর মতো দার্শনিকরা দ্বিতীয় ধাপের যুক্তি দিয়ে এটা খণ্ডাতে চান। তাঁদের মতে ভৌত মহাবিশ্ব বা তার নিয়মগুলো যৌগিক, পরিবর্তনশীল, সময়ের সাথে বাঁধা, তাই এগুলো নিজেই আবশ্যিক সত্তার শর্ত পূরণ করে না।"], "source": "philosophy"}, {"id": "ai-2026-10-16", "date": "2026-10-16", "title": "AI in Healthcare: Research Roundup — October 16, 2026", "excerpt": "Today's LLM-related additions focused heavily on clinical decision support and workflow tasks rather than autonomous diagnosis. Google Research's SymptomAI, a Gemini…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "DigitalHealth", "ClinicalAI", "HealthTech"], "body": ["Today's LLM-related additions focused heavily on clinical decision support and workflow tasks rather than autonomous diagnosis. Google Research's SymptomAI, a Gemini Flash 2.0-based conversational agent, ran a national-scale study of 13,917 participants and produced differential diagnoses that independent clinicians judged more accurate than their own, with agents that conducted a dedicated symptom interview before diagnosing outperforming simpler user-guided chat. A JMIR study tested DeepSeek-R1, Gemini 2.5 Pro, and GPT-4o on liver, lung, and breast radiology reports, finding that adding progressively more clinical context produced only a modest numeric gain in diagnostic performance versus radiologists. Elsewhere, LLMs were put to narrower, supportive tasks: generating personalized patient question lists from EHR lab data, assisting endodontic symptom screening, and supporting oncology nursing decisions, with all three studies emphasizing the continued need for clinician oversight.", "On the ML/DL side, a knowledge-augmented framework (KAMELEON) combined LLM-generated clinical reasoning with classical ML classifiers on MIMIC-III data, reaching AUROC of 0.85 for 30-day readmission and 0.92 for in-hospital mortality — and removing the LLM reasoning component dropped readmission AUROC to 0.70, highlighting how much of the gain came from the language-model layer. In imaging, a multitask EfficientNet-B0 model detected dementia presence (AUC 0.95) and staged its severity from brain MRI in one pass, while a deep learning model using MRI and transfer learning predicted neoadjuvant chemotherapy response and 5-year survival in adolescent osteosarcoma patients (C-index 0.831, small test set). Two prognostic/diagnostic comparisons rounded out the day: an XGBoost model outperformed Cox regression and random survival forests for prostate cancer survival prediction using SEER data, and an Extra Trees model screened for metabolic dysfunction-associated steatotic liver disease with AUC 0.879 internally and 0.822 on external Korean validation data.", "Across both topics, the throughline is validation against real comparators — clinicians, radiologists, and classical statistical models — with external or held-out testing increasingly treated as a baseline expectation rather than an afterthought."], "refs": [{"title": "SymptomAI: Toward a Conversational AI Agent for Everyday Symptom Assessment", "url": "https://arxiv.org/abs/2605.04012"}, {"title": "Incremental Diagnostic Value of Clinical Information for LLMs Across Multiple Organs", "url": "https://www.jmir.org/2026/1/e94904"}, {"title": "Knowledge-Augmented Large Language Model for Multimodal EHR-Based Risk Prediction (KAMELEON)", "url": "https://ai.jmir.org/2026/1/e88356"}, {"title": "A Multi-Task Deep Learning Model for Dementia Presence and Severity Prediction from Brain MRI", "url": "https://journal.gerontechnology.org/currentIssueContent.aspx?aid=4960"}, {"title": "MRI-Based Deep Learning Model for Neoadjuvant Chemotherapy Response and Survival in Osteosarcoma", "url": "https://www.wjgnet.com/2644-3228/full/v7/i1/116460.htm"}, {"title": "Comparison and Interpretability of Machine Learning Algorithms to Predict Survival of Patients With Prostate Cancer", "url": "https://www.urotoday.com/recent-abstracts/urologic-oncology/prostate-cancer/171577-comparison-and-interpretability-of-machine-learning-algorithms-to-predict-survival-of-patients-with-prostate-cancer.html"}, {"title": "Explainable Machine Learning Model for Prediction of Metabolic Dysfunction-Associated Steatotic Liver Disease", "url": "https://scholars.hkbu.edu.hk/en/publications/development-and-validation-of-an-explainable-machine-learning-mod/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-15", "date": "2026-10-15", "title": "AI in Healthcare: Research Roundup — October 15, 2026", "excerpt": "Today's LLM-related additions centered on using language models as general-purpose infrastructure rather than narrow chatbots. An npj Digital Medicine study found that…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "DigitalHealth", "ClinicalAI", "HealthTech"], "body": ["Today's LLM-related additions centered on using language models as general-purpose infrastructure rather than narrow chatbots. An npj Digital Medicine study found that embeddings from general-purpose LLMs, produced by converting structured EHR codes into plain-language text, matched or exceeded a specialized EHR foundation model (CLMBR-T-Base) across 15 clinical prediction tasks, though at higher computational cost. On the patient-facing side, Verily Life Sciences published a predeployment validation of its LLM-based symptom-guidance tool, tested on 772 synthetic cases against five physicians' level-of-care judgments; the system kept overtriage within acceptable limits but missed its undertriage targets, underscoring the gap between simulation and real-world readiness. A JMIR Formative Research study tested a ChatGPT-based conversational version of the Beck Depression Inventory against the standard PHQ-9 in 115 participants, finding moderate correlation and diagnostic agreement.", "On the ML/DL side, three disease-specific models reached notable discrimination. A Journal of Proteome Research study combined serum metabolomics with an XGBoost classifier to diagnose hepatocellular carcinoma, achieving an AUC of 0.876 internally and 0.813 in external validation, outperforming alpha-fetoprotein for early-stage detection. A Clinics (Sao Paulo) nomogram used LASSO-selected clinical variables to predict ICU sepsis mortality, reaching AUC 0.900 in training and 0.796 in validation. A Clinical Ophthalmology study trained an EfficientNet-B2 model with a weighted loss function to detect diabetic kidney disease from retinal images, aiming at a non-invasive screening alternative.", "Taken together, today's additions reflect a continued split: LLMs are being validated as backbone infrastructure and triage support rather than diagnosis engines, while disease-specific ML/DL models keep pushing incremental gains in discrimination over existing clinical scores."], "refs": [{"title": "Large Language Models are Powerful Electronic Health Record Encoders", "url": "https://pubmed.ncbi.nlm.nih.gov/42410244/"}, {"title": "Patient-Facing AI System for Symptom Guidance Using Simulated Encounters and Physician Review", "url": "https://formative.jmir.org/2026/1/e103419"}, {"title": "AI-Based Interactive Assessments Using LLMs for Depression Screening", "url": "https://formative.jmir.org/2026/1/e78401"}, {"title": "The Combination of Machine Learning and Metabolomics for the Clinical Diagnosis of Hepatocellular Carcinoma", "url": "https://pubmed.ncbi.nlm.nih.gov/42126022/"}, {"title": "Personalized sepsis mortality prediction: An interpretable machine learning nomogram", "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12924733/"}, {"title": "Deep Learning-Based Model for Detection of Diabetic Kidney Disease from Retinal Imaging", "url": "https://www.dovepress.com/article/download/114206"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-14", "date": "2026-10-14", "title": "AI in Healthcare: Research Roundup — October 14, 2026", "excerpt": "Today's LLM-related additions focused on agentic systems and clinical documentation. Two arXiv papers explored agentic AI architectures for hospital workflows: one…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "AgenticAI", "LLM", "MachineLearning", "ClinicalAI", "DigitalHealth"], "body": ["Today's LLM-related additions focused on agentic systems and clinical documentation. Two arXiv papers explored agentic AI architectures for hospital workflows: one proposed an \"agentic operating system\" built on the OpenClaw framework, combining restricted execution environments with page-indexed memory, and tested it on a MIMIC-IV benchmark where its retrieval approach matched a RAG baseline on recall (0.877 vs. 0.876) while more than doubling precision (0.779 vs. 0.352). The other evaluated human-guided agentic AI on the AgentDS Healthcare benchmark, finding that human input at key decision points improved performance by 0.065 F1 over fully automated baselines, reaching Macro-F1 of 0.90 for 30-day readmission prediction. A Radiology: Artificial Intelligence study (MIRA) fine-tuned an LLM on 1.87 million Chinese radiology reports to draft impressions, outperforming GPT-4o in blinded comparisons and cutting drafting time, though accuracy dropped on external data. A JMIR AI feasibility study at Imperial College Healthcare used template-based GPT-4 prompting to draft discharge summary sections, rating them 78-89% complete and accurate on a small test set.", "On the ML/DL side, two atrial fibrillation prediction studies stood out. A Heart Rhythm paper introduced AIRE-AF, a CNN trained on over a million ECGs, which beat the standard CHARGE-AF clinical score for predicting incident AF (C-index 0.750) and performed best when combined with it externally (0.768). A separate Swedish primary care study used stochastic gradient boosting on diagnostic codes from over 42,000 new-onset AF cases and 427,000 matched controls to help flag undiagnosed patients. An arXiv study benchmarked XGBoost against the FIB-4 score for early liver cirrhosis prediction in fatty liver disease patients, outperforming FIB-4 at 1-, 2-, and 3-year horizons (AUCs of 0.81, 0.73, and 0.69).", "Today's work shows two parallel tracks: LLMs moving toward agentic, multi-step clinical workflows rather than single-shot tasks, and ML risk models continuing to chip away at specific clinical benchmarks like CHARGE-AF and FIB-4."], "refs": [{"title": "When OpenClaw Meets Hospital: an agentic operating system for clinical workflows", "url": "https://arxiv.org/abs/2603.11721"}, {"title": "Human-Guided Agentic AI for Multimodal Clinical Prediction (AgentDS Healthcare Benchmark)", "url": "https://arxiv.org/abs/2602.19502"}, {"title": "Fine-Tuned LLMs for Automated Radiology Impression Generation (MIRA)", "url": "https://pubs.rsna.org/doi/10.1148/ryai.250714"}, {"title": "Real-World Implementation of LLMs for Writing Clinical Discharge Summaries", "url": "https://ai.jmir.org/2026/1/e88816"}, {"title": "Prediction of incident atrial fibrillation: AIRE-AF vs. CHARGE-AF", "url": "https://pubmed.ncbi.nlm.nih.gov/40850589/"}, {"title": "Machine learning model to recognize atrial fibrillation from diagnostic codes in Swedish primary care", "url": "https://doi.org/10.1186/s12911-026-03491-4"}, {"title": "Early Prediction of Liver Cirrhosis vs. the FIB-4 Score", "url": "https://arxiv.org/abs/2601.00175"}], "lang": "en", "source": "ai"}, {"id": "ph-2026-10-06-thomistic-proof", "date": "2026-10-13", "title": "থমিস্টিক প্রমাণ (এডওয়ার্ড ফেজার)", "title_en": "The Thomistic Proof (Edward Feser, Five Proofs of the Existence of God)", "excerpt": "আপনি কি কখনো কোনো জিনিসের পুরো নকশা মাথায় এঁকে ফেলেছেন, যে জিনিসটা বাস্তবে নেই?", "theme": "faith", "cats": ["স্রষ্টার অস্তিত্বের যুক্তি", "দর্শন"], "body": ["আপনি কি কখনো কোনো জিনিসের পুরো নকশা মাথায় এঁকে ফেলেছেন, যে জিনিসটা বাস্তবে নেই?", "ধরুন, আপনি একটা উড়ন্ত গাড়ির কথা কল্পনা করলেন। রঙ কী হবে, চাকা কোথায় থাকবে, কীভাবে উড়বে, ভেতরে কী কী থাকবে — সবকিছু নিখুঁতভাবে বর্ণনা করে ফেললেন। এখন প্রশ্ন হলো, এই বর্ণনা থেকেই কি বোঝা যায় গাড়িটা আসলে আছে কিনা? না। আপনি পুরো জিনিসটা কী, তা জানলেন, কিন্তু জিনিসটা সত্যিই আছে কিনা, সেটা সম্পূর্ণ আলাদা একটা প্রশ্ন। এই ছোট্ট পার্থক্যটাই (অর্থাৎ, \"জিনিসটা কী\" আর \"জিনিসটা আছে কিনা\") একটা প্রাচীন যুক্তির ভিত্তি, যা দিয়ে বহু দার্শনিক ঈশ্বরের অস্তিত্ব প্রমাণ করার চেষ্টা করেছেন। আজ আমরা কথা বলব থমাস অ্যাকুইনাসের দর্শনের উপর ভিত্তি করে আধুনিক দার্শনিক এডওয়ার্ড ফেজার তাঁর \"Five Proofs of the Existence of God\" বইয়ে যে যুক্তিটা দিয়েছেন তা নিয়ে। একে বলা হয় \"থমিস্টিক প্রমাণ\" (Thomistic Proof)।", "প্রথমে বুঝে নেওয়া যাক দুটো শব্দ। দর্শনের ভাষায় একটা জিনিসের \"স্বরূপ\" (essence) মানে হলো সেই জিনিসটা আসলে কী — তার সংজ্ঞা, তার ধরন, তাকে অন্য সবকিছু থেকে আলাদা করে তোলে এমন বৈশিষ্ট্য। আর \"অস্তিত্ব\" (existence) মানে হলো সেই জিনিসটা বাস্তবে আছে কিনা। সিংহের কথা ভাবুন। সিংহ কী? চার পায়ের, গর্জনকারী, মাংসাশী একটি প্রাণী। এটা আপনি পুরোপুরি জানেন। এই জ্ঞানটা থাকার জন্য আপনার জানার দরকার নেই পৃথিবীতে এখন সত্যিই কোনো সিংহ জীবিত আছে কিনা। এখন ধরুন ইউনিকর্নের কথা। একশিংওয়ালা ঘোড়ার মতো একটি কাল্পনিক প্রাণী। আপনি তার স্বরূপও পুরোপুরি বর্ণনা করতে পারেন, কিন্তু বাস্তবে এমন প্রাণী নেই। তাহলে দেখা যাচ্ছে, একটা জিনিসের \"কী\" এবং তা \"আছে কিনা\"  এই দুটো প্রশ্ন একরকম নয়। এই পার্থক্যকে অ্যাকুইনাস এবং ফেজার বলছেন \"বাস্তব পার্থক্য\" (real distinction)। অর্থাৎ, এটা শুধু আমাদের মনের খেলা নয়, এটা বাস্তবতার মধ্যেই লুকিয়ে থাকা একটা সত্যিকারের ফারাক।", "এখন প্রশ্ন হলো — যদি একটা জিনিসের স্বরূপের মধ্যে অস্তিত্ব অন্তর্নিহিত না থাকে, তাহলে সে অস্তিত্ব পায় কোথা থেকে? এখানেই যুক্তির মূল বক্তব্য শুরু। যে জিনিসের স্বরূপ আর অস্তিত্ব আলাদা, তার অস্তিত্বটা তাকে বাইরে থেকে কেউ না কেউ দিচ্ছে এবং এই দেওয়াটা শুধু একবারের জন্য নয়, বরং প্রতি মুহূর্তে, যতক্ষণ জিনিসটা টিকে থাকছে।", "এই \"প্রতি মুহূর্তে\" ব্যাপারটা একটা উদাহরণ দিয়ে বোঝা সহজ। একটা বাল্ব জ্বলছে কারণ বিদ্যুৎ তার মধ্য দিয়ে প্রবাহিত হচ্ছে। বিদ্যুৎ বন্ধ করে দিলে বাল্ব সঙ্গে সঙ্গে নিভে যায় — বাল্বের নিজের মধ্যে আলো জ্বালিয়ে রাখার কোনো ক্ষমতা নেই, সে শুধু বিদ্যুতের উপর নির্ভরশীল, এবং সেই নির্ভরতা প্রতিটা সেকেন্ডে চলমান। এটা একটা বিলিয়ার্ড বলকে ঠেলে দেওয়ার মতো নয়, যেখানে একবার ঠেলা দিলে বল নিজের গতিতে চলতে থাকে। অ্যাকুইনাসের যুক্তি অনুযায়ী, যে কোনো জিনিসের অস্তিত্বও এরকম। এটা একবার \"চালু\" করে দিলে নিজে নিজে চলতে থাকে না, বরং প্রতি মুহূর্তে কোনো না কোনো উৎস থেকে অস্তিত্ব \"সরবরাহ\" পেতে হয়।", "এখন সেই উৎসটা কী? দুটো সম্ভাবনা। এক, সেই উৎসও হতে পারে এমন একটা জিনিস, যার নিজেরও স্বরূপ আর অস্তিত্ব আলাদা। মানে সেও নিজের অস্তিত্বের জন্য আরও কারো ওপর নির্ভরশীল। দুই, উৎসটা হতে পারে এমন কিছু, যার মধ্যে স্বরূপ আর অস্তিত্বে কোনো ফারাক নেই। অর্থাৎ, যার \"কী হওয়া\" আর \"থাকা\" একই জিনিস। এই দ্বিতীয় রকমের সত্তাকে বলা হয় \"স্বতঃনির্ভর স্বয়ংসম্পূর্ণ অস্তিত্ব\" (subsistent existence itself) — এমন একটা সত্তা, যার প্রকৃতিই হলো অস্তিত্বশীল হওয়া, যাকে অস্তিত্ব পাওয়ার জন্য কারো দিকে তাকাতে হয় না।", "যদি প্রথম সম্ভাবনাটাই সত্যি হয়। মানে প্রতিটা উৎসও আরেকটা নির্ভরশীল জিনিস হয়, তাহলে কী হবে? এখানে দুই রকম কার্যকারণ-শৃঙ্খলের মধ্যে ফেজার একটা গুরুত্বপূর্ণ পার্থক্য টানেন । একটা হলো \"পার সে\" (per se) শৃঙ্খল — যেখানে প্রতিটা ধাপ এই মুহূর্তে, একসঙ্গে কাজ করছে, একে অপরকে ধরে রেখেছে। যেমন একটা শিকলে বাঁধা ঝাড়বাতি- প্রথম কড়াটা দ্বিতীয়টাকে ধরে রাখছে, দ্বিতীয়টা তৃতীয়টাকে, এবং এটা সব একসঙ্গে, এই মুহূর্তে ঘটছে। যদি সবচেয়ে উপরের আংটাটা, যেটা ছাদের সাথে লাগানো, সরিয়ে ফেলা হয়, তাহলে পুরো শিকলটাই পড়ে যাবে। কোনো মধ্যবর্তী কড়ার নিজের মধ্যে ঝাড়বাতিটাকে ধরে রাখার ক্ষমতা নেই, তারা সবাই শুধু ওপরের শক্তিটা নিচে পাঠাচ্ছে। এর বিপরীতে আছে \"পার অ্যাক্সিডেন্স\" (per accidens) শৃঙ্খল। যেমন, বাপ-দাদার বংশ। দাদা মারা গেলেও বাবা জীবিত থাকতে পারে, বাবা মারা গেলেও সন্তান জীবিত থাকতে পারে। কারণ একবার জন্ম দেওয়ার কাজ শেষ হয়ে গেলে, আগের প্রজন্মের উপস্থিতি আর লাগে না। ফেজারের যুক্তি হলো, অস্তিত্ব দেওয়ার শৃঙ্খলটা প্রথম রকমের। অর্থাৎ, \"পার সে\" ধরনের। কারণ এটা প্রতি মুহূর্তে ঘটছে, অতীতের কোনো এক ঘটনা নয়। আর এই ধরনের শৃঙ্খল অসীম পর্যন্ত পেছানো যায় না, কারণ মধ্যবর্তী কোনো ধাপেরই নিজের ভেতরে অস্তিত্ব তৈরির ক্ষমতা নেই। তারা শুধু হাতবদল করছে। তাই শেষমেশ এমন একটা বিন্দুতে থামতেই হবে, যার নিজের মধ্যেই অস্তিত্ব আছে, যাকে ধরে রাখার জন্য কারো প্রয়োজন নেই। এই সত্তাকেই অ্যাকুইনাস এবং ফেজার বলছেন ঈশ্বর।", "এটা মনে রাখা জরুরি যে এই প্রমাণটা মহাবিশ্বের শুরুর কথা বলছে না। এটা \"কখন শুরু হলো\" প্রশ্নের উত্তর খুঁজছে না। এটা বলছে, এই মুহূর্তে, এখন, আপনার চারপাশের প্রতিটা জিনিস কেন অস্তিত্বে টিকে আছে, তার একটা ব্যাখ্যা থাকতে হবে। মহাবিশ্ব যদি অনন্তকাল ধরেই থাকত, তাতেও এই প্রশ্ন একইরকম থাকে — প্রতিটা জিনিসের নিজের স্বরূপে অস্তিত্ব অন্তর্ভুক্ত নয়, তাই তাকে বাইরে থেকে পাওয়াতে হবেই, চিরকাল ধরেই হোক বা না হোক।", "এখন আসি ভারসাম্যের দিকে। কারণ এই যুক্তিটা নিয়ে গুরুত্বপূর্ণ আপত্তিও আছে, এবং সেগুলো অগ্রাহ্য করার মতো নয়। দার্শনিক অ্যান্থনি কেনি (Anthony Kenny) একটা শক্তিশালী প্রশ্ন তুলেছেন। তাঁর মতে, \"স্বরূপ জানলেও অস্তিত্ব জানা যায় না\" — এই পর্যবেক্ষণটা আসলে আমাদের জ্ঞান বা ধারণা সম্পর্কে একটা সত্য, বাস্তবতার গঠন সম্পর্কে নয়। আমি ইউনিকর্নের ধারণা মাথায় রাখতে পারি অস্তিত্ব নিশ্চিত না করেই। কিন্তু এটা প্রমাণ করে না যে বাস্তব জিনিসের মধ্যে আসলেই দুটো আলাদা \"উপাদান\" আছে, একটা \"স্বরূপ-উপাদান\" আর একটা \"অস্তিত্ব-উপাদান\", যেগুলো জোড়া লাগানো হয়েছে। চতুর্দশ শতকের দার্শনিক জন বুরিদানও (John Buridan) প্রায় একই রকম আপত্তি তুলেছিলেন অনেক আগে। এই সমালোচকদের মূল বক্তব্য হলো- আমাদের মনের মধ্যে একটা ফাঁক থাকা, আর বাস্তবতার মধ্যে একটা ফাঁক থাকা, এই দুটো এক জিনিস নয়। একে বলা হয় \"রিইফিকেশন সমস্যা\" (reification problem)। অর্থাৎ, দুটো ধারণাকে যদি দুটো সত্যিকারের বস্তুর মতো ভাবা হয়, তাহলে ভুল হতে পারে। যেমন, \"পানির আকার\" আর \"পানির ভেজাতে পারা”- এই দুটো আলাদা শব্দ হলেও, এগুলো যে পানি থেকে আলাদা করে বের করে আনা যাবে এমন দুটো বস্তু নয়।", "থমিস্ট দার্শনিকদের জবাব হলো, তাঁরা স্বরূপ আর অস্তিত্বকে দুটো আলাদা \"বস্তু\" বলছেন না, যেগুলো লেগোর মতো জোড়া লাগানো হয়েছে। বরং তাঁরা বলছেন এগুলো একই সত্তার দুটো সত্যিকারের, কিন্তু অবিচ্ছেদ্য দিক। যেমন, একটা আপেলের রঙ আর তার আকৃতি সত্যিকারের দুটো আলাদা বৈশিষ্ট্য, কিন্তু আপনি আপেল থেকে রঙটাকে আলাদা একটা বস্তুর মতো কেটে বের করতে পারবেন না। সমালোচকরা পাল্টা বলেন, এই তুলনা যথেষ্ট নয়, কারণ রঙ আর আকৃতি দুটোই তো \"আছে\" বলে ধরে নেওয়া হচ্ছে প্রথম থেকেই। আসল প্রশ্ন হলো \"থাকা\" নিজেই কি এমন একটা বৈশিষ্ট্য, যা যুক্ত বা বিযুক্ত করা যায়? কিছু আধুনিক যুক্তিবিদ, যেমন বারট্রান্ড রাসেলের ঘরানার দার্শনিকরা, বলেন \"অস্তিত্ব\" আসলে জিনিসের কোনো গুণ বা বৈশিষ্ট্য নয়, বরং এটা একটা যৌক্তিক অবস্থা। তাই পুরো প্রশ্নটাই ভুল জায়গা থেকে শুরু হয়েছে। আরেকটা সাধারণ আপত্তি হলো, মহাবিশ্ব বা তার মধ্যেকার জিনিসগুলোর অস্তিত্ব হয়তো একটা \"নিরেট সত্য\" (brute fact)। মানে এর আর কোনো ব্যাখ্যা খোঁজার দরকার নেই, জিনিসগুলো আছে, এটাই যথেষ্ট। থমিস্টরা এর জবাবে বলেন, যদি কোনো জিনিসের নিজের স্বরূপেই অস্তিত্ব না থাকে, তাহলে তার “থাকা” বা “না-থাকা” দুটোই সমান সম্ভব ছিল (অর্থাৎ, contingent) এবং এরকম একটা জিনিস না থেকে কেনো থাকল, তা প্রশ্ন না করাটা অদ্ভুত লাগে। যদিও সমালোচকরা বলেন, এই \"অদ্ভুত লাগা\"টা একটা স্বজ্ঞা বা intuition, প্রমাণ নয়।", "তাহলে এই যুক্তি কতটা জোরালো? এটা নির্ভর করে একটা বিষয়ে — আপনি কি মেনে নেন যে \"স্বরূপ জানা আর অস্তিত্ব জানা আলাদা\" থেকে সত্যিই প্রমাণ হয় যে বাস্তবতার মধ্যে একটা সত্যিকারের ফারাক আছে, না এটা শুধু আমাদের ভাষা আর চিন্তার সীমাবদ্ধতা? অ্যাকুইনাসের অনুসারীরা মনে করেন এটা বাস্তবতার গভীরে লুকানো একটা সত্য, যেটা শেষ পর্যন্ত আমাদের এমন একটা সত্তার দিকে নিয়ে যায় যার অস্তিত্ব ধার করা নয়, বরং যে নিজেই অস্তিত্ব। সমালোচকরা মনে করেন, এই পুরো দালানটা একটা ভাষাগত কৌশলের উপর দাঁড়িয়ে আছে, যেটাকে বাস্তবতার একটা গভীর সত্য বলে ভুল করা হচ্ছে।", "আপনার চারপাশে একবার তাকান — আপনার হাতের চায়ের কাপ, জানালার বাইরের গাছ, এমনকি আপনি নিজে। এদের প্রত্যেকের একটা সম্পূর্ণ বর্ণনা দেওয়া সম্ভব, কিন্তু সেই বর্ণনার মধ্যে কোথাও লেখা নেই যে এটা থাকতেই হবে। তাহলে এরা আছে কেন, না থাকার বদলে? এই প্রশ্নটা কি আপনার কাছে একটা গভীর রহস্য মনে হয় না, যার একটা উত্তর থাকা উচিত?"], "source": "philosophy"}, {"id": "ai-2026-10-13", "date": "2026-10-13", "title": "AI in Healthcare: Research Roundup — October 13, 2026", "excerpt": "Today's LLM-related additions centered on clinical documentation and diagnosis support. A JMIR Medical Informatics study fine-tuned Mistral, Meditron, and Llama models…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Today's LLM-related additions centered on clinical documentation and diagnosis support. A JMIR Medical Informatics study fine-tuned Mistral, Meditron, and Llama models with parameter-efficient methods on 1,700 doctor-patient conversations to generate clinical notes; physician reviewers rated Llama3-8B and Mistral-7B as the most clinically coherent and accurate. A related BioNLP 2026 paper evaluated LLM-rephrased synthetic clinical notes at million-note scale, finding they preserve core clinical information for coarse-grained tasks but lose detail needed for fine-grained work like ICD coding. On the diagnosis side, a method called MERA paired LLM knowledge with contrastive ranking over disease candidates, reporting state-of-the-art diagnosis prediction on MIMIC-III and MIMIC-IV.", "Separately, an npj Digital Medicine study tested several LLMs on secure patient portal messages from diabetes patients to screen for depression and anxiety symptoms. Three of five models topped 90% on F1 and accuracy, with Llama 3.1 405B reaching 93% on both using zero-shot prompting alone.", "The ML/DL additions were dominated by systematic reviews taking stock of existing models. A meta-analysis of prostate cancer prediction models pooled results across 85 studies, reporting AUCs of 0.79-0.85 across survival, recurrence, and treatment-response endpoints. A separate review of 13 COPD exacerbation and readmission studies (sample sizes 110 to 113,786) found most models at moderate-to-high risk of bias and rarely externally validated. A broader review of ML models for hospital readmission, length of stay, and mortality flagged limited calibration reporting as a recurring gap across the field. On individual models, a Communications Medicine study built ElasticNet models predicting 12-month cognitive and functional decline in Alzheimer's disease and MCI from routinely collected data, externally validated on 741 ADNI trajectories with a cognition mean absolute error of 2.19.", "Across both topics, today's crop leans toward evaluation and synthesis — benchmarking LLM note quality and pooling evidence on existing ML risk models — rather than introducing dramatically new capability."], "refs": [{"title": "Clinical note generation from doctor-patient conversations using parameter-efficient fine-tuning LLMs", "url": "https://medinform.jmir.org/2026/1/e82545"}, {"title": "Systematic evaluation of synthetic clinical notes rephrased by LLMs at million-note scale", "url": "https://arxiv.org/abs/2605.17775"}, {"title": "Memorize and Rank (MERA): elevating LLMs for clinical diagnosis prediction", "url": "https://arxiv.org/abs/2501.17326"}, {"title": "Optimizing LLMs for detecting depression/anxiety symptoms in chronic disease patient communications", "url": "https://doi.org/10.1038/s41746-025-01969-5"}, {"title": "Prediction models in prostate cancer: a systematic review and meta-analysis", "url": "https://pubmed.ncbi.nlm.nih.gov/42147249/"}, {"title": "AI/ML driven prediction of COPD exacerbations and readmissions: a systematic review and meta-analysis", "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12756889/"}, {"title": "Machine learning models for predicting hospital readmission, length of stay, and mortality: a systematic review", "url": "https://doi.org/10.1016/j.irbm.2026.100961"}, {"title": "Predicting rates of cognitive and functional decline in Alzheimer's disease and MCI", "url": "https://doi.org/10.1038/s43856-026-01432-w"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-12", "date": "2026-10-12", "title": "AI in Healthcare: Research Roundup — October 12, 2026", "excerpt": "Today's LLM additions are mostly benchmarking work, probing how well current models actually reason rather than just answer. DiagnosisArena tested frontier reasoning…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Today's LLM additions are mostly benchmarking work, probing how well current models actually reason rather than just answer. DiagnosisArena tested frontier reasoning models on 1,113 real clinical case reports across 28 specialties and found accuracy as low as 18-51% depending on the model. CliniBench, presented at EACL 2026, compared 12 generative LLMs against 3 encoder-based classifiers on predicting discharge diagnoses from MIMIC-IV notes; the encoder-based classifiers still came out ahead overall. MediEval, an ACL 2026 Outstanding Paper, linked MIMIC-IV records to a clinical knowledge base to test whether LLMs can tell if a statement is both true and actually supported by the patient's chart, surfacing hallucinated support and \"truth inversion\" errors that a new fine-tuning method reduced substantially. A separate evaluation of GPT-5 as a multimodal clinical reasoner found it closing the gap with GPT-4o on mammography (10-40% improvement) but still only moderate in neuroradiology (44% accuracy). And a real-world test of ChatGPT, Gemini, and DeepSeek on 1,057 actual emergency department triage conversations in Korea found accuracy topping out at 73.8%, with wide swings even between versions of the same model family.", "On the ML/DL side, three new prognostic and risk models. An XGBoost model built on 58,839 pregnancies across three New York hospitals dynamically predicts preeclampsia 1-4 weeks before onset, peaking at AUC 0.863 in training (0.81-0.83 validated) at 34 weeks, with blood pressure the strongest signal. A SEER-based nomogram for muscle-invasive bladder cancer patients treated with trimodal therapy outperformed standard AJCC staging for predicting mortality-free survival, though its own authors note the accuracy gain is modest. And a six-algorithm comparison on 9,284 hospitalized patients in China found XGBoost best for liver cancer prediction, with validation AUC of 0.802 using only routine demographic and lab data.", "Together, today's LLM studies reinforce a consistent theme: benchmark performance on real clinical reasoning and triage tasks remains well below what's needed for autonomous use, while the ML risk models continue to show solid, if incremental, gains on well-defined prediction problems."], "refs": [{"title": "DiagnosisArena: benchmarking diagnostic reasoning for LLMs across 28 specialties", "url": "https://arxiv.org/abs/2505.14107"}, {"title": "CliniBench: clinical outcome prediction benchmark for generative vs. encoder-based LLMs", "url": "https://arxiv.org/abs/2509.26136"}, {"title": "MediEval: unified medical benchmark for patient-contextual, knowledge-grounded reasoning (ACL 2026 Outstanding Paper)", "url": "https://arxiv.org/abs/2512.20822"}, {"title": "Evaluating GPT-5 as a multimodal clinical reasoner", "url": "https://arxiv.org/abs/2603.04763"}, {"title": "Real-world ED triage performance of ChatGPT, Gemini, and DeepSeek", "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12403343/"}, {"title": "XGBoost model for dynamic, short-term preeclampsia prediction", "url": "https://doi.org/10.1001/jamanetworkopen.2026.0359"}, {"title": "Nomogram for mortality-free survival after trimodal therapy in bladder cancer", "url": "https://doi.org/10.1007/s00345-026-06217-3"}, {"title": "Machine learning models for liver cancer prediction in a real-world China cohort", "url": "https://www.frontiersin.org/journals/cell-and-developmental-biology/articles/10.3389/fcell.2026.1896989/full"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-11", "date": "2026-10-11", "title": "AI in Healthcare: Research Roundup — October 11, 2026", "excerpt": "Today's LLM additions lean toward reasoning and documentation rather than head-to-head diagnostic contests. A new framework called MedTraj argues the reasoning…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Today's LLM additions lean toward reasoning and documentation rather than head-to-head diagnostic contests. A new framework called MedTraj argues the reasoning trajectory, not just the final answer, is the right unit for evaluating medical agents, cutting hallucination by 87% relative to a zero-shot baseline on one dataset. A related benchmark, MedMT-Bench, tested 17 frontier models on long multi-turn diagnosis-and-treatment conversations (up to 52 rounds); none scored above 60%, underscoring how far current models are from reliably tracking an evolving clinical conversation. A broader survey proposing a five-level medical-reasoning competency scale found specialist models ahead on diagnosis, general-purpose models ahead on decision support and dialogue. On documentation, a retrieval-augmented pipeline generated thoracic oncology histories with 97.9% accuracy in about 13 seconds (versus roughly 240 seconds manually), and six open-source LLMs produced lung-cancer pathology summaries judged more complete than physicians' own.", "On the ML/DL side, today's models span geriatrics, cardiology, neurology, and critical care. A Random Forest model predicting delirium in 973 older inpatients reached AUC 0.908 on the test set. A LightGBM model for coronary heart disease risk, built entirely on non-invasive indicators, held up well externally (AUC 0.851) and was deployed as a public web calculator. A four-model comparison across 788 older hemorrhagic stroke patients in China tackled stroke-associated pneumonia, which affected nearly half the cohort (46.7%). A large-scale deep learning effort using 17 years of Hong Kong electronic health records (569,680 people) predicted chronic kidney disease progression in type 2 diabetes patients at AUCs of 87.1%, 85.3%, and 84.7% for 2-, 5-, and 10-year horizons, validating externally against UK Biobank and CHARLS. And a multicenter ICU model for cirrhosis-plus-sepsis mortality reached AUROC 0.81-0.82 despite in-hospital mortality as high as 38.2% in one validation cohort.", "Taken together, today's findings suggest LLM progress is concentrating in reasoning transparency and clinical documentation, while ML risk models keep delivering strong, externally validated discrimination for well-defined prognostic questions."], "refs": [{"title": "MedTraj framework for evaluating clinical reasoning trajectories in medical agents", "url": "https://arxiv.org/abs/2609.05090"}, {"title": "MedMT-Bench: long multi-turn medical conversation benchmark for 17 frontier LLMs", "url": "https://arxiv.org/pdf/2603.23519"}, {"title": "Survey on LLMs for medical reasoning with a five-level competency scheme", "url": "https://arxiv.org/pdf/2607.07761"}, {"title": "Zero-shot retrieval-augmented LLM pipeline for thoracic oncologic history generation", "url": "https://pubs.rsna.org/doi/10.1148/radiol.251581"}, {"title": "LLM-generated summaries of lung cancer pathology reports vs. physicians", "url": "https://doi.org/10.1200/cci-25-00284"}, {"title": "Random Forest model for delirium risk in older inpatients", "url": "https://pubmed.ncbi.nlm.nih.gov/40891023/"}, {"title": "LightGBM model for coronary heart disease risk from non-invasive indicators", "url": "https://pubmed.ncbi.nlm.nih.gov/41353986/"}, {"title": "Deep learning CKD progression model in type 2 diabetes using 17-year Hong Kong EHR data", "url": "https://pubmed.ncbi.nlm.nih.gov/41699026/"}, {"title": "Multicenter ICU mortality model for cirrhosis and sepsis", "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12926366/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-10", "date": "2026-10-10", "title": "AI in Healthcare: Research Roundup — October 10, 2026", "excerpt": "Today's LLM additions center on head-to-head comparisons against human clinicians and specialized clinical AI tools. A Polish integrated system called Doctorina reached…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Today's LLM additions center on head-to-head comparisons against human clinicians and specialized clinical AI tools. A Polish integrated system called Doctorina reached 82.0% Top-1 diagnostic concordance on 150 primary-care cases, ahead of physicians (57.0%) and four standalone frontier LLMs (66.7%-78.7%). A separate Nature Medicine study found general-purpose models (GPT-5.2, Gemini 3.1 Pro, Claude Opus 4.6) outscoring specialized tools OpenEvidence and UpToDate Expert AI across three benchmarks, including 97.4% vs. 88-90% on a medical licensing-style test — a result OpenEvidence has since publicly disputed. On imaging, ChatGPT-5, Gemini 2.5 Flash, and Claude Sonnet 4 were tested on 772 dermoscopic images for basal cell carcinoma, topping out around 70% detection accuracy, short of what the authors consider clinically ready. A smaller but notable finding: a 60-physician RCT in Pakistan showed AI-literacy training plus LLM access lifted diagnostic scores by 27.7 percentage points over conventional resources alone (71.5% vs. 42.5%).", "On the ML/DL side, today's models span oncology, psychiatry, and infectious disease. An XGBoost model predicting liver metastasis in elderly small cell lung cancer patients (SEER database, Chinese external validation) reached AUC 0.820, edging out LightGBM, logistic regression, and random forest. A six-model comparison for osteoporotic vertebral compression fracture re-fracture risk found Random Forest best (AUC 0.88), flagging scoliosis and chronic kidney disease as top predictors. In psychiatry, a blood-biomarker model distinguishing first-episode schizophrenia from healthy controls hit AUC 0.877 on validation after the authors favored a simpler logistic regression over an overfit-prone Random Forest (training AUC 1.00). And a five-model diagnostic scorecard for macrophage activation syndrome in lupus patients held up well externally across four hospitals (SVM AUC 0.947, scorecard AUC 0.915).", "Taken together, today's studies reinforce that benchmark wins for general-purpose LLMs over specialized tools remain contested, while ML risk models continue to show the clearest gains when paired with careful external validation."], "refs": [{"title": "Doctorina clinical AI system vs. physicians and frontier LLMs on primary care diagnostics", "url": "https://arxiv.org/pdf/2609.09070"}, {"title": "General-purpose LLMs vs. OpenEvidence/UpToDate on medical benchmarks (disputed)", "url": "https://www.beckershospitalreview.com/healthcare-information-technology/ai/chatgpt-gemini-claude-beat-clinical-ai-tools-study"}, {"title": "ChatGPT, Gemini, and Claude on basal cell carcinoma image analysis", "url": "https://www.sciencedirect.com/science/article/pii/S2667026726000159"}, {"title": "AI-literacy training RCT for physician-LLM diagnostic collaboration in Pakistan", "url": "https://www.medrxiv.org/content/10.1101/2025.06.06.25329104.full.pdf"}, {"title": "XGBoost model for liver metastasis risk in small cell lung cancer (SEER + Chinese validation)", "url": "https://pubmed.ncbi.nlm.nih.gov/41518822"}, {"title": "Machine learning for postoperative re-fracture risk in osteoporotic vertebral compression fracture", "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12267157/"}, {"title": "Machine learning clinical prediction model for first-episode schizophrenia", "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12812932/"}, {"title": "Machine learning scorecard for macrophage activation syndrome in systemic lupus erythematosus", "url": "https://pubmed.ncbi.nlm.nih.gov/38725078/"}], "lang": "en", "source": "ai"}, {"id": "ph-2026-10-02-augustinian-proof", "date": "2026-10-09", "title": "অগাস্টিনিয়ান প্রমাণ (এডওয়ার্ড ফেজার)", "title_en": "The Augustinian Proof (Edward Feser, Five Proofs of the Existence of God)", "excerpt": "২ + ২ = ৪। এই সত্যটা নিয়ে একটু ভাবুন। এই সত্য কি আজ সত্য, গতকালও সত্য ছিল, আর হাজার বছর পরেও সত্য থাকবে — এমনকি যদি পৃথিবীতে একটাও মানুষ না থাকে, একটাও মস্তিষ্ক এই…", "theme": "faith", "cats": ["স্রষ্টার অস্তিত্বের যুক্তি", "দর্শন"], "body": ["২ + ২ = ৪। এই সত্যটা নিয়ে একটু ভাবুন। এই সত্য কি আজ সত্য, গতকালও সত্য ছিল, আর হাজার বছর পরেও সত্য থাকবে — এমনকি যদি পৃথিবীতে একটাও মানুষ না থাকে, একটাও মস্তিষ্ক এই হিসাবটা না করে, তাহলেও? আপনার মনে হতে পারে, \"হ্যাঁ, অবশ্যই, এটা তো চিরন্তন সত্য।\" কিন্তু এখানেই একটা অদ্ভুত প্রশ্ন লুকিয়ে আছে। একটা সত্য, একটা হিসাব, একটা নিয়ম — এগুলো তো \"চিন্তা\" জাতীয় কিছু। চিন্তা তো কোথাও না কোথাও \"থাকতে\" হয় — কারো মাথায়, কারো মনে। তাহলে যদি মানুষ না থাকে, এই সত্যটা তখন কোথায় থাকে? কার মনে?", "এই প্রশ্নটাই প্রায় দেড় হাজার বছর আগে তুলেছিলেন চতুর্থ-পঞ্চম শতাব্দীর খ্রিস্টান দার্শনিক-ধর্মতাত্ত্বিক সেন্ট অগাস্টিন (St. Augustine of Hippo)। তাঁর এই চিন্তাকে আধুনিক কালে খুব পরিষ্কার যুক্তির কাঠামোয় সাজিয়েছেন আমেরিকান দার্শনিক এডওয়ার্ড ফেজার (Edward Feser), তাঁর \"Five Proofs of the Existence of God\" বইয়ে। এই যুক্তিটাকে বলা হয় \"অগাস্টিনিয়ান প্রমাণ\" (Augustinian Proof) — একটা এমন যুক্তি, যা শুরু হয় গাণিতিক-যৌক্তিক সত্য থেকে, আর গিয়ে পৌঁছায় একটা চিরন্তন, সর্বজ্ঞ (সব জানে এমন) মনের ধারণায়। আজ এই যুক্তিটা সহজ ভাষায় বোঝার চেষ্টা করি, এর শক্তি আর দুর্বলতা দুটোই দেখি।", "বিমূর্ত জিনিস বলতে কী বোঝায়?", "প্রথমে একটু থামি। দর্শনে একটা বড় প্রশ্ন আছে। সংখ্যা, জ্যামিতিক আকার, যুক্তির নিয়ম, \"লাল রঙ\" জাতীয় সাধারণ ধারণা (যাকে দার্শনিকরা \"ইউনিভার্সাল\" বা সার্বজনীন ধারণা বলেন) — এগুলো আসলে কী? এগুলো কি সত্যিই \"আছে\", নাকি এগুলো শুধু আমাদের মাথার কল্পনা, ভাষার সুবিধার জন্য বানানো শব্দ?", "তিনটা মূল অবস্থান আছে এই নিয়ে। প্রথমটা \"নমিনালিজম\" (Nominalism) — এই মত বলে, সার্বজনীন ধারণা আসলে বাস্তব কিছু নয়, এটা শুধু নাম বা সুবিধার কথা। যেমন, \"লাল\" বলে কিছু সত্যিই নেই, আছে শুধু অনেকগুলো আলাদা আলাদা লাল বস্তু, যাদের আমরা এক নামে ডাকি। দ্বিতীয় মত \"কনসেপচুয়ালিজম\" (Conceptualism) — এটা বলে, সার্বজনীন ধারণা বাস্তব, কিন্তু সেগুলো মন-নির্ভর, মানুষের মাথায় তৈরি হওয়া ধারণা মাত্র। তৃতীয় মত \"রিয়ালিজম\" (Realism) — এটা বলে, সার্বজনীন ধারণা, সংখ্যা, যুক্তির নিয়ম এগুলো সত্যিই আছে, আর এগুলোর অস্তিত্ব কোনো একজন মানুষের মাথায় নির্ভরশীল নয়। \"২ + ২ = ৪\" সত্যটা কোনো নির্দিষ্ট মানুষের চিন্তার ওপর নির্ভর করে না। এটা এমনকি প্রথম মানুষ জন্মাবার আগেও সত্য ছিল, এমনটাই রিয়ালিস্টরা মনে করেন।", "ফেজার যুক্তি দেন রিয়ালিজমের পক্ষে, আর নমিনালিজম ও কনসেপচুয়ালিজমের বিরুদ্ধে কিছু চমৎকার পয়েন্ট তুলে ধরেন। নমিনালিজমের বিরুদ্ধে তাঁর একটা যুক্তি হলো- যদি বলি \"লাল\" বলে আসলে কিছু নেই, আছে শুধু আলাদা আলাদা লাল বস্তু যাদের একই নামে ডাকি, তাহলে প্রশ্ন ওঠে, এই \"একই নামে ডাকা\"টা কীভাবে সম্ভব হলো? \"লাল\" শব্দটা নিজেই তো একটা সার্বজনীন ধারণা। অনেক আলাদা আলাদা লেখা বা উচ্চারণ \"লাল\" শব্দের উদাহরণ। তাহলে শব্দকে ব্যাখ্যা করতে গিয়ে আমরা আরেকটা সার্বজনীন ধারণার আশ্রয় নিচ্ছি, সমস্যাটা মিটছে না, শুধু সরে যাচ্ছে।", "কনসেপচুয়ালিজমের বিরুদ্ধে ফেজারের যুক্তি আরও আকর্ষণীয়। যদি সংখ্যা আর যুক্তির নিয়ম শুধু মানুষের মাথার তৈরি ধারণা হয়, তাহলে \"২ + ২ = ৪\" সত্যটা তো ব্যক্তি থেকে ব্যক্তিতে আলাদা হতে পারত, বা মানুষ জন্মাবার আগে এটা সত্যই ছিল না এমনটাও বলতে হতো। কিন্তু বাস্তবে আমরা সবাই, সব সংস্কৃতিতে, একই গাণিতিক-যৌক্তিক সত্যে একমত হই, আর মনে করি এই সত্যগুলো আমরা \"আবিষ্কার\" করি। এটাই দেখায়, এই সত্যগুলো আমাদের মনের বাইরে, স্বতন্ত্রভাবে বিদ্যমান, তাই এগুলো \"মন-নির্ভর\" হতে পারে না।", "এবার মূল যুক্তিতে আসি", "ধরে নিই, রিয়ালিজম সত্যি। অর্থাৎ, সংখ্যা, যুক্তির নিয়ম, সম্ভাব্য জগতের ধারণা (possible worlds, মানে পৃথিবীকে আমরা যেভাবে দেখছি তা না হয়ে অন্যরকম হতেও পারত- এমন সব কাল্পনিক সম্ভাবনা সত্যিই আছে, আর তা শুধু মানুষের মাথার ওপর নির্ভরশীল নয়। তাহলে প্রশ্ন ওঠে — এগুলো আসলে কোথায় \"আছে\"?", "এখানে অগাস্টিনিয়ান প্রমাণের কেন্দ্রীয় পয়েন্ট — একটা সত্য বা একটা ধারণা শূন্যে ভাসতে পারে না। একটা চিন্তা, একটা প্রস্তাবনা (প্রোপোজিশন, যেমন \"তুষার সাদা\" এই বাক্যটার অর্থ), এগুলো স্বভাবতই এমন জিনিস যা কোনো একটা মনে \"থাকে”। এটাই উক্ত প্রস্তাবনার স্বভাব। যেমন একটা হাসি কোনো মুখ ছাড়া থাকতে পারে না, তেমনি একটা চিন্তা কোনো মন ছাড়া থাকতে পারে না। কিন্তু আমরা তো আগেই বলেছি, এই সত্যগুলো কোনো নির্দিষ্ট মানুষের মনের ওপর নির্ভরশীল নয় — এগুলো মানুষের জন্মের আগেও সত্য ছিল, মানুষ বিলুপ্ত হয়ে গেলেও সত্য থাকবে। মানুষের মন তো অস্থায়ী, সীমাবদ্ধ, কখনো ছিল না এমন একটা অবস্থা থেকে শুরু হয়েছে।", "তাহলে এই চিরন্তন সত্যগুলো টিকে থাকার জন্য দরকার এমন একটা মন, যা নিজেও চিরন্তন, যার অস্তিত্ব কখনো শুরু হয়নি আর কখনো শেষ হবে না, এবং যে মনে সমস্ত সম্ভাব্য গাণিতিক-যৌক্তিক সত্য একসাথে, সম্পূর্ণভাবে উপস্থিত। ফেজার আর ক্লাসিক্যাল দার্শনিকরা এই অনন্ত, সর্বজ্ঞ মনকেই বলেন ঈশ্বর। এখানে একটা গুরুত্বপূর্ণ কথা বলা দরকার — এই যুক্তি আসলে কার্যকারণমূলক (causal) যুক্তি না, যেমনটা আমরা \"প্রথম কারণ\" জাতীয় যুক্তিতে দেখি। এই যুক্তি বলছে না যে ঈশ্বর এই সত্যগুলো \"তৈরি করেছেন\"। এটা বলছে, ঈশ্বরের মনই এই সত্যগুলোর \"ঠিকানা\" বা আশ্রয়স্থল — যেমন একটা বইয়ের প্রতিটা অধ্যায় বইটার মধ্যেই থাকে, সৃষ্টি হয় না আলাদাভাবে।", "একটা সহজ উপমায় বোঝা যাক। ধরুন দাবা খেলার নিয়মগুলো, যেমন- ঘোড়া কীভাবে চলে, রাজা কীভাবে চেইকমেইট হয় এই নিয়মগুলো কি দাবার বোর্ড আবিষ্কারের আগে থেকেই কোনো অর্থে \"ছিল\"? একভাবে বলা যায়, হ্যাঁ — যৌক্তিক সম্ভাবনা হিসেবে এই নিয়মগুলোর ধারণা সবসময় সত্য ছিল, মানুষ শুধু আবিষ্কার করেছে। অগাস্টিনিয়ান যুক্তি বলছে, গণিত আর যুক্তির জগৎটাও এরকম — আমরা শুধু আবিষ্কার করি, কিন্তু এই আবিষ্কারের বস্তুগুলো কোথাও না কোথাও, কোনো মনে, চিরকাল ধরে উপস্থিত থাকতে হবে।", "সমালোচকরা কী বলেন", "এই যুক্তির প্রথম এবং সবচেয়ে বড় দুর্বলতা হলো এর প্রথম ধাপেই রিয়ালিজম প্রমাণ করা। অনেক দার্শনিক, বিশেষ করে আধুনিক যুক্তিবিদ্যা আর গণিতের দর্শনে কাজ করা বিশ্লেষণী দার্শনিকরা, মনে করেন নমিনালিজম বা কনসেপচুয়ালিজমের প্রতিরক্ষামূলক সংস্করণ এখনও সম্ভব, আর ফেজারের যুক্তিগুলো এই মতগুলোকে সম্পূর্ণ অসম্ভব প্রমাণ করতে পারে না, কেবল কিছু সংস্করণকে কঠিন করে তোলে।", "দ্বিতীয় আপত্তি আসে এমন দার্শনিকদের কাছ থেকে যারা রিয়ালিজম মানেন, কিন্তু \"প্লেটোনিজম\" (Platonism) নামের একটা আলাদা সংস্করণ সমর্থন করেন। প্লেটোনিস্টরা বলেন, সংখ্যা আর সার্বজনীন ধারণা সত্যিই আছে, স্বতন্ত্রভাবে আছে — কিন্তু এগুলোর কোনো মনে \"থাকার\" দরকার নেই। এগুলো নিজের শক্তিতেই, নিজের জগতেই বিদ্যমান, ঠিক যেমন একটা পাথর কারো মনে \"থাকার\" দরকার নেই বাস্তবে থাকতে। ফেজার এই মতের বিরুদ্ধে যুক্তি দেন ঠিকই, কিন্তু অনেক সমালোচক মনে করেন তার যুক্তিগুলো চূড়ান্তভাবে সিদ্ধান্তমূলক নয়। অর্থাৎ, প্লেটোনিজম একটা যুক্তিসংগত বিকল্প থেকেই যায়, আর যদি তাই হয়, তাহলে পুরো যুক্তিটাই দ্বিতীয় পদক্ষেপে থেমে যায়, কারণ তখন \"একটা মনের দরকার\" এই দাবিটাই মিথ্যা হয়ে যায়।", "তৃতীয় আপত্তি একটা গভীর জ্ঞানতাত্ত্বিক (এপিস্টেমিক, মানে জ্ঞান সম্পর্কিত) সমস্যা থেকে আসে। যদি সংখ্যা বা সার্বজনীন ধারণা সত্যিই আমাদের জগতের বাইরে, এক ভিন্ন ধরনের বাস্তবতায় থাকে, তাহলে আমরা কীভাবে এগুলো \"জানি\"? আমাদের জ্ঞান সাধারণত আসে ইন্দ্রিয়ের মাধ্যমে, কার্যকারণ সম্পর্কের মাধ্যমে। আমরা একটা জিনিস দেখি, স্পর্শ করি, তার প্রভাব অনুভব করি। কিন্তু বিমূর্ত বস্তুর সাথে তো আমাদের কোনো কার্যকারণ সম্পর্ক সম্ভব নয়। সংখ্যা \"৭\" আমাদের মস্তিষ্কে কোনো আলো বা তরঙ্গ পাঠায় না। তাহলে আমরা কীভাবে এগুলো সম্পর্কে নিশ্চিত হই? এই প্রশ্নটা শুধু অগাস্টিনিয়ান প্রমাণের বিরুদ্ধে নয়, বরং সাধারণভাবে সব ধরনের রিয়ালিজমের বিরুদ্ধেই একটা কঠিন চ্যালেঞ্জ, আর ফেজার সমর্থকরা বলেন, এই সমস্যাটা আসলে নমিনালিস্ট বা প্লেটোনিস্টদের জন্যও সমান কঠিন, তাই এটা অগাস্টিনিয়ান প্রমাণকে আলাদাভাবে দুর্বল করে না।", "চতুর্থ এবং শেষ আপত্তিটা অন্য প্রমাণগুলোর ক্ষেত্রেও দেখা যায়। ধরে নিই যুক্তিটা পুরোপুরি সফল, তাহলেও এটা কি আমাদের এমন একজন ঈশ্বর পর্যন্ত পৌঁছে দেয় যিনি ভালোবাসেন, প্রার্থনা শোনেন, ইতিহাসে হস্তক্ষেপ করেন? অনেক সমালোচক বলেন, এই যুক্তি সর্বোচ্চ একটা \"সর্বজ্ঞ চিরন্তন মন\" প্রমাণ করতে পারে, কিন্তু এই মন আর ধর্মীয় অর্থে উপাসিত ব্যক্তিগত ঈশ্বরের মাঝে দূরত্ব ঘোচাতে আলাদা যুক্তির প্রয়োজন। ফেজার এই আপত্তি মেনে নেন আংশিকভাবে। তার মতে, পাঁচটা প্রমাণ (তার বইয়ে প্রকাশিত পাঁচটা প্রমাণ) একসাথে, ধাপে ধাপে, ঈশ্বরের বিভিন্ন গুণ প্রতিষ্ঠা করে, একটা প্রমাণ একা পুরো কাজ করার কথা নয়।", "এই যুক্তিটার সৌন্দর্য হলো, এটা আমাদের এমন একটা জায়গায় নিয়ে যায় যেখানে আমরা সচরাচর চিন্তাই করি না — গণিতের ক্লাসে \"২ + ২ = ৪\" শিখি, মুখস্থ করি, পরীক্ষা দিই, কিন্তু কখনো থেমে ভাবি না, এই সত্যটা আসলে কোথায় \"থাকে\"। অথচ এই প্রশ্নটা একবার মাথায় ঢুকলে, সহজে বের হয় না।"], "source": "philosophy"}, {"id": "ai-2026-10-09", "date": "2026-10-09", "title": "AI in Healthcare: Research Roundup — October 9, 2026", "excerpt": "Today's LLM additions cluster around oncology decision support and specialized clinical benchmarking. A multicenter study ran 1,063 thyroid ultrasound reports (306…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Today's LLM additions cluster around oncology decision support and specialized clinical benchmarking. A multicenter study ran 1,063 thyroid ultrasound reports (306 histopathology-confirmed) through ChatGPT-4o and DeepSeek-R1, finding DeepSeek-R1 more accurate and consistent at benign-versus-malignant classification, while the two models matched on management recommendations. A new 511-question benchmark (MSIC-Bench) tested GPT-4o, Gemini 2.5 Pro, and Claude Opus 4 on microsatellite instability cancer tasks and concluded the gap is domain knowledge, not reasoning ability. In a prospective head-and-neck tumor board study, two locally run open-weight models (gemma-3-12b, gpt-oss-20b) generated treatment recommendations for 17 real cases, scored by board members on a 6-point adequacy scale after the human decision was already made. Separately, a retrieval-augmented generation framework from Mass General Brigham targeted a quieter but high-volume problem: identifying dementia cases buried in unstructured EHR notes, where rule-based and keyword methods are known to miss clinical nuance.", "On the ML/DL side, several groups reported a familiar pattern — strong internal performance that erodes externally. A chronic critical illness model for ICU patients with acute pancreatitis (MIMIC-IV/eICU development, Chinese single-center external validation) dropped from AUROC 0.85 internally to 0.73 externally. A breast MRI deep learning model for BI-RADS assessment, trained on 12,241 exams, underperformed radiologists in external validation (76.7% vs 91.3% AUC), and a gastric cancer endoscopy meta-analysis saw pooled sensitivity/specificity fall from 0.91/0.93 internally to 0.82/0.83 across just four external-validation studies. Kidney-metabolic risk models fared better: a China Renal Data System-derived XGBoost model predicting 5-year heart failure in CKD patients held up across both Chinese (AUC 0.879) and UK Biobank (0.851) external cohorts, and a SHAP-interpreted ensemble reached AUC 0.979 for mortality risk in 512 maintenance hemodialysis patients.", "Together, today's batch underscores external validation as the recurring fault line between promising internal results and real-world reliability."], "refs": [{"title": "ChatGPT-4o vs DeepSeek-R1 on thyroid nodule ultrasound reports", "url": "https://www.jmir.org/2026/1/e93890/PDF"}, {"title": "MSIC-Bench: benchmarking LLMs on microsatellite instability cancers", "url": "https://www.jmir.org/2026/1/e88614/PDF"}, {"title": "Locally run LLMs augmenting head and neck tumor board recommendations", "url": "https://ai.jmir.org/2026/1/e95081/PDF"}, {"title": "RAG LLM framework for dementia identification from EHRs", "url": "https://www.medrxiv.org/content/10.64898/2026.01.24.26344477.full.pdf"}, {"title": "Machine learning for chronic critical illness in acute pancreatitis (MIMIC-IV/eICU, external validation)", "url": "https://pubmed.ncbi.nlm.nih.gov/41947133/"}, {"title": "Deep learning BI-RADS model vs radiologists, breast MRI external validation", "url": "https://www.diagnosticimaging.com/view/study-mixed-results-deep-learning-model-breast-mri"}, {"title": "Deep learning for early gastric cancer detection, meta-analysis", "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12894240/"}, {"title": "XGBoost model for heart failure risk in chronic kidney disease (China Renal Data System, UK Biobank validation)", "url": "https://www.ajmc.com/view/machine-learning-model-improves-prediction-of-heart-failure-risk-in-ckd"}, {"title": "SHAP-explained machine learning for mortality risk in maintenance hemodialysis patients", "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12277357/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-08", "date": "2026-10-08", "title": "AI in Healthcare: Research Roundup — October 8, 2026", "excerpt": "Today's LLM additions center on documentation and communication tasks already moving into live clinical use. In a Dutch academic hospital, blinded clinicians rated 292…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Today's LLM additions center on documentation and communication tasks already moving into live clinical use. In a Dutch academic hospital, blinded clinicians rated 292 paired discharge summaries and found LLM-generated versions more concise than physician-written ones (median 5.00 vs 4.50, p<0.001) but somewhat less complete (4.50 vs 5.00, p<0.001), with no significant difference in correctness. A Duke University crossover study of 553 patients found GPT-4-translated discharge summaries improved comprehension across four conditions (heart failure, pneumonia, DKA, stroke), with the largest gains among patients with limited health literacy. On the evaluation side, a 16-model benchmark (GPT-o1, Gemini 2.5 Pro, Claude 3.7 Sonnet, and others) tested whether LLMs would catch and correct a deliberately incorrect physician diagnosis across 200 vignettes of commonly misdiagnosed conditions, introducing a new \"diagnostic correction rate\" metric. A JMIR meta-analysis of four studies (2,604 evaluations) found LLM-assisted communication raised perceived empathy substantially (SMD 1.02), though the authors note more randomized trials are needed.", "On the ML/DL side, prognostic and risk models continued targeting specific disease populations. An ensemble XGBoost model using PROFUND frailty components for 30-day readmission in multimorbid patients reached only modest discrimination (AUC 0.59) versus standard LACE (0.52) and HOSPITAL (0.54) scores, while a SHAP-interpretable stacking ensemble for 30-day readmission in elderly type 2 diabetes/heart failure patients performed much better (AUC 0.867, n=870). A multicenter CONFIDENT-HFpEF model reached a C-index of 0.72 for mortality in external validation, outperforming the established PREDICT-HFpEF score. A deep learning model for acute pancreatitis severity from CT, pretrained on over 10,000 studies, hit an internal AUROC of 0.888, and a random survival forest model for transthyretin amyloid cardiomyopathy (n=850, two European registries) outperformed existing Mayo Clinic and National Amyloidosis Centre staging systems for predicting mortality and HF hospitalization.", "Across both tracks, today's additions reflect models increasingly benchmarked against established clinical scores rather than evaluated in isolation."], "refs": [{"title": "AI-generated vs. physician-written discharge summaries, Dutch academic hospital", "url": "https://pubmed.ncbi.nlm.nih.gov/41962200/"}, {"title": "GPT-4-translated discharge summaries improve patient comprehension", "url": "https://www.2minutemedicine.com/large-language-models-llms-substantially-improved-patient-comprehension-of-discharge-summaries/"}, {"title": "Benchmark of LLMs correcting diagnostic errors", "url": "https://www.medrxiv.org/content/10.64898/2026.02.22.26346832v1.full"}, {"title": "LLMs in physician-patient communication, systematic review and meta-analysis", "url": "https://www.jmir.org/2026/1/e77307/PDF"}, {"title": "PROFUND-based machine learning for 30-day readmission in multimorbid patients", "url": "https://deustoteka.deusto.es/items/d016129a-614d-475d-a589-a10e1f20420f/full"}, {"title": "CONFIDENT-HFpEF machine learning risk stratification", "url": "https://www.owkin.com/publications/confident-hfpef-a-machine-learning-based-risk-stratification-for-mortality-and-hospitalization-using-multimodal-real-world-data"}, {"title": "Deep learning model for acute pancreatitis severity from CT", "url": "https://healthmanagement.org/c/imaging/News/ai-supports-early-pancreatitis-risk-stratification"}, {"title": "Machine learning risk prediction for transthyretin amyloid cardiomyopathy", "url": "https://jamanetwork.com/journals/jamacardiology/fullarticle/2853448"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-07", "date": "2026-10-07", "title": "AI in Healthcare: Research Roundup — October 7, 2026", "excerpt": "Today's LLM additions lean toward patient-facing deployment and evaluation. A randomized controlled trial of PreA, an LLM chatbot handling history-taking and referral…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Today's LLM additions lean toward patient-facing deployment and evaluation. A randomized controlled trial of PreA, an LLM chatbot handling history-taking and referral generation ahead of specialist visits, cut physician consultation time by 28.7% across 2,069 patients, with outcomes holding up even when the chatbot ran without staff support. In hospital documentation, a Gemini 2.5 Pro-based agentic workflow (MedAgentBrief) generated nightly discharge summaries across 384 admissions; physicians used its output in 57% of cases, rated 88% of unedited drafts as having no harm potential, and reported a significant drop in burnout scores. Elsewhere, CataractBot's expert-verified answers for cataract surgery patients were rated 84.5% accurate and complete, while scoping reviews flagged how early this space still is: only 8 studies exist on multiturn LLM chatbots for cancer patients and caregivers, and a separate review on LLM-based mental health chatbots found safety and privacy risks remain under-studied relative to the pace of deployment.", "On the ML/DL side, prognostic nomograms kept targeting high-stakes, lower-profile conditions. A nomogram for acute chlorfenapyr poisoning hit a C-index of 0.988 in training (0.849 on validation) using procalcitonin, ALT, and dose as key predictors, while a readmission-risk nomogram for acute pancreatitis reached AUC 0.836 internally but dropped to 0.704 on external validation — a reminder that generalization remains the harder test. Imaging-based diagnostic models also advanced: a CBAM-ResNet model for Alzheimer's diagnosis reached AUC 0.876, a CNN classifying cervical CT scans distinguished Kikuchi disease, lymphoma, lymphadenitis, and tuberculosis with PR-AUC between 0.73 and 0.92, and an international reader study pitted a market-approved CNN against 96 dermatologists on real-world skin lesion classification.", "Across both tracks, the same pattern holds: LLM tools are moving into live clinical workflows with measurable efficiency and burnout gains, while ML/DL diagnostic and prognostic models keep posting strong internal performance but a recurring external-validation gap."], "refs": [{"title": "RCT of LLM chatbot (PreA) for primary-to-specialist care transitions", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13004692/"}, {"title": "Physician-reported safety outcomes of AI-generated hospital course summaries (MedAgentBrief)", "url": "https://pubmed.ncbi.nlm.nih.gov/42101844/"}, {"title": "CataractBot utility for pre/post-operative cataract care", "url": "https://pubmed.ncbi.nlm.nih.gov/41358933/"}, {"title": "Scoping review of LLM chatbots for cancer patients and caregivers", "url": "https://cancer.jmir.org/2026/1/e96241"}, {"title": "Scoping review on mental health harms of LLM-based chatbots", "url": "https://pubmed.ncbi.nlm.nih.gov/42624944/"}, {"title": "Prognostic nomogram for acute chlorfenapyr poisoning mortality", "url": "https://pubmed.ncbi.nlm.nih.gov/42170443/"}, {"title": "Nomogram for unplanned readmission in acute pancreatitis", "url": "https://pubmed.ncbi.nlm.nih.gov/41890191/"}, {"title": "CBAM-ResNet model for Alzheimer's disease diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/42295635/"}, {"title": "CNN vs. 96 dermatologists on skin lesion diagnosis, international study", "url": "https://pubmed.ncbi.nlm.nih.gov/42252869/"}], "lang": "en", "source": "ai"}, {"id": "ph-2026-09-29-neo-platonic-proof", "date": "2026-10-06", "title": "নব্য-প্লেটোনিক প্রমাণ (এডওয়ার্ড ফেজার)", "title_en": "The Neo-Platonic Proof (Edward Feser, Five Proofs of the Existence of God)", "excerpt": "নিও-প্ল্যাটোনিক প্রুফ", "theme": "faith", "cats": ["স্রষ্টার অস্তিত্বের যুক্তি", "দর্শন"], "body": ["নিও-প্ল্যাটোনিক প্রুফ", "আপনার হাতের ফোনটার দিকে একবার তাকান। স্ক্রিন, ব্যাটারি, চিপ, প্লাস্টিকের বডি — অনেকগুলো আলাদা আলাদা অংশ একসাথে জোড়া লেগে একটা \"ফোন\" হয়ে আছে। এবার নিজের শরীরের দিকে তাকান। কোটি কোটি কোষ, রক্ত, হাড়, স্নায়ু — সব মিলে \"আপনি\" হয়ে আছেন। এমনকি এই মুহূর্তে আপনি যে চেয়ারে বসে আছেন, সেটাও কাঠ, স্ক্রু, আঠা দিয়ে তৈরি।", "একটা প্রশ্ন করি। এই জিনিসগুলো তৈরি হয়েছে অতীতে — কারখানায়, মায়ের গর্ভে, কাঠমিস্ত্রির হাতে। কিন্তু এখন, এই মুহূর্তে, কেন এই অংশগুলো একসাথে লেগে আছে? কেন ফোনের স্ক্রিন হঠাৎ আলাদা হয়ে যাচ্ছে না, কেন আপনার শরীরের কোষগুলো এই মুহূর্তে ছড়িয়ে-ছিটিয়ে যাচ্ছে না? \"অতীতে তৈরি হয়েছিল\" — এই উত্তরটা কি আসলে যথেষ্ট?", "এই প্রশ্ন থেকেই জন্ম নিয়েছে দর্শনের এক অসাধারণ পুরনো যুক্তি, যাকে বলা হয় \"নব্য-প্লেটোনিক প্রমাণ\" (Neo-Platonic Proof)। এর শিকড় প্রাচীন গ্রিক-রোমান দার্শনিক প্লোটিনাসের (Plotinus, খ্রিস্টীয় তৃতীয় শতাব্দী) চিন্তায়, আর আধুনিক কালে এটাকে খুব পরিষ্কারভাবে সাজিয়েছেন আমেরিকান দার্শনিক এডওয়ার্ড ফেজার (Edward Feser) তাঁর \"Five Proofs of the Existence of God\" বইয়ে। চলুন, একদম সহজ ভাষায় বোঝার চেষ্টা করি — যুক্তিটা কী বলছে, কেন অনেকে এটাকে শক্তিশালী মনে করেন, আর কেন অনেক দার্শনিক এতে গুরুতর আপত্তি তোলেন।", "তাসের ঘর দিয়ে বোঝা যাক", "কল্পনা করুন, আপনি তাস দিয়ে একটা ঘর বানাচ্ছেন। নিচের সারির দুটো তাস একে অপরের গায়ে হেলান দিয়ে দাঁড়িয়ে আছে। তার ওপর আরেকটা তাস শুয়ে আছে। তার ওপর আবার আরেক সারি হেলানো তাস। পুরো কাঠামোটা টিকে আছে কারণ প্রতিটা তাস তার নিচের তাসের ওপর নির্ভর করছে — ঠিক এই মুহূর্তে, একসাথে, একই সময়ে। এটা কোনো ঐতিহাসিক ঘটনা নয় (যেমন \"গতকাল আমি এই তাসটা রেখেছিলাম\") — এটা এখনকার, বর্তমান মুহূর্তের নির্ভরতা।", "এখন প্রশ্ন হলো: পুরো তাসের ঘরটা কীসের ওপর দাঁড়িয়ে? উত্তর হলো টেবিল। টেবিলটা তাসের মতো আরেকটা তাসের ওপর হেলান দিয়ে নেই — সেটা নিজেই শক্ত, নিজে দাঁড়িয়ে থাকতে পারে, তার আর কোনো \"নিচের তাস\"-এর দরকার নেই।", "নব্য-প্লেটোনিক যুক্তির মূল কথাটা অনেকটা এরকম। আমাদের চারপাশের প্রতিটা জিনিস — ফোন, শরীর, চেয়ার, এমনকি একটা পরমাণু পর্যন্ত — \"যৌগিক\" বা কম্পোজিট (composite), মানে অনেকগুলো অংশ দিয়ে তৈরি। কিন্তু শুধু অংশগুলো একসাথে জড়ো করে দিলেই তো \"একটা জিনিস\" তৈরি হয় না। কাঠ, স্ক্রু, আর আঠা আলাদা আলাদা টেবিলের ওপর পড়ে থাকলে সেটা \"চেয়ার\" নয়, স্তূপ মাত্র। কিছু একটা এই অংশগুলোকে এই মুহূর্তে, এখন, একসাথে ধরে রাখছে বলেই এটা একটা \"চেয়ার\" হিসেবে টিকে আছে।", "ফেজারের যুক্তি বলছে, এই \"ধরে রাখা\"-টা একটা কারণ (cause) দাবি করে — এবং সেই কারণ যদি নিজেও যৌগিক হয় (নিজেও অনেক অংশ দিয়ে তৈরি হয়), তাহলে তারও নিজের অংশগুলোকে ধরে রাখার জন্য আরেকটা কারণ লাগবে। এভাবে একটার পর একটা স্তর — ঠিক তাসের ঘরের মতো, অতীতের দিকে নয়, বরং বর্তমানের গভীরে — নেমে যেতে থাকে। প্রশ্ন হলো: এই স্তরগুলো কি অনন্তকাল ধরে চলতেই থাকতে পারে, নিচে কোনো \"টেবিল\" ছাড়াই?", "ক্লাসিক্যাল দার্শনিকরা বলেন, না। যদি নিচে কোনো প্রকৃত ভিত্তি না থাকে — যদি পুরো ব্যবস্থাটা শুধু তাসের-ওপর-তাস হয়েই চলতে থাকে, কোনো টেবিল ছাড়াই — তাহলে আসলে কোনো কিছুই কিছুকে ধরে রাখছে না। পুরো কাঠামোটা তখন শূন্যে ভাসমান, আর বাস্তবে এরকম কিছু ধরে রাখাই সম্ভব নয়। তাই এই স্তরগুলোর শেষে এমন একটা কিছু থাকতেই হবে যেটা নিজে যৌগিক নয় — যার কোনো অংশ নেই, তাই যাকে ধরে রাখার জন্য আর কোনো আলাদা কারণের দরকার নেই। এই \"অংশহীন\", সম্পূর্ণ সরল বা অখণ্ড সত্তাকেই প্লোটিনাস বলতেন \"দ্য ওয়ান\" (The One), আর ফেজারসহ খ্রিস্টান, ইহুদি, মুসলিম ঐতিহ্যের অনেক দার্শনিক-ধর্মতাত্ত্বিক এটাকেই বলেন ঈশ্বর।", "\"সম্পূর্ণ সরল\" মানে আসলে কী?", "এখানে একটা জিনিস স্বীকার করা জরুরি — আমাদের অভিজ্ঞতায় এমন কিছুই নেই যা সত্যিকার অর্থে \"সম্পূর্ণ সরল\" বা অংশহীন। এমনকি একটা আলোর কণা বা একটা চিন্তাও কোনো না কোনোভাবে গঠিত। তাই এই যুক্তির শেষ ধাপে আমরা এমন একটা ধারণার মুখোমুখি হই যার সাথে দৈনন্দিন অভিজ্ঞতার সরাসরি তুলনা চলে না। ঐতিহ্য বলে, এই সত্তায় \"অস্তিত্ব\" আর \"সত্তা\" আলাদা কিছু নয়, \"শক্তি\" আর \"জ্ঞান\" আলাদা টুকরো নয় — সবকিছু একই অখণ্ড বাস্তবতা। এজন্যই বলা হয়, ঈশ্বরের \"ভালোত্ব আছে\" তা নয়, বরং ঈশ্বর নিজেই ভালোত্ব। এটা আমাদের মতো একটা প্রাণীর বাড়তি ভালো সংস্করণ নয় — এটা সম্পূর্ণ ভিন্ন ধরনের বাস্তবতা, যার ওপর নির্ভর করেই বাকি সব যৌগিক জিনিস এই মুহূর্তে টিকে থাকতে পারে।", "এবার শুনি সমালোচকরা কী বলেন", "এই যুক্তিটা যতটা সুন্দর শোনায়, ততটাই এটা কঠিন প্রশ্নের মুখে পড়ে। সমসাময়িক দার্শনিক জোসেফ শ্মিড (Joseph Schmid) তাঁর \"Simply Unsuccessful: The Neo-Platonic Proof of God's Existence\" প্রবন্ধে বেশ কিছু গুরুত্বপূর্ণ আপত্তি তুলেছেন, যেগুলো ফেজারের সমর্থকদের কাছেও গুরুত্বসহকারে আলোচিত হয়।", "প্রথম আপত্তি হলো, যুক্তির মূল ভিত্তি নিয়ে — \"প্রতিটা যৌগিক জিনিসের অংশগুলোকে একসাথে ধরে রাখার জন্য অবশ্যই একটা সক্রিয় কারণ থাকতে হবে\" — এই দাবিটা আসলে প্রমাণিত নয়। হয়তো একটা জিনিসের অংশগুলো একসাথে থাকার কারণ শুধুই সাধারণ পদার্থবিজ্ঞান — রাসায়নিক বন্ধন, মহাকর্ষ, বৈদ্যুতিক বল। এর জন্য আলাদা কোনো অতিপ্রাকৃত \"ধরে-রাখা-কারণ\" লাগার কথা নয়, এটা এমনকিছু দার্শনিকও মনে করেন যারা বিশ্বাস করেন \"সমগ্র\" (whole) বলে আলাদা কিছুর অস্তিত্বই নেই — শুধু অংশগুলো একটা নির্দিষ্ট বিন্যাসে সাজানো আছে, তার বেশি কিছু নয়। যদি তাই হয়, তাহলে যে \"যৌগিক বস্তু\"-কে কারণ খুঁজতে হবে বলে যুক্তিটা দাবি করছে, সেই বস্তুই হয়তো সেই অর্থে আসলে নেই।", "দ্বিতীয় আপত্তিটা আরও গভীর এবং আগ্রহোদ্দীপক। ধরা যাক যুক্তিটা পুরোপুরি সফল — তাহলেও এটা কি আমাদের একটা \"মন\" পর্যন্ত পৌঁছে দেয়? একজন ব্যক্তিগত ঈশ্বর, যিনি জানেন, ভাবেন, ভালোবাসেন? শ্মিড বলছেন, \"মন\" থাকা মানেই কিছুটা অভ্যন্তরীণ পার্থক্য থাকা — একজন চিন্তাকারী, আর তার চিন্তা, এই দুটো সম্পূর্ণ অভিন্ন হলে \"চিন্তা করা\" ধারণাটাই অর্থহীন হয়ে পড়ে। কিন্তু নব্য-প্লেটোনিক যুক্তি যে সত্তার কথা বলছে, সেখানে কোনো অভ্যন্তরীণ পার্থক্যই নেই — সবকিছু সম্পূর্ণ অখণ্ড। তাহলে কি এই \"সম্পূর্ণ সরল\" সত্তা আদৌ চিন্তা করতে, জানতে, ইচ্ছা করতে পারে? এটা এমন একটা টান যা স্বয়ং ধর্মতাত্ত্বিকরাও শতাব্দীর পর শতাব্দী ধরে নিয়ে আলোচনা করেছেন।", "দুই পক্ষের অবস্থান", "যে ঐতিহ্য প্লোটিনাস থেকে শুরু করে মধ্যযুগীয় খ্রিস্টান, ইহুদি আর মুসলিম দার্শনিকদের হাত ধরে বিকশিত হয়েছে সেই ক্লাসিক্যাল দর্শনের সমর্থকরা (যেমন: ফেজার) মনে করেন এই আপত্তিগুলোর যুক্তিসংগত উত্তর আছে। অন্যদিকে শ্মিডের মতো সমালোচকরা মনে করেন, যুক্তিটা খুব বেশি হলে একটা নৈর্ব্যক্তিক \"অস্তিত্বের ভিত্তি\" প্রমাণ করে — কোনো একজন ব্যক্তিগত, চিন্তাশীল ঈশ্বর নয়। কেউ কেউ আবার এই \"ভিত্তি\"-কেই ঈশ্বর বলে মেনে নিতে রাজি, কেউ রাজি নন।", "যা লক্ষণীয়, তা হলো এই যুক্তির প্রশ্নটা আসলে আমাদের অস্তিত্বের একেবারে মূলে গিয়ে ঠেকে। আমরা সচরাচর ভাবি, \"একটা জিনিস কেন তৈরি হলো\" তার উত্তর খুঁজি অতীতে — কে বানালো, কবে বানালো। কিন্তু এই যুক্তি জিজ্ঞেস করছে অন্য এক প্রশ্ন: এই মুহূর্তে, ঠিক এখন, কেন এই জিনিসটা \"একটা জিনিস\" হয়ে টিকে আছে, ভেঙে পড়ছে না? এটা এমন একটা প্রশ্ন যা আমরা সচরাচর করিই না, অথচ একবার করলে সহজে মাথা থেকে যায় না।", "দার্শনিক যুক্তিগুলো যেন বড় একটা পাজলের অনেকগুলো পিস এবং এই যুক্তিটিও একটি পিস। আইসোলেটেড ভাবে, এই পিসগুলো আসলে স্রষ্টার অস্তিত্বের পক্ষে একেকটা ভিত্তি দেয় এবং সর্বশেষ ধর্মগ্রন্থ আল কোরআন সেই ভিত্তির ওপর কাঠামো দাড় করিয়ে দেয়। সব মিলিয়ে এ স্থাপনা দৃঢ় স্রষ্টায় দৃঢ় বিশ্বাসের যৌক্তিক প্রয়োজনীয়তা প্রমাণ করে।"], "source": "philosophy"}, {"id": "ai-2026-10-06", "date": "2026-10-06", "title": "AI in Healthcare: Research Roundup — October 6, 2026", "excerpt": "Today's LLM-related additions center on benchmarking and evaluation rather than new clinical deployments. ClinicRealm, testing 15 GPT-style LLMs, 5 BERT-style models,…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Today's LLM-related additions center on benchmarking and evaluation rather than new clinical deployments. ClinicRealm, testing 15 GPT-style LLMs, 5 BERT-style models, and 11 traditional ML methods, found leading zero-shot LLMs like GPT-5 now outperform finetuned BERT models on clinical notes, though conventional ML still leads on structured EHR data with ample training data. A physician-benchmarked triage study across 6,232 scenarios (226,191 LLM responses vs. 7,356 physician annotations) found LLMs more likely than physicians to recommend unnecessary care, especially under gender and tone perturbation. On multi-course clinical decision-making, a top medical LLM (HuatuoGPT-o1) scored only 43-48% versus 85-88% for human physicians. In narrower patient-facing roles, ChatGPT-5.3 was rated appropriate 94-100% of the time for scoliosis patient questions, and ChatGPT-5 scored 4.74/5 for guideline concordance on vascular disease management — though a comparison of eight chatbots on public mental health information found none met basic readability standards.", "On the ML/DL side, diagnostic and risk models continued posting strong discrimination across cancer and acute-care conditions. An XGBoost model predicted adverse prognosis in pediatric pneumonia at AUC 0.84, while a machine learning model for NSTE-ACS in-hospital mortality reached ROC-AUC 0.951, outperforming the GRACE risk score. Imaging-based diagnostic models were especially strong: a CNN for gastric neuroendocrine carcinoma reached AUROC up to 1.000, a multimodal CT-plus-lab model for gallbladder cancer hit 93.3% accuracy, and a 3D-DenseNet ensemble for sacral bone tumors (AUC 0.91 internal/0.87 external) improved radiologist accuracy when used as a decision aid. A ten-study meta-analysis of deep learning for lumbar disc herniation diagnosis pooled sensitivity and specificity at 0.94 each, though external validation again lagged internal performance.", "Across both tracks, the throughline is validation discipline: LLMs are being stress-tested against physicians and shown to still lag on complex, multi-step reasoning, while imaging-based ML/DL diagnostic models keep clearing high internal benchmarks but show a recurring accuracy gap once tested externally."], "refs": [{"title": "ClinicRealm benchmark of LLMs vs. conventional ML for clinical prediction", "url": "https://pubmed.ncbi.nlm.nih.gov/41951858/"}, {"title": "Sense and Sensitivity: benchmarking LLM clinical triage vs. physicians", "url": "https://arxiv.org/html/2609.38600"}, {"title": "ClinicalMC benchmark for multi-course clinical decision-making", "url": "https://arxiv.org/abs/2606.03157v1"}, {"title": "Eight-LLM comparison on public mental health information quality", "url": "https://pubmed.ncbi.nlm.nih.gov/42433429/"}, {"title": "XGBoost risk prediction model for pediatric pneumonia prognosis", "url": "https://pubmed.ncbi.nlm.nih.gov/41684921/"}, {"title": "ML model for NSTE-ACS in-hospital mortality risk", "url": "https://pubmed.ncbi.nlm.nih.gov/42616816/"}, {"title": "Multimodal deep learning model for gallbladder cancer diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/42108444/"}, {"title": "Deep learning ensemble for sacral bone tumor differentiation", "url": "https://pubmed.ncbi.nlm.nih.gov/41774326"}, {"title": "Meta-analysis of deep learning for lumbar disc herniation diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/42277705/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-05", "date": "2026-10-05", "title": "AI in Healthcare: Research Roundup — October 5, 2026", "excerpt": "Today's LLM-related additions cluster around evaluation and documentation rather than new diagnostic claims. A bibliometric review of 650 publications found…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Today's LLM-related additions cluster around evaluation and documentation rather than new diagnostic claims. A bibliometric review of 650 publications found LLM-diagnosis research growing at a 71.25% average quarterly rate since 2023, but noted this reflects rising academic interest rather than proven clinical validation. A comparative validation study of four LLMs (ChatGPT o3, DeepSeek v3, Gemini Flash 2.0, Grok 3) on risk-of-bias assessment for 200 randomized trials found agreement with human reviewers too low (kappa 0.06-0.39) for autonomous use, recommending supervised, second-assessor roles instead. On the documentation side, GPT-4o and Llama 3.1 405B extracted structured data from histopathology reports at 96.1% and 94.7% accuracy respectively — matching human annotators — while a pathology-validated study found Gemini 2.5 reached 79.1% diagnostic accuracy for cholesteatoma versus 84.0% for radiologic assessment. A new benchmark, HealthBench Professional, drawn from 15,079 real clinician conversations, found a clinician-tuned model scored 59.0 overall versus 43.7 for physician-written responses, with the largest gap on documentation tasks (64.1 vs. 32.1).", "On the ML/DL side, XGBoost-based models again delivered strong discrimination across varied conditions: AUC 0.898 (internal) and 0.819 (external) for HFpEF comorbidity risk in COPD patients, AUC 0.844 for postoperative acute kidney injury in CKD patients, and AUC up to 0.841 for high-grade cervical intraepithelial neoplasia. A SEER-based study of 2,427 pediatric neuroblastoma patients found XGBoost outperformed five other algorithms for overall survival prediction (AUC up to 0.807, C-index 0.784), enabling clear risk stratification. An explainable logistic regression model reached AUC 0.948 for advanced diabetic kidney disease risk, and a systematic review pooling 24 studies (>=1,000 patients each) found ML models for bloodstream infection diagnosis achieve good but not yet decision-grade accuracy (pooled SROC-AUC 0.87).", "Today's pattern continues: LLMs are increasingly being evaluated for narrower, supervised roles — bias detection, data extraction, documentation — rather than autonomous diagnosis, while gradient-boosted and explainable ML models keep posting high, well-validated discrimination for prognosis and risk stratification across oncology, renal, and cardiopulmonary conditions."], "refs": [{"title": "Bibliometric review of LLMs in medical diagnosis research", "url": "https://pubmed.ncbi.nlm.nih.gov/42327634/"}, {"title": "LLMs for risk-of-bias assessment in randomized clinical trials", "url": "https://pubmed.ncbi.nlm.nih.gov/41905260/"}, {"title": "LLM extraction of structured data from histopathology reports", "url": "https://pubmed.ncbi.nlm.nih.gov/41472471/"}, {"title": "Gemini 2.5 for pathology-validated cholesteatoma diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/42228449/"}, {"title": "HealthBench Professional benchmark on real clinician chats", "url": "https://arxiv.org/html/2604.27470v1"}, {"title": "Interpretable ML model for HFpEF comorbidity risk in COPD", "url": "https://pubmed.ncbi.nlm.nih.gov/42104441/"}, {"title": "XGBoost prognostic model for pediatric neuroblastoma survival", "url": "https://pubmed.ncbi.nlm.nih.gov/42592066/"}, {"title": "Systematic review of ML models for bloodstream infection diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/42665777/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-04", "date": "2026-10-04", "title": "AI in Healthcare: Research Roundup — October 4, 2026", "excerpt": "Today's LLM additions center on decision-support and triage roles rather than diagnosis itself. A Stanford-deployed, EHR-integrated LLM tool for recommending surgical…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Today's LLM additions center on decision-support and triage roles rather than diagnosis itself. A Stanford-deployed, EHR-integrated LLM tool for recommending surgical comanagement reached sensitivity of 0.94 and specificity of 0.74 against physicians' own decisions. A PSB benchmarking study found frontier models (o3, GPT-4o, Claude 4 Sonnet, Gemini 2.5 Pro, among others) could reach 92.2% comprehensiveness when drafting clinical consultation templates, but consistently failed to prioritize the most clinically important questions under length constraints. Equity-focused work on ChatGPT-4 found that race, housing status, and language proficiency did not shift its pain-management recommendations, but a history of opioid use disorder consistently did, toward more restrictive suggestions — a notable bias finding. In a blinded urogynecology comparison, ChatGPT-4's management recommendations scored statistically similarly to fellowship-trained specialists (6.1 vs. 5.8 on a 10-point scale), though it lagged on complex-reasoning cases.", "On the ML/DL side, nomogram-based models again delivered strong, well-validated discrimination across varied conditions: AUC 0.864 for thyroid nodule malignancy, 0.861 for polypoidal choroidal vasculopathy recurrence, and 0.864 for osteosarcopenia risk in type 2 diabetes. Risk and prognostic models also performed solidly in less commonly modeled areas — hypertension incidence (AUC 0.79, n=8,237), 28-day COPD mortality (AUC 0.772/0.795, n=1,817), and oral tongue squamous cell carcinoma survival (C-index up to 0.720, n=5,746 plus external validation). A smaller nomogram for severe Pneumocystis jirovecii pneumonia in kidney transplant recipients used just four biomarkers to stratify ICU/death risk with significant survival separation (p<0.0001).", "Today's pattern holds steady: LLMs are being tested and audited as assistive triage and consultation tools with mixed, task-dependent performance, while XGBoost- and logistic-regression-based nomograms continue to post reliable, well-calibrated discrimination for prognosis and diagnosis across oncology, cardiometabolic, and infectious disease."], "refs": [{"title": "EHR-integrated LLM tool for surgical comanagement triage", "url": "https://pubmed.ncbi.nlm.nih.gov/42623072/"}, {"title": "Bias in ChatGPT-4 pain management recommendations by patient profile", "url": "https://pubmed.ncbi.nlm.nih.gov/41875512/"}, {"title": "ChatGPT-4 vs. specialists in urogynecology case management", "url": "https://pubmed.ncbi.nlm.nih.gov/41921334/"}, {"title": "Benchmarking LLMs on clinical consultation templates", "url": "https://pubmed.ncbi.nlm.nih.gov/41758156/"}, {"title": "Diagnostic nomogram for thyroid nodule malignancy", "url": "https://pubmed.ncbi.nlm.nih.gov/42299289/"}, {"title": "ML model for polypoidal choroidal vasculopathy recurrence", "url": "https://pubmed.ncbi.nlm.nih.gov/42086315/"}, {"title": "Machine learning nomogram for osteosarcopenia risk in type 2 diabetes", "url": "https://pubmed.ncbi.nlm.nih.gov/42528576/"}, {"title": "Nomogram for severe Pneumocystis jirovecii pneumonia in kidney transplant recipients", "url": "https://pubmed.ncbi.nlm.nih.gov/41840841/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-03", "date": "2026-10-03", "title": "AI in Healthcare: Research Roundup — October 3, 2026", "excerpt": "On the LLM side, ophthalmology produced the strongest numbers: GPT-4.o, Claude 3.7, and Gemini 2.5 were tested on 40 real-world retina cases, with GPT-4.o leading…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["On the LLM side, ophthalmology produced the strongest numbers: GPT-4.o, Claude 3.7, and Gemini 2.5 were tested on 40 real-world retina cases, with GPT-4.o leading full-context diagnostic accuracy (78.4%) and Claude leading on image-only cases (73.7%); separately, GPT-4V matched expert OCT readings for wet AMD and fluid detection with over 90% agreement but fell to 68.7% sensitivity on dry AMD. Several papers pushed back on how LLMs are evaluated: one argues first-contact consultation behavior should be judged directly rather than inferred from diagnostic accuracy (baseline models gave premature self-care advice in 9 of 12 test cases without explicit instruction), another proposes a new rubric for scoring clinical reasoning, and a JMIR piece and an AJR commentary both caution that strong benchmark performance (an LLM matched or beat physicians at ER triage in one study) doesn't automatically translate to safe clinical deployment. On the patient-facing side, qualitative work with 60 patients, caregivers, and nurses found cautious openness to chatbots as adjunctive information tools rather than replacements for nurse-patient trust.", "On the ML/DL side, nomogram-based risk and diagnostic models kept posting strong discrimination: AUCs of 0.974/0.955 for tuberculous peritoneal effusion, 0.933/0.908 for post-neurosurgical bacterial meningitis, and 0.892 for distinguishing melanoma liver metastases from other origins. Risk-prediction models also performed well in acute care — an ROC-AUC of 0.951 for in-hospital mortality in non-ST-elevation ACS, and 0.886 for one-year postoperative pneumonia risk — while a random-forest model for sepsis-associated liver injury reached 0.816/0.781 across internal and external validation.", "Together, today's additions show LLM research increasingly focused on where and how to evaluate clinical reasoning and consultation behavior, while ML/DL prognostic and diagnostic nomograms continue to deliver high discrimination across acute and oncologic conditions."], "refs": [{"title": "Multimodal diagnostic accuracy of GPT-4.o, Claude 3.7, and Gemini 2.5 on retina cases", "url": "https://pubmed.ncbi.nlm.nih.gov/41797736/"}, {"title": "GPT-4V vs. expert assessment on OCT images of age-related macular degeneration", "url": "https://pubmed.ncbi.nlm.nih.gov/41904432/"}, {"title": "The preformulation gap in evaluating LLMs for medical consultation", "url": "https://arxiv.org/abs/2608.17330"}, {"title": "Qualitative study of AI chatbots in patient education (patients, caregivers, nurses)", "url": "https://pubmed.ncbi.nlm.nih.gov/42531560/"}, {"title": "Machine learning-based mortality risk prediction in NSTE-ACS", "url": "https://pubmed.ncbi.nlm.nih.gov/42616816/"}, {"title": "Machine learning prediction of long-term postoperative pneumonia risk", "url": "https://pubmed.ncbi.nlm.nih.gov/42218466/"}, {"title": "Diagnostic nomogram for tuberculous peritoneal effusion", "url": "https://pubmed.ncbi.nlm.nih.gov/42404577/"}, {"title": "Diagnostic nomogram for post-neurosurgical bacterial meningitis", "url": "https://pubmed.ncbi.nlm.nih.gov/42067788/"}], "lang": "en", "source": "ai"}, {"id": "ph-2026-09-25-argument-from-finality-design", "date": "2026-10-02", "title": "নকশার যুক্তি: অ্যাকুইনাসের পঞ্চম পথ", "title_en": "The Argument from Finality / Design (Aquinas's Five Ways)", "excerpt": "আপনি কি কখনো একটা আমগাছের বীজ পুঁতে দেখেছেন? মাটির নিচে সেই ছোট্ট বীজটার কোনো চোখ নেই, মাথা নেই, কোনো পরিকল্পনা করার ক্ষমতা নেই। অথচ প্রতিবার, ব্যতিক্রম ছাড়াই, সেটা ঠিক…", "theme": "faith", "cats": ["স্রষ্টার অস্তিত্বের যুক্তি", "দর্শন"], "body": ["আপনি কি কখনো একটা আমগাছের বীজ পুঁতে দেখেছেন? মাটির নিচে সেই ছোট্ট বীজটার কোনো চোখ নেই, মাথা নেই, কোনো পরিকল্পনা করার ক্ষমতা নেই। অথচ প্রতিবার, ব্যতিক্রম ছাড়াই, সেটা ঠিক আমগাছই হয়ে ওঠে। কখনো জামগাছ হয় না, কখনো এলোমেলো কিছু হয় না। কিংবা ভাবুন সূর্যমুখী ফুলের কথা। কোনো মস্তিষ্ক ছাড়াই সারাদিন সে সূর্যের দিকে মুখ ঘুরিয়ে রাখে, যেন কেউ তাকে শিখিয়ে দিয়েছে সূর্যের আলো কোথায় বেশি পাওয়া যাবে। মাছেরা হাজার মাইল সাঁতরে ঠিক সেই নদীতেই ফিরে আসে যেখানে তাদের জন্ম হয়েছিল। এসব জিনিসের কোনোটারই বুদ্ধি নেই, চিন্তাশক্তি নেই। তবু তারা প্রত্যেকে যেন একটা নির্দিষ্ট লক্ষ্যের দিকে ছুটছে। প্রশ্নটা হলো: বুদ্ধিহীন জিনিস কীভাবে বারবার, নিয়মিতভাবে একটা নির্দিষ্ট উদ্দেশ্যের দিকে এগোয়?", "এই প্রশ্ন থেকেই জন্ম নিয়েছে দর্শনের ইতিহাসের অন্যতম বিখ্যাত যুক্তি — থমাস আকুইনাসের \"পঞ্চম পথ\" (Fifth Way), যাকে বলা হয় \"চরম-উদ্দেশ্য থেকে যুক্তি\" বা \"নকশার যুক্তি\" (Argument from Finality / Design)। আজকের পোস্টে আমরা এই যুক্তিটা সহজ ভাষায় বোঝার চেষ্টা করব — এটা কী বলে, কেন এটাকে শক্তিশালী মনে করা হয়, আর কোথায় এর সবচেয়ে বড় সমালোচনাগুলো এসেছে।", "**প্রেক্ষাপটটুকু জেনে নেওয়া যাক**", "ত্রয়োদশ শতাব্দীর ইতালীয় খ্রিস্টান দার্শনিক ও ধর্মতাত্ত্বিক থমাস আকুইনাস তাঁর বিখ্যাত গ্রন্থ \"সুম্মা থিওলজিকা\"-তে ঈশ্বরের অস্তিত্ব প্রমাণের পাঁচটা পথ (Quinque Viae) দিয়েছিলেন। আমরা আগের কিছু পোস্টে দেখেছি পরিবর্তন থেকে যুক্তি, কার্যকারণ থেকে যুক্তি, সম্ভাব্যতা-অনিবার্যতা থেকে যুক্তি, আর পূর্ণতার মাত্রা থেকে যুক্তি। আজকেরটা তাঁর পঞ্চম ও শেষ পথ — যেটা প্রকৃতিতে থাকা \"লক্ষ্যমুখিতা\" বা উদ্দেশ্যপূর্ণতা থেকে শুরু হয়।", "আকুইনাস এখানে গ্রিক দার্শনিক অ্যারিস্টটলের একটা ধারণা ধার করেছেন, যাকে বলে \"চূড়ান্ত কারণ\" (final cause)। অ্যারিস্টটলের মতে, কোনো কিছু কেন ঘটে তা বোঝার একটা উপায় হলো জিজ্ঞেস করা — এটা কীসের জন্য ঘটছে, এর লক্ষ্য বা পরিণতি কী। যেমন, একটা বীজ কেন অঙ্কুরিত হয়? কারণ তার একটা \"স্বাভাবিক লক্ষ্য\" আছে। তা হল পূর্ণাঙ্গ গাছ হয়ে ওঠা। এই লক্ষ্যের দিকে ছুটে চলাটাই হলো \"ফাইনালিটি\" বা চরম-উদ্দেশ্য।", "**যুক্তিটা আসলে কী বলছে**", "আকুইনাসের যুক্তিটা মোটামুটি এভাবে সাজানো যায়:", "১. প্রকৃতিতে বুদ্ধিহীন জিনিসগুলো (গাছ, গ্রহ, পাথর, পানি) সবসময় একটা নির্দিষ্ট ফলাফলের দিকেই কাজ করে, এলোমেলোভাবে নয়। তারা প্রায় সবসময়, বা সবসময়, একইভাবে আচরণ করে যাতে সবচেয়ে ভালো ফলাফলটাই আসে।", "২. কিন্তু যার বুদ্ধি নেই, সে নিজে থেকে কোনো লক্ষ্য ঠিক করতে পারে না — যদি না কোনো বুদ্ধিমান সত্তা তাকে সেই লক্ষ্যের দিকে পরিচালিত করে। আকুইনাস নিজেই একটা চমৎকার উপমা দিয়েছেন: \"যার জ্ঞান নেই, সে কোনো লক্ষ্যের দিকে এগোতে পারে না, যদি না কোনো জ্ঞানী ও বুদ্ধিমান সত্তা তাকে পরিচালনা করে। যেমন, তীরের দিক ধনুর্ধর (তীরন্দাজ) দ্বারা নির্ধারিত হয়।\"", "৩. তীরটা নিজে জানে না সে কোথায় যাচ্ছে। তবু সে সঠিক লক্ষ্যে গিয়ে পৌঁছায়, কারণ একজন বুদ্ধিমান ধনুর্ধর তাকে ছুঁড়েছে। ঠিক তেমনই, প্রকৃতির প্রতিটা বুদ্ধিহীন জিনিস যে নিয়মিতভাবে তার লক্ষ্যের দিকে এগোয়, তার পেছনেও নিশ্চয়ই কোনো বুদ্ধিমান পরিচালনাকারী আছে।", "৪. তাই আকুইনাসের উপসংহার: \"সুতরাং এমন একজন বুদ্ধিমান সত্তা আছেন, যাঁর দ্বারা প্রকৃতির সব জিনিস তাদের লক্ষ্যের দিকে পরিচালিত হয়; আর এই সত্তাকেই আমরা ঈশ্বর বলি।\"", "**এটা প্যালির \"ঘড়ি-নির্মাতা\" যুক্তির মতো নয় — এই পার্থক্যটা জরুরি**", "এখানে একটা সাধারণ ভুল বোঝাবুঝি হয়, যেটা পরিষ্কার করা দরকার। অনেকে মনে করেন আকুইনাসের এই যুক্তি আঠারো শতকের উইলিয়াম প্যালির বিখ্যাত \"ঘড়ি-নির্মাতা\" (Watchmaker) যুক্তির মতোই — অর্থাৎ, প্রকৃতি এত জটিল আর নিখুঁতভাবে সাজানো যে এর পেছনে একজন নকশাকার থাকতেই হবে, যেমন একটা ঘড়ির জটিল কলকব্জা দেখে বুঝা যায় কোনো নির্মাতা এটা বানিয়েছে।", "কিন্তু দার্শনিক এডওয়ার্ড ফেজারের মতো আধুনিক থমিস্ট চিন্তাবিদরা জোর দিয়ে বলেন, এই দুটো যুক্তি আসলে মৌলিকভাবে আলাদা। প্যালির যুক্তি নির্ভর করে জটিলতার ওপর: একটা জিনিস যত জটিল, তত বেশি মনে হয় এটা কেউ বানিয়েছে। কিন্তু আকুইনাসের যুক্তি নির্ভর করে নিয়মতান্ত্রিকতার ওপর: এমনকি সবচেয়ে সাধারণ, সবচেয়ে সরল প্রাকৃতিক প্রক্রিয়াও (যেমন আগুন সবসময় তাপ ছড়ায়, বরফ সবসময় গলে পানি হয়) একটা নির্দিষ্ট ফলাফলের দিকেই যায়, এলোমেলোভাবে নয়। প্যালির যুক্তিতে উদ্দেশ্য যেন বাইরে থেকে চাপিয়ে দেওয়া, একজন কারিগরের হাতের মতো। আকুইনাসের যুক্তিতে উদ্দেশ্যটা জিনিসের ভেতরেই নিহিত — এটাকে বলা হয় \"অন্তর্নিহিত লক্ষ্যমুখিতা\" (immanent teleology)। তাই যেসব সমালোচনা প্যালির যুক্তিকে আঘাত করে, সেগুলো আকুইনাসের যুক্তিকে সরাসরি স্পর্শ নাও করতে পারে।", "**এই যুক্তির পক্ষে সবচেয়ে শক্তিশালী যুক্তি**", "এই যুক্তির শক্তি হলো এটা এমন কিছুর ওপর দাঁড়িয়ে আছে যা আমরা প্রতিনিয়ত দেখি — প্রকৃতির নিয়মতান্ত্রিকতা। বিজ্ঞান নিজেই এই নিয়মিততার ওপর নির্ভরশীল। রসায়নে সোডিয়াম সবসময় ক্লোরিনের সাথে মিলে লবণই তৈরি করে, সোনা তৈরি করে না। পদার্থবিজ্ঞানের সূত্রগুলো নির্দিষ্ট ফলাফলের দিকে নির্দেশ করে বলেই আমরা ভবিষ্যদ্বাণী করতে পারি। প্রশ্ন হলো- এই নিয়মিততা কোত্থেকে এলো? কেন কার্যকারণ সবসময় একই দিকে নির্দিষ্টভাবে যায়, এলোমেলোভাবে যায় না? আকুইনাসের যুক্তি বলে, এই প্রশ্নের সবচেয়ে যুক্তিসঙ্গত উত্তর হলো- কোনো বুদ্ধিমান সত্তা এই নিয়মিততাকে স্থির করে রেখেছেন।", "**সবচেয়ে শক্তিশালী আপত্তিগুলো**", "তবে এই যুক্তির বিরুদ্ধে দর্শনের ইতিহাসে বেশ কিছু আপত্তি এসেছে।", "প্রথমত, স্কটিশ দার্শনিক ডেভিড হিউম প্রশ্ন তোলেন — আমরা যে প্রকৃতিতে \"উদ্দেশ্য\" দেখি, সেটা কি সত্যিই প্রকৃতিতে আছে, নাকি এটা আমাদের নিজেদের মনের একটা প্রক্ষেপণ? মানুষ যেহেতু নিজে উদ্দেশ্য নিয়ে কাজ করে, তাই সে প্রকৃতির যেকোনো নিয়মিত আচরণকেও \"উদ্দেশ্যপূর্ণ\" হিসেবে দেখতে চায়। এটা একধরনের উপমা মাত্র, প্রমাণ নয়। আধুনিক মনোবিজ্ঞানও একই কথা বলে -  মানুষের মস্তিষ্ক প্যাটার্ন খুঁজতে এবং র‍্যান্ডম জিনিসের মধ্যেও উদ্দেশ্য বা এজেন্সি আরোপ করতে স্বভাবতই ঝুঁকে থাকে।", "দ্বিতীয়ত, ডারউউনবাদকে এই যুক্তির জন্য সবচেয়ে বড় চ্যালেঞ্জ হিসেবে দেখা হত। ডারউইনের আগে মনে করা হতো, জীবজগতের প্রতিটা প্রাণী বা অঙ্গ এমনভাবে সাজানো যেন সেটা একটা নির্দিষ্ট উদ্দেশ্য পূরণের জন্যই তৈরি — যেমন চোখ দেখার জন্য, ডানা ওড়ার জন্য। কিন্তু ডারউইনবাদীরা দেখালেন, প্রকৃতিতে এলোমেলো ভ্যারিয়েশন আর প্রাকৃতিক নির্বাচনের মাধ্যমে, লক্ষ লক্ষ বছর ধরে, কোনো পরিকল্পনাকারী ছাড়াই এমন জটিল, উদ্দেশ্যপূর্ণ-দেখতে গঠন তৈরি হতে পারে। যেটা ভালো কাজ করে, সেটা টিকে থাকে; যেটা কাজ করে না, সেটা হারিয়ে যায়। ফলে \"উদ্দেশ্য\" আসলে উদ্দেশ্য না হয়ে হয়ে ওঠে কেবল \"যা টিকে গেছে তার ফলাফল।\" তবে, আধুনিক জীববিদ্যার গবেষণার আলোকে এই ডারউইনবাদী ‘এলোমেলো’ মিউটেশন তত্ত্বের অ্যাবসার্ডিটি অনেক জীববিজ্ঞানের কাছেই বাতিল বলে গন্য হয়েছে। সুতরাং, এই চ্যালেঞ্জও এখন বড় কিছু না।", "যাই হোক, আধুনিক থমিস্ট দার্শনিকরা ডারউইনাবাদীর চ্যালেঞ্জের জবাবে বলেন, ডারউইনের তত্ত্ব ব্যাখ্যা করে কীভাবে প্রজাতি বদলায় — অর্থাৎ প্রক্রিয়াটার \"কীভাবে\" অংশ। কিন্তু এটা এই গভীর প্রশ্নের উত্তর দেয় না যে, কেন প্রকৃতির নিয়মগুলো (যেগুলোর ওপর ভিত্তি করেই বিবর্তন কাজ করে) নিজেরাই এত নিয়মিত ও নির্দিষ্ট ফলাফলমুখী। সমালোচকরা অবশ্য এই জবাবকেও গ্রহণ করতে আগ্রহী না — তাদের যুক্তি, এভাবে প্রশ্নটাকে সরিয়ে নেওয়া (goalpost সরানো) আসলে যুক্তিটাকে এমন একটা জায়গায় নিয়ে যায় যেখানে একে আর পরীক্ষা করে ভুল প্রমাণ করা যায় না।", "তৃতীয় আপত্তিটা হলো, তীর আর ধনুর্ধরের উপমাটা নিজেই প্রশ্নবিদ্ধ। তীর সত্যিই বুদ্ধিহীন, আর তার গতিপথ বাইরে থেকে একজন মানুষ ঠিক করে দেন — এটা প্যালির মতোই \"বাহ্যিক\" ডিজাইনের উদাহরণ। কিন্তু একটা বীজ বা একটা রাসায়নিক বিক্রিয়ার \"লক্ষ্যমুখিতা\" কি সত্যিই তীরের মতো বাইরে থেকে চাপানো, নাকি এটা সম্পূর্ণ ভিন্ন ধরনের ব্যাপার? সমালোচকরা বলেন উপমাটা যতটা পরিষ্কার মনে হয়, ততটা নিখুঁত নয়। তবে, একজন চিন্তাশীলের কাছে বিষয়টা পরিস্কার যে, রাসায়নিক বিক্রিয়াকে কোন কিছু উৎপাদনে কাজে লাগাতে হলে নিয়ন্ত্রণ স্থাপন করতে হয় এবং লক্ষ্য নির্ধারন করে দিতে হয়। নাহলে তা কোন গঠনমূলক উন্নত কাঠামোর দিকে স্বয়ংক্রিয়ভাবে ধাবিত হয় না।", "**শেষ কথা**", "এই যুক্তিটা শেষ পর্যন্ত আমাদের একটা গভীর প্রশ্নের সামনে দাঁড় করিয়ে দেয় — প্রকৃতির নিয়মিততা কি নিছক একটা \"ঘটনা\", নাকি এর পেছনে কোনো ব্যাখ্যা থাকা দরকার? আপনি যখন দেখেন একটা বীজ বারবার নির্দিষ্ট গাছ হয়ে ওঠে, বা মহাবিশ্বের সূত্রগুলো নিখুঁতভাবে একই রকম আচরণ করে চলেছে যুগের পর যুগ — সেটা কি আপনার কাছে কোনো মনের ছাপ বলে মনে হয় না? নাকি মনে হয় এটা কেবল দীর্ঘ সময় ধরে যা টিকে গেছে তারই ফল, যাতে বাড়তি কোনো ব্যাখ্যার দরকার নেই? আপনি কি কখনও কোন মাইন্ডলেস বস্তুকে নলেজ জেনারেট করতে দেখেছেন?"], "source": "philosophy"}, {"id": "ai-2026-10-02", "date": "2026-10-02", "title": "AI in Healthcare: Research Roundup — October 2, 2026", "excerpt": "On the LLM side, today's additions skew toward diagnostic and decision-support benchmarking rather than new clinical deployments. A conversational diagnostic AI (AMIE)…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["On the LLM side, today's additions skew toward diagnostic and decision-support benchmarking rather than new clinical deployments. A conversational diagnostic AI (AMIE) completed text-chat history-taking with 100 primary-care patients and included the correct diagnosis in its differential 90% of the time (75% top-3 accuracy), with no safety-supervisor interventions needed. Comparative studies were more mixed: ChatGPT o1-preview reached 68.6% concordance with pathologist consensus on oral histopathology descriptions (versus 27.5% for Gemini), and ChatGPT-3.5/4.0 outperformed Bard and Bing on neuro-ophthalmology diagnostic questions. A few-shot triage-categorization benchmark found Claude Haiku 4.5 edging out a supervised BioBERT baseline (macro-F1 0.475 vs. 0.378) but still struggling on ambiguous urgent-review cases, and a separate benchmark found generalist models (GPT-5, Gemini 3 Pro, Claude Sonnet 4.5) outperforming two deployed clinical AI tools on combined medical-knowledge and clinician-alignment tasks. A Nature review mapped security and safety hazards across the clinical LLM development pipeline, and a JMIR perspective argued human-in-the-loop review remains an essential accountability guardrail.", "On the ML/DL side, today's models spanned imaging, oncology, and endocrinology. A deep learning model trained on over 62,000 UK Biobank retinal photographs predicted Alzheimer's-linked risk factors (AUROC up to 0.95), and a nationwide transformer-based model flagged young-onset type 2 diabetes with the highest-risk decile showing a 118-fold relative risk 3-15 months before diagnosis. In oncology, a weakly supervised deep learning model stratified lung adenocarcinoma recurrence risk from whole-slide pathology images with external validation, a Random Survival Forest model predicted early-stage NSCLC survival across a SEER and an independent Chinese cohort (C-index 0.74-0.78), and an XGBoost model reached over 90% accuracy on multimodal breast cancer survival prediction. Elsewhere, an XGBoost-and-SHAP nomogram detected PCOS with AUCs of 0.92 (internal) and 0.92 (external), and a GLM-based nomogram distinguished thrombocytopenia etiology with an AUC of 0.945.", "Together, today's findings show LLM-based diagnostic and triage tools continuing to close the gap with clinician and supervised-model baselines on narrow tasks, while ML/DL risk and diagnostic models keep posting high discrimination (AUCs above 0.90) across a wide range of disease areas."], "refs": [{"title": "Conversational diagnostic AI (AMIE) feasibility study in primary care", "url": "https://arxiv.org/abs/2603.08448"}, {"title": "LLMs as decision-support tools in oral pathology", "url": "https://pubmed.ncbi.nlm.nih.gov/41760843/"}, {"title": "Few-shot LLMs for actionable triage categorization", "url": "https://arxiv.org/abs/2605.15680"}, {"title": "Generalist LLMs outperform clinical tools on medical benchmarks", "url": "https://arxiv.org/abs/2512.01191"}, {"title": "Deep learning retinal imaging model for Alzheimer's risk factors", "url": "https://pubmed.ncbi.nlm.nih.gov/42299837/"}, {"title": "Deep learning model for young-onset type 2 diabetes risk", "url": "https://pubmed.ncbi.nlm.nih.gov/42619209/"}, {"title": "Weakly supervised deep learning recurrence model for lung adenocarcinoma", "url": "https://pubmed.ncbi.nlm.nih.gov/42286527/"}, {"title": "XGBoost and SHAP nomogram for PCOS detection", "url": "https://pubmed.ncbi.nlm.nih.gov/41480359/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-10-01", "date": "2026-10-01", "title": "AI in Healthcare: Research Roundup — October 1, 2026", "excerpt": "On the LLM side, today's additions center on clinical decision support and triage rather than diagnosis. ChatGPT (GPT-4) showed considerable-to-almost-perfect agreement…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["On the LLM side, today's additions center on clinical decision support and triage rather than diagnosis. ChatGPT (GPT-4) showed considerable-to-almost-perfect agreement with emergency physicians managing 792 traumatic laceration cases (82.6%-91.7% accuracy), and GPT-4o feedback on clinical note quality was found non-inferior to physician feedback in a discharge-planning documentation study. A postoperative decision-support pilot in a Gambian neurosurgery ward improved management-plan quality in 60% of 75 LLM-assisted interactions, with 14 care changes attributed to the tool. Triage work was more cautionary: a new benchmark (CARE-Bench) found prompted models preserved the correct \"ask for clarification\" step only 33.5% of the time, and a 15-chatbot psychiatric triage study found average accuracy of 42.0%-71.8% with a net over-triage bias. A related paper argued emergency-triage LLMs need explicit decision objectives, not just better predictions, after a consumer system under-triaged over half of gold-standard emergencies.", "On the ML/DL side, risk-prediction models again showed strong, disease-specific performance. LightGBM reached an AUC of 0.966 predicting multidrug-resistant infection in ICU COPD patients, and a benchmark of 10 models across eight hospital datasets found gradient-boosting methods (especially CatBoost) and the TabPFN tabular foundation model most consistently robust. A 2.5D deep learning model using multiparametric MRI predicted prostate cancer biochemical recurrence with AUCs of 0.938 (internal) and 0.935 (external validation), and a dual-task deep learning model for head-and-neck cancer radiotherapy achieved C-indices of 0.92 and 0.74 for metastasis and recurrence risk. Separately, a CNN-XGBoost hybrid improved demographic fairness in chest X-ray diagnosis without sacrificing accuracy.", "Together, today's findings suggest LLM decision-support tools are approaching clinician-level agreement in narrow, well-defined tasks, while triage remains an open problem; ML/DL risk models continue to post high discrimination (AUCs above 0.93) on disease-specific prediction."], "refs": [{"title": "ChatGPT agreement with emergency physicians on laceration management", "url": "https://pubmed.ncbi.nlm.nih.gov/42386488/"}, {"title": "GPT-4 quality-improvement feedback for clinical notes", "url": "https://pubmed.ncbi.nlm.nih.gov/41985489/"}, {"title": "LLM postoperative decision support in a Gambian neurosurgery ward", "url": "https://pubmed.ncbi.nlm.nih.gov/41697048/"}, {"title": "CARE-Bench: benchmarking patient-facing LLM triage", "url": "https://arxiv.org/abs/2608.03731"}, {"title": "One-shot emergency psychiatric triage across 15 AI chatbots", "url": "https://arxiv.org/abs/2604.25415"}, {"title": "High-stakes decision-making with language models in emergency triage", "url": "https://arxiv.org/abs/2608.01361"}, {"title": "Machine learning risk model for multidrug resistance in ICU COPD patients", "url": "https://pubmed.ncbi.nlm.nih.gov/42180772/"}, {"title": "Benchmark of 10 ML models for clinical risk prediction", "url": "https://pubmed.ncbi.nlm.nih.gov/42063551/"}, {"title": "2.5D deep learning model for prostate cancer recurrence", "url": "https://pubmed.ncbi.nlm.nih.gov/41417975/"}, {"title": "Dual-task deep learning model for head-and-neck cancer radiotherapy outcomes", "url": "https://pubmed.ncbi.nlm.nih.gov/42595266/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-30", "date": "2026-09-30", "title": "AI in Healthcare: Research Roundup — September 30, 2026", "excerpt": "On the LLM side, today's additions cluster around clinical decision support and documentation rather than diagnosis benchmarks. In primary immune disorders, GPT-4o…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["On the LLM side, today's additions cluster around clinical decision support and documentation rather than diagnosis benchmarks. In primary immune disorders, GPT-4o reached 96.2% diagnostic accuracy on real-world case vignettes across six tested LLMs, well ahead of smaller open models (as low as 42.3%). A retrieval-augmented LLM system for medication safety, tested against 91 prescribing-error scenarios across 16 specialties, worked best as a pharmacist \"co-pilot\" (61% accuracy), increasing detection of serious-harm errors 1.5-fold over pharmacists alone. A tailored small language model for breast cancer guidelines matched ChatGPT-4's concordance with tumor-board recommendations (86% vs. 90%), while a tool-calling chatbot backed by verified clinical calculators eliminated calculation errors entirely versus a stand-alone LLM (0% vs. 16.8%). On documentation, Note2Chat improved diagnostic accuracy from multi-turn history-taking by +21 points over GPT-4o, and separate work found GPT-4/Gemini-based discharge-summary generation judged clinically useful despite residual hallucination risk. A regional-anesthesia study was more cautionary: four chatbot platforms missed key safety issues like anticoagulation and informed-consent gaps in complex consult scenarios.", "On the ML/DL side, disease-specific prognostic and diagnostic models again showed strong discrimination. An SFTS mortality model using five routine lab values reached an AUC of 0.913 (test) and 0.923 (external validation). XGBoost hit 98.6% AUROC diagnosing sepsis-associated thrombocytopenia across two centers, outperforming Random Forest and ANN. A radiomics-clinical model improved survival prediction for lung adenocarcinoma brain metastasis, and a CT-radiomics random forest model differentiated malignant from benign endometrial tumors with 0.96 testing AUROC. On the deep-learning front, a time-aware attention framework (TA-RNN-Medical-Hybrid) improved ICU mortality prediction over sequential baselines, longitudinal deep-learning mammogram risk scores rose sharply (2.1 to 6.6) in the years before a breast cancer diagnosis versus flat scores in cancer-free women, and a multimodal EHR-plus-notes model improved ICU mortality, length-of-stay, and surgical-duration predictions over structured-data-only baselines.", "Taken together, today's LLM findings emphasize where clinical language models still need human oversight (medication safety, anesthesia consults), while ML/DL models continue to deliver consistent, disease-specific predictive accuracy validated with AUCs above 0.90."], "refs": [{"title": "LLM performance on primary immune disorder diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/39956279/"}, {"title": "LLM clinical decision support for medication safety across 16 specialties", "url": "https://pubmed.ncbi.nlm.nih.gov/40997804/"}, {"title": "Small language model chatbot for breast cancer decision support", "url": "https://pubmed.ncbi.nlm.nih.gov/39382778/"}, {"title": "LLM-powered clinical calculator chatbot", "url": "https://arxiv.org/abs/2503.17550"}, {"title": "Note2Chat: LLMs for multi-turn clinical history taking", "url": "https://arxiv.org/abs/2601.21551"}, {"title": "Machine learning approach for early SFTS prognosis", "url": "https://pubmed.ncbi.nlm.nih.gov/42382680/"}, {"title": "XGBoost for diagnosing sepsis-associated thrombocytopenia", "url": "https://pubmed.ncbi.nlm.nih.gov/41737408/"}, {"title": "Longitudinal deep learning breast cancer risk scores", "url": "https://pubmed.ncbi.nlm.nih.gov/42334348/"}, {"title": "CT radiomics ML model for endometrial tumor differentiation", "url": "https://arxiv.org/abs/2506.18106"}], "lang": "en", "source": "ai"}, {"id": "ph-2026-09-22-argument-from-degrees-of-perfection", "date": "2026-09-29", "title": "পূর্ণতার মাত্রার যুক্তি: অ্যাকুইনাসের চতুর্থ পথ", "title_en": "The Argument from Degrees of Perfection (Aquinas's Five Ways)", "excerpt": "পূর্ণতার মাত্রার যুক্তি: \"ভালো\", \"আরও ভালো\", \"সবচেয়ে ভালো\" - এই তুলনাটা করতে গেলে কি আমাদের একটা অদৃশ্য মাপকাঠি লাগে?", "theme": "faith", "cats": ["স্রষ্টার অস্তিত্বের যুক্তি", "দর্শন"], "body": ["পূর্ণতার মাত্রার যুক্তি: \"ভালো\", \"আরও ভালো\", \"সবচেয়ে ভালো\" - এই তুলনাটা করতে গেলে কি আমাদের একটা অদৃশ্য মাপকাঠি লাগে?", "একটু ভাবুন তো - আপনি যখন বলেন \"উনি খুব সৎ মানুষ, কিন্তু ঐ ভদ্রলোক তার চেয়েও সৎ\", তখন আপনার মাথায় আসলে কী ঘটছে? আপনি দুজন মানুষকে মেপে দেখছেন, আর একজনকে অন্যজনের চেয়ে \"সততার দিক দিয়ে এগিয়ে\" রাখছেন। কিন্তু এই এগিয়ে-পিছিয়ে থাকার হিসাবটা করতে গেলে আপনার মনে কি এমন একটা ধারণা কাজ করছে না যে - কোথাও একটা \"পুরোপুরি সৎ\" বলে কিছু একটা আছে, যার সাথে তুলনা করেই আমরা কাউকে কম বা বেশি সৎ বলছি? একই কথা খাটে যখন আমরা বলি একটা ছবি আরেকটার চেয়ে \"বেশি সুন্দর\", একটা যুক্তি আরেকটার চেয়ে \"বেশি সত্য\", বা একটা কাজ আরেকটার চেয়ে \"বেশি মহৎ\"। প্রতিটা ক্ষেত্রেই আমরা যেন একটা অদৃশ্য স্কেলে জিনিসগুলোকে বসাচ্ছি, আর সেই স্কেলের একটা প্রান্তে আছে \"সম্পূর্ণ\", \"চূড়ান্ত\", \"সর্বোচ্চ\" কিছু একটা - যদিও বাস্তবে আমরা হয়তো কখনো সেই চূড়ান্ত জিনিসটা চোখে দেখিনি। এখন প্রশ্ন হলো - এই তুলনা করার ক্ষমতাটা কি স্রেফ আমাদের মনের একটা খেলা, নাকি এর পেছনে সত্যিই বাস্তবে এমন কিছু থাকা দরকার যেটা \"সর্বোচ্চ পূর্ণতা\" ধারণ করে? এই প্রশ্নটাই থমাস আকুইনাসের বিখ্যাত \"পাঁচটি পথ\"-এর চতুর্থ পথের মূল কথা - \"পূর্ণতার মাত্রার যুক্তি\" (Argument from Degrees of Perfection), যাকে অনেকে \"গ্রেডেশনের যুক্তি\" (Argument from Gradation)-ও বলেন। আগের তিন পর্বে আমরা দেখেছি পরিবর্তনের যুক্তি, নিমিত্ত কারণের যুক্তি, আর সময়-সম্ভাব্যতার যুক্তি - আজকের এই চতুর্থ পথটা আগের তিনটার চেয়ে একেবারে আলাদা স্বাদের, কারণ এটা কার্যকারণ নয়, বরং তুলনা আর মূল্যবোধ নিয়ে কথা বলে।", "যুক্তিটা কোথা থেকে এলো", "আকুইনাস তার \"সুম্মা থিওলজিকা\" গ্রন্থের প্রথম ভাগে (প্রশ্ন ২, অনুচ্ছেদ ৩) এই চতুর্থ পথটা শুরু করেন একটা সাধারণ পর্যবেক্ষণ দিয়ে - আমরা জিনিসের মধ্যে \"কম-বেশি\" পার্থক্য দেখি। কিছু জিনিস অন্য জিনিসের চেয়ে বেশি ভালো, বেশি সত্য, বেশি মহৎ - এভাবেই আমরা কথা বলি প্রতিদিন। আকুইনাস এখানে অ্যারিস্টটলের একটা নীতি ধার করেন - কোনো একটা গুণের তুলনা তখনই সম্ভব যখন সেই গুণটা কোনো না কোনো \"সর্বোচ্চ মাত্রার\" সাথে তুলনা করে মাপা হয়। যেমন কোনো জিনিস \"বেশি গরম\" তখনই বলা যায় যখন সেটা সবচেয়ে গরম জিনিসটার (আগুনের) কাছাকাছি থাকে। আকুইনাসের মূল দাবিটা হলো - \"সত্তা\" (being), \"ভালোত্ব\" (goodness), \"সত্যতা\" (truth), আর \"মহত্ত্ব\" (nobility) - এই গুণগুলোর ক্ষেত্রেও একই যুক্তি খাটে। যেহেতু জিনিসগুলো এসব গুণে কম-বেশি অংশীদার, তাই কোথাও একটা এমন কিছু থাকতে হবে যেটা এই গুণগুলোর সর্বোচ্চ মাত্রায় ধারণ করে, আর সেটাই বাকি সবকিছুতে ঐ গুণের উৎস।", "মূল ধারণা সহজ ভাষায়", "আকুইনাস অ্যারিস্টটলের একটা উদাহরণ ব্যবহার করেন - আগুন হলো সবচেয়ে গরম জিনিস, আর প্রাচীন পদার্থবিজ্ঞানের ধারণা অনুযায়ী আগুনই অন্য জিনিসকে গরম করে তোলে, অর্থাৎ যে গুণে আগুন সর্বোচ্চ মাত্রায় আছে, সেই গুণটা আগুনই অন্য জিনিসে সঞ্চার করে। এখন এই একই যুক্তি যদি \"ভালোত্ব\" বা \"সত্যতা\"-র মতো গুণে প্রয়োগ করি, তাহলে দাঁড়ায় - যেহেতু জগতে জিনিস কম-বেশি ভালো, কম-বেশি সত্য, কম-বেশি পূর্ণ, তাই কোথাও একটা সত্তা থাকতে হবে যেটা সর্বোচ্চ মাত্রায় ভালো, সর্বোচ্চ মাত্রায় সত্য, সর্বোচ্চ মাত্রায় পূর্ণ - আর সেই সর্বোচ্চ সত্তাই বাকি সব কিছুর মধ্যে এই গুণগুলোর কারণ। এখানে একটা গুরুত্বপূর্ণ ধারণা কাজ করে, যেটাকে দর্শনে বলে \"অংশগ্রহণ\" বা \"পার্টিসিপেশন\" (participation) - প্লেটোর কাছ থেকে ধার করা একটা ধারণা, যদিও আকুইনাস নিজে অ্যারিস্টটলীয় দর্শনের অনুসারী। ধারণাটা এমন - যে জিনিস কোনো গুণ পুরোপুরি নিজে থেকে ধারণ করে না, বরং আংশিকভাবে ধারণ করে, সেটা আসলে সেই গুণের একটা উৎস থেকে \"ধার\" নিচ্ছে, \"অংশ\" নিচ্ছে। একটা মোমবাতির আলো যেমন সূর্যের আলোর একটা ক্ষীণ প্রতিফলন না হলেও, তুলনামূলকভাবে বোঝার জন্য বলা যায়। ঠিক তেমনি, আংশিক ভালোত্ব বা আংশিক সত্যতা যেন পূর্ণ ভালোত্ব বা পূর্ণ সত্যতার একটা \"ছায়া\" বা \"অংশ\"। আকুইনাসের যুক্তিতে এই সর্বোচ্চ পূর্ণতার উৎসটাই ঈশ্বর।", "যুক্তির কাঠামো", "পুরো যুক্তিটা ধাপে ধাপে এভাবে সাজানো যায়:", "১) আমরা জিনিসের মধ্যে গুণের কম-বেশি মাত্রা দেখি - কিছু জিনিস অন্যের চেয়ে বেশি ভালো, বেশি সত্য, বেশি মহৎ, বেশি পূর্ণ (এগুলোকে দর্শনে বলে \"ট্রান্সেন্ডেন্টাল\" বা অতিক্রমী গুণ - কারণ এগুলো সত্তার সাথেই অবিচ্ছেদ্যভাবে জড়িত)।", "২) কোনো গুণের তুলনামূলক মাত্রা বোঝা যায় শুধু তখনই, যখন সেই গুণের একটা সর্বোচ্চ মান বা মানদণ্ডের সাথে তুলনা করা হয় - যেমন \"বেশি গরম\" বোঝা যায় \"সবচেয়ে গরম\"-এর সাপেক্ষে।", "৩) সুতরাং যেহেতু জিনিস কম-বেশি ভালো, সত্য, মহৎ, পূর্ণ, তাই কোথাও একটা এমন কিছু থাকতে হবে যেটা সর্বোচ্চ মাত্রায় ভালো, সত্য, মহৎ, পূর্ণ - অর্থাৎ সম্পূর্ণরূপে সত্তাশীল।", "৪) যে জিনিস কোনো গুণে সর্বোচ্চ মাত্রায় থাকে, সেটাই সেই গুণের উৎস হিসেবে বাকি সবকিছুতে সেই গুণ সঞ্চার করে (অ্যারিস্টটলের নীতি অনুযায়ী)।", "৫) সুতরাং একটা এমন সত্তা থাকতে হবে যেটা সব জিনিসের ভালোত্ব, সত্যতা, মহত্ত্ব আর সত্তার (being) কারণ।", "৬) এই পরম পূর্ণ সত্তাকেই আকুইনাস বলেন ঈশ্বর।", "একটা জরুরি স্পষ্টীকরণ - এটা যেকোনো গুণ নিয়ে না", "এই যুক্তিটা নিয়ে সবচেয়ে বড় ভুল বোঝাবুঝি হয় এইখানে - অনেকে ভাবেন আকুইনাস বলছেন, জগতে যেকোনো গুণের তুলনা করলেই একটা \"সর্বোচ্চ উদাহরণ\" থাকতে হবে। নাস্তিক রিচার্ড ডকিন্স তার \"দ্য গড ডিলিউশন\" বইতে ঠিক এই আপত্তিটাই তোলেন - তিনি বলেন, মানুষ কম-বেশি \"দুর্গন্ধময়\" হতে পারে, তার মানে কি এই দাঁড়ায় যে কোথাও একটা \"সবচেয়ে দুর্গন্ধময় সত্তা\" থাকতে হবে, আর সেটাই ঈশ্বর? এই ব্যঙ্গাত্মক উদাহরণ দিয়ে ডকিন্স যুক্তিটাকে হাস্যকর বানানোর চেষ্টা করেন। কিন্তু আধুনিক থোমিস্ট দার্শনিক এডওয়ার্ড ফেজার (Edward Feser) দেখান যে এটা মূল যুক্তিটাকেই ভুল বোঝা। কারণ, আকুইনাস দুর্গন্ধ, স্বাদ, রং-এর মতো এলোমেলো, আপেক্ষিক, বস্তুনির্ভর গুণ নিয়ে কথা বলছেন না। তিনি কথা বলছেন নির্দিষ্ট কিছু \"ট্রান্সেন্ডেন্টাল\" গুণ নিয়ে, যেমন- সত্তা, ভালোত্ব, সত্যতা, মহত্ত্ব। এগুলোকে মধ্যযুগীয় দর্শনে সত্তার সাথেই অভিন্ন বলে গণ্য হয়, আর যেগুলোর একটা নির্দিষ্ট, বিশ্লেষণযোগ্য কাঠামো আছে বলে দাবি করা হয়। দুর্গন্ধ কোনো \"ট্রান্সেন্ডেন্টাল\" গুণ না, তাই এই যুক্তি সেখানে খাটেই না।", "সবচেয়ে শক্তিশালী সমর্থন কী", "এই যুক্তির আসল শক্তি এখানে যে এটা আমাদের নৈতিক আর মূল্যবোধ সংক্রান্ত ভাষার একটা গভীর অনুমানের দিকে আঙুল তোলে। আমরা যখন বলি হিটলারের কাজ নিরো-র চেয়েও নিষ্ঠুর ছিল, বা মাদার তেরেসার কাজ একজন সাধারণ মানুষের চেয়ে বেশি মহৎ ছিল, তখন আমরা যেন ধরেই নিচ্ছি যে নিষ্ঠুরতা বা মহত্ত্বের একটা বাস্তব, বস্তুনিষ্ঠ মানদণ্ড আছে - এটা স্রেফ ব্যক্তিগত পছন্দের বিষয় না। যদি নৈতিকতা বা সত্য নিছক আপেক্ষিক হতো, তাহলে \"বেশি ভালো\" বলাটাই অর্থহীন হয়ে যেত - ঠিক যেমন \"বেশি লাল\" বলার কোনো মানে হয় না যদি লাল রঙের কোনো নির্দিষ্ট মান না থাকে। এই যুক্তি তাই নৈতিক বাস্তববাদ (moral realism)-এর একটা আধিভৌতিক ভিত্তি দেওয়ার চেষ্টা করে। এটি বলে যে আমাদের মূল্যবোধের ভাষা নিছক কল্পনা না, বরং বাস্তবতার একটা গভীর কাঠামোর প্রতিফলন। আর যদি এই পূর্ণতার একটা চূড়ান্ত উৎস থাকে, তাহলে সেটা একইসাথে আগের তিনটা পথে পাওয়া \"প্রথম কারণ\" আর \"আবশ্যিক সত্তা\"-র সাথেও মিলে যায়। যেন সবগুলো পথ একই সিদ্ধান্তের দিকে বিভিন্ন কোণ থেকে এগিয়ে আসছে।", "এবার আসি সমালোচনার দিকে", "প্রথম আর সবচেয়ে গুরুত্বপূর্ণ আপত্তিটা আসে দার্শনিক অ্যান্টনি কেনির (Anthony Kenny) কাছ থেকে। কেনি বলেন, আকুইনাস যে ধরে নেন \"সর্বোচ্চ মাত্রার জিনিসটাই বাকি সবকিছুতে সেই গুণ সঞ্চার করে\" - এই নীতিটা আসলে অ্যারিস্টটলের সেকেলে পদার্থবিজ্ঞান থেকে ধার করা, যেখানে ভাবা হতো আগুনই তাপের উৎস। কিন্তু আধুনিক বিজ্ঞান আমাদের দেখায়, তাপ আসলে অণুর গতি, আগুন কোনো বিশেষ \"তাপের মূল ভান্ডার\" না। তাই যে বৈজ্ঞানিক ভিত্তির ওপর এই সাদৃশ্যটা দাঁড়িয়ে, সেটাই এখন ভুল প্রমাণিত। এখান থেকে কেনির মূল অভিযোগ - সাদৃশ্য বা তুলনা থেকে কার্যকারণ অনুমান করাটাই একটা ভুল লাফ; দুটো জিনিস একই গুণে অংশীদার হলেই তার মানে এই না যে একটা আরেকটার কারণ। ফেজারের মতো থোমিস্টরা জবাব দেন যে আকুইনাসের মূল যুক্তিটা আসলে অ্যারিস্টটলের নির্দিষ্ট পদার্থবিজ্ঞানের ওপর নির্ভরশীল না, বরং একটা সাধারণ আধিভৌতিক নীতির ওপর নির্ভরশীল - যা কিছু কোনো পূর্ণতা কেবল আংশিকভাবে ধারণ করে, তাকে সেই পূর্ণতা কোনো বাহ্যিক উৎস থেকে পেতে হয়, কারণ সে নিজে থেকে সেই পূর্ণতার ব্যাখ্যা দিতে পারে না। তবে সমালোচকরা বলেন, এই সাধারণ নীতিটা নিজেই একটা প্রমাণ ছাড়া অনুমান, যা মেনে নেওয়ার আগে আরও যুক্তির দরকার।", "দ্বিতীয় আপত্তিটা হলো একটা যৌক্তিক ফাঁক নিয়ে - এমনকি যদি মেনেও নিই কোনো গুণের তুলনা করতে একটা \"সর্বোচ্চ মানদণ্ড\" লাগে, তার মানে এই না যে সেই মানদণ্ডটা বাস্তবে অস্তিত্বশীল কোনো সত্তা হতে হবে, বা সেটাই বাকি সবকিছুর কারণ হতে হবে। একটা ক্লাসে সবচেয়ে লম্বা ছাত্রটা অন্য ছাত্রদের লম্বা বানায় না, সে স্রেফ তুলনার একটা রেফারেন্স পয়েন্ট মাত্র। একইভাবে \"সবচেয়ে ভালো\" ধারণাটা হয়তো নিছক একটা ধারণাগত মানদণ্ড (conceptual standard), বাস্তব কোনো কার্যকারণ সম্পর্কের উৎস না। এই আপত্তির জবাবে থোমিস্টরা বলেন, \"ভালোত্ব\" আর \"সত্তা\"-র ক্ষেত্রে ব্যাপারটা লম্বা হওয়ার মতো সাধারণ পরিমাপযোগ্য গুণের চেয়ে আলাদা, কারণ এখানে প্রশ্নটা কেবল তুলনা নিয়ে না, বরং কেন কোনো জিনিস আংশিকভাবে ভালো বা পূর্ণ হয়ে থাকতে পারে অথচ সম্পূর্ণ পূর্ণতা অর্জন করতে পারে না, তার ব্যাখ্যা নিয়ে।", "তৃতীয় আপত্তিটা আসে নৈতিক দর্শনের দিক থেকে - আদৌ কি \"সর্বোচ্চ ভালোত্ব\" বলে কিছু আছে? মানুষ তো সহজ সহজ নৈতিক প্রশ্নেই একমত হতে পারে না - তাহলে একটা চূড়ান্ত, বস্তুনিষ্ঠ, সর্বোচ্চ ভালোত্বের ধারণা কতটা বাস্তবসম্মত? হয়তো \"ভালো\" ধারণাটা সংস্কৃতি আর প্রেক্ষাপটভেদে আপেক্ষিক, কোনো একক পরম মানদণ্ডের দিকে নির্দেশ করে না। থোমিস্টরা পাল্টা বলেন, নৈতিক বিষয়ে মতভেদ থাকা মানেই এই না যে কোনো বস্তুনিষ্ঠ সত্য নেই - বিজ্ঞানের অনেক প্রশ্নেও বিজ্ঞানীরা দ্বিমত পোষণ করেন, তাতে বিজ্ঞানের বস্তুনিষ্ঠতা মিথ্যা হয়ে যায় না। তদুপরি, নৈতিক ভালত্যের যদি বস্তুনিষ্ঠ মানদন্ড না-ই থাকে, তাহলে হিটলার বা জেওদের কাজও জাস্টিফাইড দেখানো যায়।", "চতুর্থ আপত্তিটা আগের পর্বগুলোর মতোই \"অনন্যতার সমস্যা\" - এমনকি যদি মেনেও নিই একটা \"সর্বোচ্চ পূর্ণ সত্তা\" থাকতে হবে, তার মানে এই না যে সেই সত্তার বুদ্ধি, ইচ্ছা, ব্যক্তিত্ব আছে, বা এটাই সেই ব্যক্তিগত ঈশ্বর যার কাছে মানুষ প্রার্থনা করে। আকুইনাস নিজে এই ফাঁকটা বুঝতেন বলেই সুম্মা থিওলজিকার পরবর্তী প্রশ্নগুলোতে আলাদাভাবে যুক্তি দেন কেন এই পরম পূর্ণ সত্তার মধ্যে জ্ঞান, ইচ্ছা, আর ব্যক্তিত্বের মতো গুণ থাকতে হবে। সমালোচকরা মনে করেন এই অতিরিক্ত ধাপগুলো মূল পাঁচটা পথের চেয়ে অনেক বেশি অনুমাননির্ভর, আর সেখানেই যুক্তির আসল দুর্বলতা লুকিয়ে থাকতে পারে। কিন্তু, ধর্মগ্রন্থগুলোর মূল কথাকে সামনে নিয়ে আসলে দেখা যায়, এই সকল অনুমান একাধিক উৎস থেকে ভ্যালিডেটেড তথা একটা বিন্দুতেই ইঙ্গিত করে। ফলে সমালোকদের অর্থহীন সন্দেহবাতিকতা যৌক্তিক বোধের সাপেক্ষে ভিত্তিহীন মনে হয়।", "শেষ কথা", "আকুইনাসের এই চতুর্থ পথ আমাদের এমন একটা জায়গায় নিয়ে যায় যেখানে যুক্তি আর নৈতিকতা মিলেমিশে একাকার হয়ে যায় - আমরা প্রতিদিন মানুষকে, কাজকে, চিন্তাকে \"ভালো\" আর \"মন্দ\", \"সত্য\" আর \"মিথ্যা\" বলে বিচার করি, যেন কোথাও একটা নিখুঁত মানদণ্ড আছে যার সাপেক্ষে এই বিচার করা যায়। দর্শনে আলোচনা হয়, এই মানদণ্ডটা কি সত্যিই বাস্তবে কোথাও অস্তিত্বশীল, নাকি এটা স্রেফ আমাদের মনের একটা সুবিধাজনক কল্পনা, যা দিয়ে আমরা জগতকে বোঝার চেষ্টা করি? কিন্তু, যৌক্তিক চিন্তা এবং ধর্মীয় জ্ঞানের সমন্বয় করলে এই মানদন্ডের বাস্তবিক অস্তিত্ব এবং অস্তিত্বের উৎস হিসেবে স্রষ্টার অবস্থান পরিস্কার হয়ে যায়।"], "source": "philosophy"}, {"id": "ai-2026-09-29", "date": "2026-09-29", "title": "AI in Healthcare: Research Roundup — September 29, 2026", "excerpt": "On the LLM side, today's additions lean toward evaluation, safety, and trust rather than new clinical benchmarks. A privacy-budgeted adaptation framework (MedDP) applied…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "PrecisionMedicine", "HealthTech"], "body": ["On the LLM side, today's additions lean toward evaluation, safety, and trust rather than new clinical benchmarks. A privacy-budgeted adaptation framework (MedDP) applied differential privacy only to low-rank adapter parameters on MedQA/MedMCQA tasks, characterizing a clear privacy-utility trade-off with minimal added compute. A bias-auditing study using the Stanford Healthcare red-teaming dataset found that smaller models like o1-mini outperformed GPT-4o at detecting demographic bias, with up to 53% higher precision. CLIN-LLM, a hybrid framework pairing a fine-tuned BioBERT classifier with retrieval-augmented treatment generation, automatically flagged 18% of cases as low-certainty for expert review rather than forcing a prediction. Separately, a stroke-education study comparing GPT-4 and Claude 3 against neurologist-authored materials found LLMs could convey complex content accessibly, though performance varied across accuracy and comprehensiveness domains. Rounding out the day, several reviews (a roadmap for medical LLM clinical translation, a healthcare LLM evaluation-methods primer, and a systematic review of medical reasoning-enhancement techniques) mapped the field's open challenges: hallucination, evaluation validity, and workflow integration.", "On the ML/DL side, prognostic models continued to post strong discrimination across a wide range of diseases. A gradient boosting model for prostate cancer recurrence reached an AUC of 0.891 (0.912 in a simplified 5-feature version), beating the UCSF-CAPRA score (0.703) and D'Amico classification (0.610) in a 320-patient cohort with external validation. A histology-only deep learning model predicted pancreatic cancer recurrence from routine slides across 591 training and 302 validation patients. For prolonged disorders of consciousness, a gradient boosting model using GCS, FOUR, and CRS-R scores hit an AUROC of 0.954 (training) and 0.922 (test) in a 304-patient prospective cohort. A conformal-prediction NAFLD risk tool (LIVERRISK) achieved AUROC 0.912 internally and 0.891 externally with calibrated coverage guarantees, and a renal cell carcinoma brain metastasis survival model showed median overall survival rising from 1.2 to 2.9 years across treatment eras (interferon to immunotherapy), with a C-index of 0.71.", "Taken together, today's LLM research skews toward making models safer and more auditable for deployment, while ML/DL prognostic models keep demonstrating strong, disease-specific discrimination validated against established clinical scores."], "refs": [{"title": "Efficient privacy-budgeted LLM adaptation for sensitive healthcare QA", "url": "https://pubmed.ncbi.nlm.nih.gov/42262952/"}, {"title": "Using LLMs to audit model healthcare biases", "url": "https://pubmed.ncbi.nlm.nih.gov/41758166/"}, {"title": "CLIN-LLM: safety-constrained hybrid framework for diagnosis and treatment", "url": "https://arxiv.org/abs/2510.22609"}, {"title": "Evaluation of LLMs for personalized stroke education materials", "url": "https://pubmed.ncbi.nlm.nih.gov/42167740/"}, {"title": "ML prognostic model for postoperative prostate cancer recurrence", "url": "https://pubmed.ncbi.nlm.nih.gov/42204546/"}, {"title": "Machine learning of routine slides for pancreatic cancer recurrence", "url": "https://pubmed.ncbi.nlm.nih.gov/41507565/"}, {"title": "Prognostic model for prolonged disorders of consciousness", "url": "https://pubmed.ncbi.nlm.nih.gov/41798799/"}, {"title": "Conformal risk prediction for NAFLD using gradient boosting", "url": "https://arxiv.org/abs/2606.09860"}, {"title": "Interpretable ML survival model for renal cell carcinoma brain metastases", "url": "https://pubmed.ncbi.nlm.nih.gov/42531803/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-28", "date": "2026-09-28", "title": "AI in Healthcare: Research Roundup — September 28, 2026", "excerpt": "On the LLM side, today's additions span clinical diagnosis, evaluation, and documentation. A randomized trial in nephrology had 97 clinicians from 9 countries complete…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["On the LLM side, today's additions span clinical diagnosis, evaluation, and documentation. A randomized trial in nephrology had 97 clinicians from 9 countries complete 556 complex, open-ended case evaluations and found LLM-supported workflows improved diagnostic accuracy while AI-induced errors were rare. In clinical neuroanatomy, ChatGPT-4 showed stable diagnostic performance and precise anatomical terminology across 20 novel cases, while Gemini 2.5 was more sensitive to prompt phrasing. ClinicalGPT-R1, a reasoning-enhanced diagnostic LLM trained on 20,000 clinical records, outperformed GPT-4o on Chinese diagnostic tasks and matched GPT-4 in English. A four-way comparison of ChatGPT, Gemini, Grok, and Copilot on multiple sclerosis questions found Gemini scored highest for relevance and transparency, with Copilot trailing. On documentation, a functional evaluation framework (DistillNote) found LLM summaries of clinical notes compressed 20x still retained 97% of the diagnostic signal (AUROC 0.92 vs. 0.94) for heart failure detection, while a qualitative pilot study of LLM-assisted SOAP notes in pediatric rehabilitation found friction came from workflow mismatch and clinician trust, not language quality. A new benchmark (BRIE) testing nine LLMs on EHR information retrieval found frequent omissions of clinically important information, especially when synthesis across multiple documents was required.", "On the ML/DL side, risk and diagnostic models continued to post strong discrimination on disease-specific tasks. An AutoML model for trauma patients with hemorrhagic shock accurately predicted in-hospital mortality using GCS, ISS, lactate, and fibrinogen as top predictors. A lightweight LightGBM model for breast cancer risk, trained on routine lab panels from 13,285 patients, reached an internal AUC of 0.987 (external AUC 0.83) while running in under 6 seconds. A Vision Transformer outperformed CNN architectures for patient-level classification of acute pancreatitis on CT (89.19% accuracy, AUC 0.946), and a hierarchical multiscale fusion network combining CT and clinical variables achieved high precision for preoperative esophageal cancer T-staging across three centers. A systematic review of 26 studies found AI models for MASLD risk stratification consistently reached AUROC 0.72-0.95, outperforming conventional risk scores. Elsewhere, a knowledge-augmented multimodal EHR model combining an LLM with structured data reached AUCs of 0.84 and 0.92 for 30-day readmission and in-hospital mortality, respectively.", "Taken together, today's findings reinforce a consistent pattern: LLMs are increasingly tested in realistic, open-ended clinical scenarios rather than multiple-choice benchmarks, with mixed but generally positive results, while ML/DL risk and diagnostic models continue to deliver strong, disease-specific discrimination that still needs broader external validation."], "refs": [{"title": "Randomized controlled trial of LLM-assisted diagnostic accuracy in nephrology", "url": "https://pubmed.ncbi.nlm.nih.gov/42502668/"}, {"title": "Evaluation of large language models in clinical neuroanatomy", "url": "https://pubmed.ncbi.nlm.nih.gov/41778880/"}, {"title": "ClinicalGPT-R1: reasoning-enhanced generalist disease diagnosis LLM", "url": "https://arxiv.org/abs/2504.09421"}, {"title": "DistillNote: functional evaluation of LLM-generated clinical note summaries", "url": "https://arxiv.org/abs/2506.16777"}, {"title": "A living benchmark (BRIE) for information retrieval from electronic health records", "url": "https://arxiv.org/abs/2609.30205"}, {"title": "AutoML prognostic model for traumatic multiple fractures and hemorrhagic shock", "url": "https://pubmed.ncbi.nlm.nih.gov/42359088/"}, {"title": "Lightweight LightGBM model for breast cancer risk prediction", "url": "https://pubmed.ncbi.nlm.nih.gov/42647514/"}, {"title": "Vision Transformer framework for acute pancreatitis classification on CT", "url": "https://pubmed.ncbi.nlm.nih.gov/42072777/"}, {"title": "AI-based models for risk prediction in MASLD (systematic review)", "url": "https://pubmed.ncbi.nlm.nih.gov/41231418/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-27", "date": "2026-09-27", "title": "AI in Healthcare: Research Roundup — September 27, 2026", "excerpt": "On the LLM side, today's additions center on diagnostic accuracy in specialized domains and on evaluation methodology. In rare disease diagnosis, the picture is mixed: a…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["On the LLM side, today's additions center on diagnostic accuracy in specialized domains and on evaluation methodology. In rare disease diagnosis, the picture is mixed: a benchmark of seven LLMs against the established bioinformatics tool Exomiser on 5,213 case reports found the best model ranked the correct diagnosis first in only 23.6% of cases versus 35.5% for Exomiser, while a separate 2-stage study on orthopedic rare diseases found Claude Sonnet 4.5, ChatGPT-5.0, and Gemini 2.5 Pro each reaching 90% primary-diagnosis accuracy and improving physician accuracy from 40-58% to 68-83% when used as a decision aid. In psychiatry, GPT-4.0 reached 71.7% strict diagnostic accuracy on 9,923 real-world inpatient records (up to 79.5% in older adults), and a separate vignette study put the top model's diagnostic reasoning within the range of psychiatry residents (0.801 top-5 accuracy). DeepSeek posted 82.9% accuracy on standardized diagnostic-reasoning cases. On the methods side, a new evidence-auditing framework showed that diagnostic accuracy alone can mask whether an LLM is using case evidence appropriately, and a 134-study scoping review of \"LLM-as-a-judge\" approaches found moderate-to-strong alignment with human experts, though reliability varies by task and rubric.", "On the ML/DL side, diagnostic imaging models again posted strong discrimination: a meta-analysis comparing radiomics, deep learning, and hybrid AI for pulmonary ground-glass nodules found hybrid models topped out at AUC 0.94, and a new deep learning model for oral squamous cell carcinoma pathology (RRGNet) beat existing mainstream architectures on accuracy and AUC. Risk-prediction work concentrated on readmission and mortality: an XGBoost model for STEMI long-term mortality hit AUC 0.999, a Random Forest model for acute radiation enteritis in cervical cancer patients reached AUC 0.961, and a pooled meta-analysis of 49 stroke-readmission models found a more modest overall AUROC of 0.74. A LightGBM-based online calculator for 30-day readmission in elderly stroke patients and a random-forest model for pediatric psychiatric readmission (AUROC 0.74-0.75 across 30/90/180 days) both moved toward deployable tools, while an XGBoost gastric cancer risk model (AUROC 0.764 internal, 0.708 external) used SHAP to flag H. pylori, age, and smoking as top contributors.", "Taken together, today's LLM findings underscore that diagnostic accuracy varies sharply by domain and still trails specialized tools in rare disease genetics, even as physician-assistance and evaluation methodology continue to mature; ML/DL models, meanwhile, keep producing disease-specific tools with a wide range of external validation rigor."], "refs": [{"title": "Systematic benchmarking of LLMs vs traditional rare-disease decision support tools", "url": "https://pubmed.ncbi.nlm.nih.gov/41735669/"}, {"title": "Diagnostic performance of LLMs for orthopedic-related rare diseases and impact on physician accuracy", "url": "https://pubmed.ncbi.nlm.nih.gov/42497411/"}, {"title": "Large language models for psychiatric diagnosis based on multicenter real-world clinical records", "url": "https://pubmed.ncbi.nlm.nih.gov/41408781/"}, {"title": "Auditing evidence use in medical LLM diagnosis", "url": "https://arxiv.org/abs/2607.20848"}, {"title": "Comparative diagnostic accuracy of radiomics, deep learning, and hybrid AI for pulmonary ground-glass nodules (meta-analysis)", "url": "https://pubmed.ncbi.nlm.nih.gov/42568352/"}, {"title": "Machine learning-based prediction of long-term mortality in STEMI patients", "url": "https://pubmed.ncbi.nlm.nih.gov/41827216/"}, {"title": "Comparative ML algorithms for acute radiation enteritis risk in cervical cancer radiotherapy", "url": "https://pubmed.ncbi.nlm.nih.gov/41658474/"}, {"title": "Machine learning models for predicting readmission after stroke (systematic review and meta-analysis)", "url": "https://pubmed.ncbi.nlm.nih.gov/42134253/"}, {"title": "SHAP-explained machine-learning model for high-risk gastric cancer identification", "url": "https://pubmed.ncbi.nlm.nih.gov/41919267/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-26", "date": "2026-09-26", "title": "AI in Healthcare: Research Roundup — September 26, 2026", "excerpt": "On the LLM side, today's additions lean toward evaluation and benchmarking rather than new clinical deployments. A scoping review in npj Health Systems mapped the…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["On the LLM side, today's additions lean toward evaluation and benchmarking rather than new clinical deployments. A scoping review in npj Health Systems mapped the field's methodological progress across pretraining, fine-tuning, and prompt engineering, while a 36-study systematic review of LLMs in clinical neurology found strong performance on constrained tasks like binary diagnostic classification (AUC 0.75-0.94) and stroke thrombectomy decision support (AUC 0.92), but flagged that most evidence is still early-stage. A comparative study in JMIR AI showed LLMs actually outperforming conventional machine learning when training data is scarce (under 50 patients), and a new contamination-free benchmark, LiveMedBench, found even the best of 38 tested models topped out at 39.2% accuracy on real-world medical cases — with most failures traced to poor contextual application rather than missing knowledge. On the clinical-facing end, ChatGPT-4o showed mixed results: no measurable benefit for medical students during real-patient exams, and only 60% guideline concordance on knee osteoarthritis surgical recommendations.", "On the ML/DL side, nomogram-based diagnostic tools continued to post strong discrimination: an O-RADS-plus-serum-marker nomogram for ovarian mass malignancy reached AUC 0.950, a LASSO-based nomogram for sepsis risk in acute abdomen hit AUC 0.929/0.934 (train/validation), and a radiomics-clinical nomogram for soft tissue tumors reached AUC 0.97/0.93. Deep learning imaging models also performed well: a CNN using high-frequency ultrasound classified skin lesions with AUC 0.98, and a lightweight segmentation-classification network for hepatic echinococcosis held up on external validation (90.1%/81.0% accuracy, internal vs external). Prognostic models rounded out the batch, including a random-forest model for 12-month cognitive decline in Alzheimer's disease (AUC 0.773, beating a logistic-regression baseline at 0.755) and a LASSO-logistic nomogram for 90-day functional outcomes after stroke thrombectomy (AUC 0.889/0.878).", "Taken together, today's LLM research is largely about calibrating expectations — measuring where these models genuinely help versus where evaluation gaps remain — while ML/DL work keeps delivering disease-specific tools with concrete, externally validated discrimination metrics."], "refs": [{"title": "Generative large language models in medicine: a scoping review", "url": "https://pubmed.ncbi.nlm.nih.gov/42686940/"}, {"title": "Large Language Models in Clinical Neurology: A Systematic Review", "url": "https://pubmed.ncbi.nlm.nih.gov/41756436/"}, {"title": "LLMs vs conventional ML for predicting clinical outcomes with limited data", "url": "https://pubmed.ncbi.nlm.nih.gov/41921208/"}, {"title": "LiveMedBench: a contamination-free medical benchmark for LLMs", "url": "https://arxiv.org/abs/2602.10367"}, {"title": "AI at the bedside: RCT of ChatGPT's impact on student performance in real-patient exams", "url": "https://pubmed.ncbi.nlm.nih.gov/42010936/"}, {"title": "Diagnostic nomogram for ovarian mass malignancy (O-RADS + serum indexes)", "url": "https://pubmed.ncbi.nlm.nih.gov/42024575/"}, {"title": "Deep learning CNN for skin lesion classification on high-frequency ultrasound", "url": "https://pubmed.ncbi.nlm.nih.gov/41267329/"}, {"title": "Machine-learning risk stratification for 12-month cognitive decline in Alzheimer's disease", "url": "https://pubmed.ncbi.nlm.nih.gov/41820490/"}, {"title": "Nomogram for 90-day functional outcomes after endovascular stroke therapy", "url": "https://pubmed.ncbi.nlm.nih.gov/41792065/"}], "lang": "en", "source": "ai"}, {"id": "ph-2026-09-18-argument-from-time-and-contingency", "date": "2026-09-25", "title": "সময় ও সম্ভাব্যতার যুক্তি: অ্যাকুইনাসের তৃতীয় পথ", "title_en": "The Argument from Time and Contingency (Aquinas's Five Ways)", "excerpt": "সময় ও সম্ভাব্যতার যুক্তি: যদি একসময় সত্যিই কিছুই না থাকত, তাহলে এখন কিছু আছে কীভাবে?", "theme": "faith", "cats": ["স্রষ্টার অস্তিত্বের যুক্তি", "দর্শন"], "body": ["সময় ও সম্ভাব্যতার যুক্তি: যদি একসময় সত্যিই কিছুই না থাকত, তাহলে এখন কিছু আছে কীভাবে?", "আপনার ঘরে তাকিয়ে দেখুন একবার - টেবিলের ওপর রাখা একটা মোমবাতি, জানালার পাশে একটা টবের গাছ, আর আয়নায় নিজের প্রতিবিম্ব। এই তিনটা জিনিসের একটা মিল আছে যা হয়তো আমরা কখনো খেয়াল করি না - এগুলোর কোনোটাই চিরকাল ছিল না, আর কোনোটাই চিরকাল থাকবে না। মোমবাতিটা একদিন জ্বলে শেষ হয়ে যাবে, গাছটা একদিন শুকিয়ে মরে যাবে, আর আমরা নিজেরাও একদিন থাকব না। এমনকি এই মুহূর্তে যেটা পুরোপুরি বাস্তব, সজীব, স্পষ্ট মনে হচ্ছে, সেটাও এমন একটা জিনিস যেটা \"নাও থাকতে পারত\"। এখন একটু অদ্ভুত একটা প্রশ্ন করি নিজেকে - যদি প্রতিটা জিনিসই এমন হয় যে সেটা থাকতেও পারে, নাও থাকতে পারে, তাহলে কি এমন কোনো সময় আসা সম্ভব ছিল না যখন আক্ষরিক অর্থেই কিছুই ছিল না - কোনো মোমবাতি না, কোনো গাছ না, কোনো মানুষ না, কিছুই না? আর যদি সত্যিই এমন একটা সময় থেকে থাকে যখন কিছুই ছিল না, তাহলে এখন এত কিছু আছে কী করে? শূন্য থেকে তো নিজে থেকে কিছু আসতে পারে না। এই প্রশ্নটাই থমাস আকুইনাসের বিখ্যাত \"পাঁচটি পথ\"-এর তৃতীয় পথের মূল কথা - যাকে বলা হয় \"সম্ভাব্যতা ও প্রয়োজনীয়তার যুক্তি\" (Argument from Possibility and Necessity), বা আরেকটু সহজ নামে \"সময় ও সম্ভাব্যতার যুক্তি\" (Argument from Time and Contingency)। আগের দুটি পোস্টে আমরা দেখেছিলাম পরিবর্তনের যুক্তি আর নিমিত্ত কারণের যুক্তি, আজ দেখব এই দুটোর চেয়ে অনেকটাই আলাদা, আর হয়তো সবচেয়ে গভীর প্রশ্ন তোলা একটা যুক্তি।", "যুক্তিটা কোথা থেকে এলো", "আকুইনাস তার \"সুম্মা থিওলজিকা\" গ্রন্থের প্রথম ভাগে (প্রশ্ন ২, অনুচ্ছেদ ৩) এই তৃতীয় পথটা হাজির করেন প্রকৃতির একটা সাধারণ পর্যবেক্ষণ দিয়ে - আমাদের চারপাশে এমন জিনিস দেখা যায় যেগুলো \"জন্মায় আর ধ্বংস হয়\" (generation and corruption) - গাছপালা, প্রাণী, আগুন, বরফ। এই জিনিসগুলোর একটা বিশেষ বৈশিষ্ট্য আছে - এগুলো \"থাকতেও পারে, না থাকতেও পারে\" (possibile esse et non esse), অর্থাৎ এদের অস্তিত্ব আবশ্যিক না, নিছক সম্ভাব্য। এই ধরনের অস্তিত্বকে দর্শনের ভাষায় বলে \"সম্ভাব্য\" বা \"কনটিনজেন্ট\" (contingent) অস্তিত্ব। এর বিপরীতে আছে \"আবশ্যিক\" বা \"নেসেসারি\" (necessary) অস্তিত্ব, যা থাকতে বাধ্য, যার না-থাকা অসম্ভব। আকুইনাসের প্রশ্ন হলো - যদি সবকিছুই স্রেফ সম্ভাব্য হয়, তাহলে গোটা বাস্তবতার পেছনে কি এমন কিছু থাকার দরকার নেই যেটা আবশ্যিকভাবেই আছে?", "মূল ধারণা সহজ ভাষায়", "চিন্তা করুন একটা জ্বলন্ত মোমবাতির কথা। মোমবাতিটা এখন জ্বলছে - কিন্তু এটা এমন না যে এটা জ্বলতেই হতো, বাধ্যতামূলকভাবে। এটা না জ্বললেও পারত, এমনকি না বানানো হলেও পারত। এক সময় এই মোমবাতিটা ছিল না (তৈরির আগে), আর একদিন এটা থাকবে না (পুড়ে শেষ হয়ে গেলে বা গলে গেলে)। এই যে \"না-থাকা\"টা মোমবাতির জন্য সম্ভব - এটাই একে \"সম্ভাব্য অস্তিত্ব\" বানায়। আকুইনাসের যুক্তিতে একটা সহজ নীতি কাজ করে - যে জিনিস না-থাকতে পারে, সেটা আসলে কোনো না কোনো সময়ে ছিলও না। মানুষের বেলাতেও একই কথা - আমরা প্রত্যেকেই জন্মের আগে ছিলাম না, আর মৃত্যুর পর থাকব না। এখন প্রশ্ন হলো, যদি মহাবিশ্বের সবকিছুই - প্রতিটা মানুষ, প্রতিটা গ্রহ, প্রতিটা পরমাণু - এভাবে নিছক সম্ভাব্য হয়, তাহলে অসীম সময় ধরে চিন্তা করলে কী দাঁড়ায়? যদি প্রতিটা জিনিসেরই না-থাকার সম্ভাবনা থাকে, আর সময় অসীম হয়, তাহলে যুক্তিসংগতভাবে এমন একটা মুহূর্ত থাকা উচিত ছিল যখন সেই সম্ভাবনাটা বাস্তবায়িত হয়েছে - অর্থাৎ যখন কিছুই ছিল না। আর একবার যদি সত্যিই এমন একটা \"শূন্য মুহূর্ত\" ঘটে যায়, তাহলে তার পর থেকে আর কখনো কিছু থাকার কথা না - কারণ যা নেই, তা নিজে থেকে অস্তিত্বে আসতে পারে না, তাকে অস্তিত্বে আনার জন্য আগে থেকে অস্তিত্বশীল কিছু লাগে। কিন্তু বাস্তবে তো এখন অনেক কিছুই আছে। তাহলে শুরুর অনুমানটাই ভুল - সবকিছু নিছক সম্ভাব্য হতে পারে না। কোথাও একটা এমন সত্তা থাকতেই হবে যা আবশ্যিকভাবে আছে, যার অস্তিত্ব কখনো ছিল না এমনটা হতেই পারে না।", "যুক্তির কাঠামো", "পুরো যুক্তিটা ধাপে ধাপে এভাবে সাজানো যায়:", "১) প্রকৃতিতে আমরা এমন জিনিস দেখি যেগুলো সম্ভাব্য - অর্থাৎ যেগুলো থাকতেও পারে, না থাকতেও পারে (এরা জন্মায় আর ধ্বংস হয়)।", "২) যে জিনিস না-থাকতে পারে, সেটা কোনো না কোনো সময়ে ছিলও না - এটা একটা যৌক্তিক অনিবার্যতা।", "৩) যদি প্রতিটা জিনিসই এরকম সম্ভাব্য হয়, তাহলে (অসীম সময়ের পরিপ্রেক্ষিতে) এমন একটা সময় থাকা উচিত ছিল যখন কিছুই ছিল না।", "৪) কিন্তু যা নেই, তা নিজে থেকে অস্তিত্বে আসতে পারে না - অস্তিত্বে আসার জন্য আগে থেকেই অস্তিত্বশীল কোনো কিছুর প্রয়োজন হয় (এটাকে ল্যাটিনে বলে \"এক্স নিহিলো নিহিল ফিট\" - শূন্য থেকে কিছু আসে না)।", "৫) সুতরাং যদি একসময় সত্যিই কিছুই না থাকত, তাহলে এখনো কিছুই থাকত না - যা মিথ্যা, কারণ এখন স্পষ্টতই অনেক কিছু আছে।", "৬) অতএব সবকিছু নিছক সম্ভাব্য, এই অনুমানটা মিথ্যা - এমন কিছু থাকতেই হবে যা আবশ্যিকভাবে আছে, যেটা অন্য কারো ওপর নির্ভর না করে নিজের ভেতরেই তার অস্তিত্বের ভিত্তি ধারণ করে।", "৭) এই আবশ্যিক সত্তাটাকেই আকুইনাস বলেন ঈশ্বর।", "একটা জরুরি পার্থক্য: কেন এই যুক্তি \"সময়\"-নির্ভর", "আগের দুই পর্বে যে যুক্তিগুলো দেখেছি, সেগুলোর সাথে এই তৃতীয় পথের একটা সূক্ষ্ম কিন্তু গুরুত্বপূর্ণ পার্থক্য আছে। দ্বিতীয় পথ (নিমিত্ত কারণের যুক্তি) কথা বলে এই মুহূর্তে চলমান একটা নির্ভরতার সম্পর্ক নিয়ে - অতীতে কী ঘটেছিল সেটা নিয়ে না। কিন্তু তৃতীয় পথটা স্পষ্টভাবেই সময়ের ওপর নির্ভর করে - এখানে যুক্তিটা বলছে, যদি অসীম সময় ধরে প্রতিটা জিনিসের না-থাকার সম্ভাবনা থাকে, তাহলে অতীতের কোনো এক মুহূর্তে সব সম্ভাবনাই বাস্তবায়িত হয়ে যাওয়ার কথা, অর্থাৎ একটা \"শূন্য মুহূর্ত\" থাকারই কথা। এই কারণেই এই যুক্তিটাকে \"সময় ও সম্ভাব্যতার যুক্তি\" নাম দেওয়া হয় - এখানে সময় (এবং সেই সময়ের সাথে সম্ভাবনার বাস্তবায়ন) যুক্তির কাঠামোর একটা অপরিহার্য অংশ। পরবর্তীকালের দার্শনিকরা - যেমন গটফ্রিড লাইবনিজ (Gottfried Leibniz) - এই একই মূল ধারণাটা নিয়ে একটা আলাদা সংস্করণ বানান, যেখানে সময়ের ওপর নির্ভরতা বাদ দিয়ে শুধু যুক্তির (মোডাল লজিকের) মাধ্যমে বলা হয় - মহাবিশ্ব চিরকাল ধরে থেকে থাকলেও তার অস্তিত্বের একটা পর্যাপ্ত কারণ লাগবে, কারণ চিরস্থায়ী হওয়া মানেই আবশ্যিক হওয়া না। আকুইনাসের মূল সংস্করণ আর লাইবনিজের পরবর্তী সংস্করণ - দুটোই \"সম্ভাব্যতা থেকে আবশ্যিকতার দিকে\" যাওয়ার একই মৌলিক পথ ধরে, কিন্তু আকুইনাসেরটা সময়নির্ভর, লাইবনিজেরটা যুক্তিনির্ভর।", "সবচেয়ে শক্তিশালী সমর্থন কী", "এই যুক্তির আবেদনটা এখানেই যে এটা এমন একটা প্রশ্ন তোলে যা এড়িয়ে যাওয়া কঠিন - \"কেন আদৌ কিছু আছে, কিছুই না থাকার বদলে?\" (why is there something rather than nothing) - দর্শনের ইতিহাসে এটাকে অনেকেই সবচেয়ে গভীর প্রশ্ন বলে মনে করেন। আমরা নিজেরাও জানি, আমাদের অস্তিত্ব আবশ্যিক না - আমরা না থাকলেও পারতাম, আমাদের বাবা-মা যদি কখনো দেখা না করতেন, আমরা জন্মাতামই না। এই সাধারণ উপলব্ধিটাকেই আকুইনাস যুক্তিসংগতভাবে পুরো মহাবিশ্বের ক্ষেত্রে প্রয়োগ করেন - যদি প্রতিটা অংশই সম্ভাব্য হয়, পুরো সংগ্রহটাও কি সম্ভাব্য না? আর যদি তাই হয়, তাহলে কোথাও একটা এমন ভিত্তি না থাকলে পুরো ব্যবস্থাটাই \"ঝুলে\" থাকে, কোনো প্রকৃত ব্যাখ্যা ছাড়া।", "এবার আসি সমালোচনার দিকে", "প্রথম আর সবচেয়ে প্রভাবশালী আপত্তিটা আসে ব্রিটিশ দার্শনিক অ্যান্টনি কেনির (Anthony Kenny) কাছ থেকে, যিনি নিজে একসময় ক্যাথলিক পুরোহিত ছিলেন এবং আকুইনাসের একজন গুরুত্বপূর্ণ পণ্ডিত। কেনি বলেন, আকুইনাসের তৃতীয় পথের তৃতীয় ধাপে (প্রতিটা জিনিস কোনো না কোনো সময়ে ছিল না থেকে, এমন একটা সময় ছিল যখন কিছুই ছিল না - এই লাফে) একটা যৌক্তিক ভুল আছে, যাকে বলে \"কোয়ান্টিফায়ার শিফট ফ্যালাসি\" (quantifier shift fallacy)। এটা বোঝার জন্য একটা সহজ উদাহরণ নিন - এটা সত্যি যে \"প্রতিটা মানুষেরই একজন মা আছে\", কিন্তু এখান থেকে এটা বলা ভুল হবে যে \"এমন একজন মহিলা আছেন যিনি প্রত্যেক মানুষেরই মা\"। প্রতি আর কোনো-একটা - এই দুটো ভিন্ন জিনিস, আর একটা থেকে আরেকটায় লাফ দিলে যুক্তিতে গলদ থেকে যায়। একইভাবে, \"প্রতিটা জিনিসই কোনো না কোনো সময়ে ছিল না\" - এটা সত্যি হতে পারে, অথচ এখান থেকে এটা বলা ভুল হবে যে \"এমন একটা নির্দিষ্ট সময় আছে যখন সব জিনিসই একসাথে ছিল না\"। হতে পারে প্রতিটা জিনিসই আলাদা আলাদা সময়ে ছিল না, কিন্তু সবসময়ই অন্তত একটা কিছু না কিছু ছিল - ঠিক যেমন একটা ক্লাসের প্রতিটা ছাত্রই আলাদা আলাদা দিনে জন্মেছে, কিন্তু তার মানে এই না যে এমন একটা দিন ছিল যেদিন ক্লাসের কোনো ছাত্রই এখনো জন্মায়নি। আকুইনাসের রক্ষাকারীরা - যেমন আধুনিক থোমিস্ট দার্শনিক এডওয়ার্ড ফেজার (Edward Feser) - এই অভিযোগ প্রত্যাখ্যান করেন। তাদের যুক্তি হলো, আকুইনাস আসলে সরল ঐতিহাসিক সময়ের কথা বলছেন না, বরং দ্বিতীয় পথের মতোই একটা \"এই মুহূর্তে নির্ভরতার\" কাঠামোর কথা বলছেন - প্রশ্নটা কোনো এক অতীত মুহূর্তে সবকিছু একসাথে না-থাকা নিয়ে না, বরং এই প্রশ্ন নিয়ে যে সম্ভাব্য জিনিসের একটা সংগ্রহ, নিজে থেকেই, নিজের অস্তিত্বের ব্যাখ্যা দিতে পারে কি না। এই ব্যাখ্যা কেনির আপত্তিকে পুরোপুরি নিষ্ক্রিয় করে কি না, তা নিয়ে দার্শনিকদের মধ্যে এখনো বিতর্ক চলছে।", "দ্বিতীয় আপত্তিটা হলো - মহাবিশ্ব নিজেই কি আবশ্যিক সত্তা হতে পারে না? যদি মহাবিশ্ব বা পদার্থ চিরকাল ধরে থেকে থাকে (শুরু বা শেষ ছাড়া), তাহলে আলাদা করে কোনো ঈশ্বরের দরকার কী? এর জবাবে দার্শনিক আলেকজান্ডার প্রুস (Alexander Pruss)-এর মতো থোমিস্ট চিন্তাবিদরা বলেন, চিরস্থায়ী হওয়া আর আবশ্যিক হওয়া এক জিনিস না - মহাবিশ্ব যদি অসংখ্য সম্ভাব্য অংশ (পরমাণু, কণা) দিয়ে গঠিত হয়, তাহলে পুরো সংগ্রহটাও সম্ভাব্যই থেকে যায়, শুধু অংশগুলো যোগ করলেই সেটা আবশ্যিক হয়ে যায় না। একগুচ্ছ সম্ভাব্য জিনিস মিলে কখনো নিজে থেকে আবশ্যিকতা তৈরি করতে পারে না - এটা অনেকটা এমন, যেন অনেকগুলো ঋণ যোগ করলে হঠাৎ সম্পদ তৈরি হয়ে যায়, যা যুক্তিসংগতভাবে অসম্ভব।", "তৃতীয় আপত্তিটা আসে সেই পুরনো \"মৌলিক সত্য\" (brute fact) তর্ক থেকে, যা বার্ট্রান্ড রাসেল আর ডেভিড হিউম উভয়েই আলাদাভাবে তুলেছিলেন - কেন ধরে নিতে হবে যে মহাবিশ্বের অস্তিত্বের একটা \"ব্যাখ্যা\" থাকতেই হবে? হয়তো মহাবিশ্ব, বা তার ভেতরের কোনো মৌলিক অবস্থা, এমনিই আছে, কোনো আরও গভীর কারণ ছাড়াই। এই আপত্তি আসলে \"পর্যাপ্ত কারণের নীতি\" (Principle of Sufficient Reason)-টাকেই প্রশ্নবিদ্ধ করে, যার ওপর পুরো যুক্তিটা দাঁড়িয়ে আছে। আকুইনাসের সমর্থকরা বলেন, এই নীতি ছাড়া বিজ্ঞান নিজেও দাঁড়াতে পারে না - প্রতিটা ঘটনার একটা কারণ খোঁজাই তো বৈজ্ঞানিক পদ্ধতির ভিত্তি; তাই মহাবিশ্বের ক্ষেত্রে হঠাৎ এই নীতি ছেড়ে দেওয়াটা যুক্তিসংগত মনে হয় না।", "চতুর্থ আপত্তিটা আগের পর্বগুলোর মতোই \"অনন্যতার সমস্যা\" - এমনকি যদি মেনেও নিই একটা আবশ্যিক সত্তা থাকতে হবে, যুক্তিটা নিজে থেকে প্রমাণ করে না যে এই সত্তা একটাই, বা তার বুদ্ধি-ইচ্ছা-ব্যক্তিত্ব আছে, বা এটাই সেই ঈশ্বর যাকে বিভিন্ন ধর্মে পূজা করা হয়। আকুইনাস নিজেও এই ফাঁক বুঝতেন - সুম্মা থিওলজিকার পরের প্রশ্নগুলোতে তিনি আলাদাভাবে যুক্তি দেন কেন এই আবশ্যিক সত্তা একটাই হতে হবে এবং কেন তার মধ্যে জ্ঞান-ইচ্ছার মতো গুণ থাকতে হবে। সমালোচকরা মনে করেন এই বাড়তি ধাপগুলো মূল পাঁচটা পথের চেয়ে অনেক বেশি অনুমাননির্ভর।", "শেষ কথা", "আকুইনাসের এই তৃতীয় পথ আমাদের এমন একটা জায়গায় দাঁড় করায় যেখানে যুক্তি আর বিস্ময় একসাথে মিশে যায় - আমাদের চারপাশের প্রতিটা জিনিসই, এমনকি আমরা নিজেরাও, এমন যে থাকতেও পারতাম না, না থাকাটাও সমান সম্ভব ছিল। তাহলে এত কিছুর অস্তিত্ব কি নিছক একটা দুর্ঘটনা, নাকি এর পেছনে সত্যিই এমন কিছু থাকা দরকার যা কখনো না-থাকতে পারে না? এই প্রশ্নটা দর্শনের সবচেয়ে পুরনো প্রশ্নগুলোর একটা, অথচ এখনো এর উত্তর নিয়ে যুক্তিবিদ, পদার্থবিজ্ঞানী আর ধর্মতাত্ত্বিকদের মধ্যে বিতর্ক থামেনি।", "ভাল ভাবে লক্ষ্য করলে দেখবেন কোরআন বুঝে অধ্যয়নকালী একজন চিন্তাশীল মুসলিমের ভাবনার সাথে এই দার্শনিক যুক্তিগুলো দারুণভাবে মিলে যায়। কোরআনের মধ্যে দার্শনিকদের কাছে  আপাত অমিমাংসিত কিছু প্রশ্নের উত্তর খুব পরিস্কার ভাবে পাওয়া যায়। যেমন, দার্শনিক ভাবনার মাধ্যমে প্রাপ্ত আবশ্যকীয় সত্ত্বার বৈশিষ্ট্যগুলো সুরা ইখলাসে বর্ণিত স্রষ্টার গুনাবলীরই যেন প্রতিফলন। এর থেকে বোঝা যায়, যে এককভাবে দর্শনের ওপর নির্ভরশীল না হয়ে, ধর্মীয় গ্রন্থ, ইতিহাস, অভিজ্ঞতা এবং বিজ্ঞানের সমন্বয় করলে স্রষ্টার অস্থিত্ব সম্পর্কে কনভিকশন পূর্ণতা পায়।"], "source": "philosophy"}, {"id": "ai-2026-09-25", "date": "2026-09-25", "title": "AI in Healthcare: Research Roundup — September 25, 2026", "excerpt": "On the LLM side, several new studies benchmarked how far chatbots can be pushed on clinical reasoning and communication tasks. A randomized trial of ChatGPT-4o as…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["On the LLM side, several new studies benchmarked how far chatbots can be pushed on clinical reasoning and communication tasks. A randomized trial of ChatGPT-4o as decision support for junior otolaryngology residents found it scored significantly higher than a board-certified specialist on a structured performance instrument (mean 14.20 vs 12.34, p=0.001), while a separate evaluation of ChatGPT-4o on 24 foot and ankle vignettes matched fellowship-trained surgeons' top diagnosis in 9 of 12 cases (75%). New benchmarking work is also probing the limits of longitudinal reasoning: ClinTraceBench, built from 385 verified MIMIC-IV dialogues across nine tasks, found that compressed or memory-based patient-history representations lose meaningful signal compared to full clinical context, and a separate multi-turn diagnostic dataset (MTDiag) documented clear accuracy degradation when models reason interactively rather than answer static questions.", "On the ML/DL prognostic and diagnostic side, imaging models continued to post strong discrimination: a deep transfer learning signature for thyroid adenomatoid nodules reached AUC 0.959 on ultrasound, and an integrated clinical-radiomics-deep learning model for pulmonary ground-glass nodules reached AUC 0.871. Tree-based models were validated across several risk-prediction tasks — XGBoost reached AUC 0.903 for diabetic peripheral neuropathy, 0.915/0.912 (train/test) for arteriovenous fistula dysfunction in dialysis patients, and 0.85 for early recurrence after hilar cholangiocarcinoma resection, outperforming logistic regression in a head-to-head comparison for post-stroke cognitive impairment (0.806 vs 0.735). Nomogram-based tools also continued to accumulate: new models for ischemic stroke risk in atrial fibrillation (AUC 0.852/0.847) and ICU delirium (AUC 0.736 development, 0.810 external validation, beating the established PRE-DELIRIC score) add to the growing library of bedside-deployable risk calculators.", "Taken together, today's LLM studies are testing where language models hold up under more demanding, interactive clinical conditions, while ML/DL work keeps producing narrowly validated, disease-specific models with concrete discrimination metrics ready for further external testing."], "refs": [{"title": "ChatGPT-4o as clinical decision support for junior otolaryngology residents (RCT)", "url": "https://pubmed.ncbi.nlm.nih.gov/41862715/"}, {"title": "ChatGPT's triage and diagnostic capabilities for foot and ankle pain", "url": "https://pubmed.ncbi.nlm.nih.gov/41883881/"}, {"title": "ClinTraceBench: source-verifiable longitudinal clinical reasoning over EHR dialogues", "url": "https://arxiv.org/abs/2609.01111"}, {"title": "MTDiag: multi-turn diagnostic dataset for clinically meaningful LLM evaluation", "url": "https://arxiv.org/abs/2608.25085"}, {"title": "Deep learning for differentiating thyroid adenomatoid nodules on ultrasound", "url": "https://pubmed.ncbi.nlm.nih.gov/42493350/"}, {"title": "CT-based deep learning model for pulmonary ground-glass nodule subtyping", "url": "https://pubmed.ncbi.nlm.nih.gov/42272663/"}, {"title": "XGBoost model for arteriovenous fistula dysfunction in end-stage renal disease", "url": "https://pubmed.ncbi.nlm.nih.gov/42676377/"}, {"title": "Multicenter ML model for early recurrence after hilar cholangiocarcinoma resection", "url": "https://pubmed.ncbi.nlm.nih.gov/42219861/"}, {"title": "Nomogram for acute ischemic stroke risk in non-valvular atrial fibrillation", "url": "https://pubmed.ncbi.nlm.nih.gov/41938697/"}, {"title": "Nomogram for ICU delirium prediction, outperforming PRE-DELIRIC", "url": "https://pubmed.ncbi.nlm.nih.gov/41780761/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-24", "date": "2026-09-24", "title": "AI in Healthcare: Research Roundup — September 24, 2026", "excerpt": "On the LLM side, several new studies examined triage performance across specialties. A pilot study pitting four LLM chatbots against retina specialists on after-hours…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["On the LLM side, several new studies examined triage performance across specialties. A pilot study pitting four LLM chatbots against retina specialists on after-hours emergency calls found humans still more accurate overall (95% vs 76.7% diagnosis), though ChatGPT (90%) and Claude (83.3%) were statistically noninferior to human graders. A separate benchmarking study across five rare-disease datasets found LLM specialty-triage accuracy ranging widely from 0.44 to 0.71, while an evaluation of eight contemporary models on 48 clinical vignettes showed structured prompting lifting mean diagnostic accuracy from 89.84% to 91.67% and triage accuracy from 76.82% to 86.20%.", "On broader evidence quality, a meta-research analysis of 11,628 PubMed records from 2023-2026 found medical LLM publications growing 45-fold, yet only 2.5% used randomized, controlled, or prospective designs, and the gap between a study's newest cited model and its own publication date widened from 1.33 to 6.08 quarters. A national survey of nearly 36,000 adults in China found moderate public acceptance of LLM-based healthcare (64.3/100), skewing lower among older adults and those with less digital-health experience. In a real-world multimodal evaluation across 539 inpatient cases, ten frontier LLMs all outperformed routine ward diagnoses on accuracy and safety scores.", "On the ML/DL prognostic and diagnostic side, several nomogram studies validated risk-prediction tools: an invasive pulmonary aspergillosis model in ICU sepsis patients reached AUC 0.883/0.844 (training/validation), and a postherpetic neuralgia risk nomogram in herpes zoster patients reached AUC 0.758 with external validation. In imaging, a histology-based deep learning model for pituitary neuroendocrine tumors achieved AUC 0.912 for lineage classification across three independent cohorts, and a sequential-learning framework preserved diagnostic accuracy while adding prognostic capability for osteoarthritis, Alzheimer's disease, and breast cancer.", "Across both threads, today's studies reinforce a consistent theme: LLMs are being pushed hardest on triage and diagnostic-reasoning tasks with mixed but improving results, while ML/DL prognostic and diagnostic models keep delivering well-validated, disease-specific risk scores ready for clinical use."], "refs": [{"title": "LLM triage of retina emergency telephone calls (pilot study)", "url": "https://pubmed.ncbi.nlm.nih.gov/41602600/"}, {"title": "Initial-visit specialty triage in rare diseases using LLMs", "url": "https://pubmed.ncbi.nlm.nih.gov/42490550/"}, {"title": "Diagnosis and triage performance of contemporary LLMs on clinical vignettes", "url": "https://pubmed.ncbi.nlm.nih.gov/41108346/"}, {"title": "The widening evaluation gap in medical LLM research, 2023-2026", "url": "https://arxiv.org/abs/2609.11770"}, {"title": "Public acceptance of LLMs in healthcare in China (national survey)", "url": "https://pubmed.ncbi.nlm.nih.gov/42531173/"}, {"title": "Evaluating multimodal LLMs for inpatient diagnosis across ten frontier models", "url": "https://arxiv.org/abs/2604.16980"}, {"title": "Nomogram for invasive pulmonary aspergillosis risk in ICU sepsis patients", "url": "https://pubmed.ncbi.nlm.nih.gov/42222036/"}, {"title": "Nomogram for postherpetic neuralgia risk in herpes zoster patients", "url": "https://pubmed.ncbi.nlm.nih.gov/42502490/"}, {"title": "Deep learning for pituitary neuroendocrine tumor lineage and subtypes", "url": "https://pubmed.ncbi.nlm.nih.gov/42031964/"}, {"title": "Sequential learning for robust disease prognosis via diagnostic knowledge preservation", "url": "https://pubmed.ncbi.nlm.nih.gov/42090385/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-23", "date": "2026-09-23", "title": "AI in Healthcare: Research Roundup — September 23, 2026", "excerpt": "On the LLM side, several studies this week focused on diagnostic reasoning. GPT-4 evaluated against cardiologists at a Sub-Saharan Africa hospital identified the correct…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["On the LLM side, several studies this week focused on diagnostic reasoning. GPT-4 evaluated against cardiologists at a Sub-Saharan Africa hospital identified the correct diagnosis with certainty in 64% of 50 cases, rising to 82% when counted among the top three hypotheses. A separate study tracking six successive GPT models on sleep medicine cases found diagnostic accuracy climbing from 74.4% (GPT-3.5 Turbo) to 93.6% (GPT-o3), with board-exam knowledge scores rising from 56.9% to 93.0% for GPT-5, though gains appear to be plateauing.", "On safety and deployment, a risk-stratified evaluation of Claude Sonnet 4.0 across 200 consultation scenarios reported 78.3% diagnostic accuracy and 88.7% clinical safety, with acute-care scenarios flagged as needing more oversight than routine care. Applied tools also moved forward: a LangChain/GPT-3.5 chatbot cut pediatric EHR search time by 40.6% and raised retrieval accuracy (F1) from 0.71 to 0.89, while CLIN-LLM, a BioBERT-based diagnosis-and-treatment framework, reached 98% classification accuracy and cut unsafe antibiotic suggestions by 67% versus GPT-5.", "On the ML/DL prognostic and diagnostic side, a meta-analysis of 69 studies confirmed XGBoost-family gradient boosting as the most consistent performer for post-MI mortality prediction, and a similar XGBoost model reached AUC 0.954 for ICU sepsis mortality. An explainable LightGBM model for COVID-19 mortality in older adults identified SaO2 (85%) and CRP (100 mg/L) as clinically meaningful risk thresholds. In imaging, deep learning models reached AUC 0.986 for proptosis detection on orbital MRI and improved differentiation of liver cancer subtypes on contrast-enhanced ultrasound.", "Across both threads, today's studies point toward the same pattern: LLM performance keeps improving on diagnostic and reasoning tasks, while ML/DL prognostic models continue to deliver strong, well-validated accuracy on narrower, single-disease prediction problems."], "refs": [{"title": "GPT-4 diagnostic accuracy in cardiology (Sub-Saharan Africa)", "url": "https://pubmed.ncbi.nlm.nih.gov/41773215/"}, {"title": "Successive GPT models on sleep medicine cases and board questions", "url": "https://pubmed.ncbi.nlm.nih.gov/41495183/"}, {"title": "Risk-stratified safety assessment of Claude Sonnet 4.0 in medical consultations", "url": "https://pubmed.ncbi.nlm.nih.gov/41442171/"}, {"title": "LangChain/GPT-3.5 chatbot for pediatric EHR accessibility", "url": "https://pubmed.ncbi.nlm.nih.gov/41820430/"}, {"title": "CLIN-LLM safety-constrained diagnosis and treatment framework", "url": "https://pubmed.ncbi.nlm.nih.gov/42658861/"}, {"title": "XGBoost meta-analysis for post-MI mortality prediction", "url": "https://pubmed.ncbi.nlm.nih.gov/41664678/"}, {"title": "XGBoost model for ICU sepsis mortality (AUC 0.954)", "url": "https://pubmed.ncbi.nlm.nih.gov/42605370/"}, {"title": "Explainable LightGBM model for COVID-19 mortality in older adults", "url": "https://pubmed.ncbi.nlm.nih.gov/42266687/"}], "lang": "en", "source": "ai"}, {"id": "ph-2026-09-15-argument-from-efficient-causality", "date": "2026-09-22", "title": "নিমিত্ত কারণের যুক্তি: অ্যাকুইনাসের দ্বিতীয় পথ", "title_en": "The Argument from Efficient Causality (Aquinas's Five Ways)", "excerpt": "নিমিত্ত কারণের যুক্তি: এক্সটেনশন কর্ড থেকে আকুইনাসের দ্বিতীয় পথ পর্যন্ত", "theme": "faith", "cats": ["স্রষ্টার অস্তিত্বের যুক্তি", "দর্শন"], "body": ["নিমিত্ত কারণের যুক্তি: এক্সটেনশন কর্ড থেকে আকুইনাসের দ্বিতীয় পথ পর্যন্ত", "বাসায় কখনো একটার পর একটা এক্সটেনশন কর্ড (মাল্টিপ্লাগ) জোড়া লাগিয়ে দূরের একটা বাতি জ্বালানোর চেষ্টা করেছেন? প্রথম কর্ডটা দেয়ালের সকেটে, তার সাথে দ্বিতীয়টা, তার সাথে তৃতীয়টা - এভাবে পাঁচ-সাতটা কর্ড জোড়া দিয়ে শেষ মাথায় বাতিটা জ্বলে। এখন প্রশ্ন করুন নিজেকে - বাতিটা আসলে বিদ্যুৎ পাচ্ছে কার কাছ থেকে? কর্ডগুলো নিজেরা কি বিদ্যুৎ তৈরি করে, নাকি শুধু একটা থেকে আরেকটায় \"ধার করা\" বিদ্যুৎ পাস করে দিচ্ছে? আর যদি দেয়ালের সকেট থেকে মূল সংযোগটাই কেটে দেন, তাহলে কি মাঝখানে যতগুলো কর্ডই থাকুক না কেন, বাতিটা সাথে সাথে নিভে যাবে না? এই সাধারণ পর্যবেক্ষণটাই আসলে থমাস আকুইনাসের \"পাঁচটি পথ\"-এর দ্বিতীয় পথের মূল কথা - যাকে বলা হয় \"নিমিত্ত কারণের যুক্তি\" (Argument from Efficient Causality)। গত পর্বে আমরা \"পরিবর্তনের যুক্তি\" নিয়ে কথা বলেছিলাম, আজ দেখব এর কাছাকাছি অথচ আলাদা একটা যুক্তি নিয়ে - যেটা পরিবর্তন নিয়ে না, বরং জিনিসের অস্তিত্বই কোথা থেকে আসছে, সেই প্রশ্ন নিয়ে।", "যুক্তিটা কোথা থেকে এলো", "আকুইনাস তার \"সুম্মা থিওলজিকা\" গ্রন্থের প্রথম ভাগে (প্রশ্ন ২, অনুচ্ছেদ ৩) স্রষ্টার অস্তিত্বের পক্ষে পাঁচটি যুক্তি হাজির করেন। প্রথমটা ছিল পরিবর্তন নিয়ে, আর দ্বিতীয়টা শুরু হয় \"নিমিত্ত কারণ\" (efficient cause) নামের একটা ধারণা দিয়ে। এই শব্দটা অ্যারিস্টটলের দর্শন থেকে আসা - অ্যারিস্টটল বলতেন, যেকোনো জিনিসের চারটা ধরনের \"কারণ\" থাকতে পারে। ধরুন একটা কাঠের চেয়ার - এর \"বস্তুগত কারণ\" হলো কাঠ (যা দিয়ে বানানো), \"আকৃতিগত কারণ\" হলো চেয়ারের নকশা (যে রূপ এটা ধারণ করেছে), \"উদ্দেশ্যগত কারণ\" হলো বসার জন্য ব্যবহার (কেন এটা বানানো হলো), আর \"নিমিত্ত কারণ\" হলো কাঠমিস্ত্রি - যে আসলে কাজটা করেছে, যার হাতের শ্রমে কাঠের টুকরোগুলো চেয়ারে রূপান্তরিত হলো। আকুইনাসের দ্বিতীয় পথ এই শেষ ধরনের কারণ নিয়ে কথা বলে - কোনো কিছুকে অস্তিত্বে আনার বা তার মধ্যে পরিবর্তন ঘটানোর পেছনের \"উৎপাদক\" নিয়ে।", "মূল ধারণা: কেউ নিজের কারণ নিজে হতে পারে না", "আকুইনাসের যুক্তির শুরুর পর্যবেক্ষণটা সহজ - আমাদের চারপাশে জিনিসের একটা শৃঙ্খল দেখা যায়, যেখানে একটা জিনিস আরেকটার কারণে অস্তিত্বে থাকছে বা কাজ করছে। একটা বাচ্চার জন্মের পেছনে আছে তার মা-বাবা, একটা রুটির পেছনে আছে ময়দা মাখা হাত আর চুলার আগুন, একটা টেবিলের পেছনে আছে কাঠমিস্ত্রি। কোনো কিছুই নিজেই নিজের কারণ হতে পারে না - কারণ তাহলে সেটাকে নিজের অস্তিত্বের আগে থেকেই থাকতে হতো নিজেকে তৈরি করার জন্য, যা একটা সরাসরি স্ববিরোধিতা (contradiction)। একটা জিনিস নিজেকে নিজে জন্ম দিতে পারে না, নিজেকে নিজে বানাতে পারে না - এই সহজ যুক্তিসংগত নীতিটা মেনে নিলে, প্রতিটা কার্যকারণ সম্পর্কে দেখা যায় একটা জিনিস তার অস্তিত্ব বা কার্যক্ষমতা পাচ্ছে তার বাইরের অন্য কোনো উৎস থেকে।", "যুক্তির কাঠামো", "পুরো যুক্তিটা সংক্ষেপে এভাবে সাজানো যায়:", "১) আমরা জগতে নিমিত্ত কারণের একটা ক্রম বা শৃঙ্খল দেখি - এটা এই ওটার কারণ, ওটা আবার আরেকটার কারণ।", "২) কোনো কিছু নিজের নিজের নিমিত্ত কারণ হতে পারে না, কারণ তাহলে তাকে নিজের অস্তিত্বের আগেই থাকতে হবে - যা অসম্ভব।", "৩) সুতরাং প্রতিটা কারণই তার কার্যকারিতা পাচ্ছে তার আগের কোনো কারণ থেকে।", "৪) এই শৃঙ্খল অসীম পর্যন্ত পেছাতে পারে না - কারণ তাহলে গোড়াতেই এমন কোনো সত্যিকারের উৎস থাকবে না, যেখান থেকে বাকি সবাই তাদের কার্যকারিতা \"ধার\" করছে। কারণ সরিয়ে নিলে ফলও চলে যায় - প্রথম কারণ না থাকলে মাঝের বা শেষের কারণও থাকতে পারে না।", "৫) সুতরাং একটা \"প্রথম নিমিত্ত কারণ\" থাকতেই হবে, যে নিজে অন্য কারো ওপর নির্ভরশীল না, বরং নিজের ভেতরেই কার্যকারিতার উৎস ধারণ করে - আকুইনাস একেই বলেন ঈশ্বর।", "একটা জরুরি পার্থক্য: এটা পরিবর্তনের যুক্তি থেকে আলাদা কেন", "গত পর্বের \"পরিবর্তনের যুক্তি\" (প্রথম পথ) নিয়ে যারা পড়েছেন, তাদের মনে হতে পারে এটা তো প্রায় একই কথা। পার্থক্যটা সূক্ষ্ম কিন্তু গুরুত্বপূর্ণ। প্রথম পথ কথা বলে \"পরিবর্তন\" নিয়ে - সম্ভাবনা থেকে বাস্তবতায় রূপান্তর নিয়ে, যেমন ঠান্ডা থেকে গরম হওয়া। দ্বিতীয় পথ আরও বিস্তৃত - এটা কথা বলে যেকোনো জিনিসের অস্তিত্বই বা কার্যকারিতাই কোথা থেকে আসছে, সেই প্রশ্ন নিয়ে, শুধু অবস্থার বদল নিয়ে না। আরেকটা গুরুত্বপূর্ণ বিষয় হলো, এখানেও আকুইনাস যে \"অসীম শৃঙ্খল সম্ভব না\" বলছেন, সেটা সময়ের দিক থেকে অতীতের দিকে পেছানো একটা শৃঙ্খল না - এটা এই মুহূর্তে, এখনই চলমান একটা নির্ভরতার সম্পর্ক। আমাদের এক্সটেনশন কর্ডের উদাহরণটাই আবার ভাবুন - মাঝের কর্ডগুলো নিজে থেকে কোনো বিদ্যুৎ তৈরি করে না, তারা শুধু দেয়ালের সকেট থেকে আসা বিদ্যুৎ পরবর্তী কর্ডে পাঠিয়ে দিচ্ছে। এই কর্ডের সংখ্যা দুইটা হোক বা দুইশোটা, তাতে কিছু আসে যায় না - যদি শেষমেশ একটা মূল উৎস (সকেট) না থাকে যেখান থেকে আসল বিদ্যুৎটা আসছে, তাহলে পুরো শৃঙ্খলেই কোনো বিদ্যুৎ থাকবে না, বাতিও জ্বলবে না। একে বলা হয় \"essentially ordered\" বা সহজাতভাবে সাজানো শৃঙ্খল - যেখানে প্রতিটা সদস্য তার কার্যকারিতা এই মুহূর্তে ধার করছে আরেকজনের কাছ থেকে, নিজের ভেতরে কোনো স্বাধীন উৎস নেই তার। এর বিপরীতে আছে সময়ের সাথে চলা একটা সাধারণ ধারাবাহিকতা, যেমন এক প্রজন্মের পর আরেক প্রজন্মের জন্ম - যেখানে আগের সদস্য না থাকলেও পরের সদস্য নিজে থেকেই কাজ চালাতে সক্ষম। আকুইনাসের যুক্তি প্রথম ধরনের শৃঙ্খল নিয়ে, আর এখানেই তার মূল দাবি - এই ধরনের \"ধার করা কার্যকারিতা\"র শৃঙ্খল অসীম হতে পারে না, কোথাও একটা সত্যিকারের, নিজস্ব উৎস থাকতেই হবে।", "সবচেয়ে শক্তিশালী সমর্থন কী", "এই যুক্তির শক্তি হলো এটা এমন একটা নীতির ওপর দাঁড়িয়ে আছে যা আমরা প্রতিদিনের জীবনে, এমনকি বিজ্ঞানের গবেষণাতেও মেনে চলি - কোনো জিনিস নিজে নিজে শূন্য থেকে নিজেকে তৈরি করতে পারে না, তার পেছনে কোনো না কোনো কারণ থাকতেই হবে। এই নীতিকে বলা হয় \"পর্যাপ্ত কারণের নীতি\" (Principle of Sufficient Reason)-এর একটা সংস্করণ, আর এটা বিজ্ঞানের প্রায় প্রতিটা শাখার ভিত্তি - পদার্থবিজ্ঞানী কোনো ঘটনা দেখলে জিজ্ঞেস করেন \"এটা কেন ঘটল\", ডাক্তার রোগের কারণ খোঁজেন, প্রকৌশলী একটা সেতু ভেঙে পড়লে তার কারণ অনুসন্ধান করেন। \"এমনি এমনি, কোনো কারণ ছাড়াই ঘটেছে\" - এই উত্তরে আমরা কখনো সন্তুষ্ট হই না। আকুইনাসের যুক্তি এই সাধারণ প্রবৃত্তিটাকেই যুক্তিসংগতভাবে শেষ পর্যন্ত টেনে নিয়ে যায়।", "এবার আসি সমালোচনার দিকে", "প্রথম আপত্তিটা আসে বিশ শতকের দার্শনিক বার্ট্রান্ড রাসেল (Bertrand Russell)-এর কাছ থেকে, যিনি ধর্মতাত্ত্বিক ফ্রেডেরিক কপলস্টন (Frederick Copleston)-এর সাথে ১৯৪৮ সালের বিখ্যাত এক বিতর্কে বলেছিলেন - মহাবিশ্ব বা কার্যকারণের পুরো শৃঙ্খলটাকে \"ব্যাখ্যা করার\" কোনো বাধ্যবাধকতা নেই। তার ভাষায়, \"মহাবিশ্ব এমনিই আছে, ব্যস, এটাই সব\" (the universe is just there, and that's all)। এই আপত্তিকে বলা হয় \"স্ববলম্বিতার আপত্তি\" (self-sufficiency objection) - হয়তো পুরো শৃঙ্খলটাকেই একটা \"মৌলিক সত্য\" (brute fact) হিসেবে মেনে নেওয়া যায়, যার আর কোনো আলাদা ব্যাখ্যা দরকার নেই। আকুইনাসের সমর্থকরা এর জবাবে বলেন, এটা আসলে ব্যাখ্যা এড়িয়ে যাওয়া, ব্যাখ্যা দেওয়া না - প্রতিটা অংশের যদি একটা কারণ থাকতে হয়, তাহলে পুরো শৃঙ্খলটারও একটা কারণ প্রয়োজন, শুধু অংশগুলো যোগ করে দিলেই সেই প্রয়োজনীয়তা হারিয়ে যায় না।", "দ্বিতীয় আপত্তিটা হলো \"অসীম রিগ্রেসের আপত্তি\" - স্কটিশ দার্শনিক ডেভিড হিউম (David Hume) যুক্তি দিয়েছিলেন, যদি শৃঙ্খলের প্রতিটা সদস্যকেই তার ঠিক আগের সদস্য দিয়ে ব্যাখ্যা করা যায়, তাহলে পুরো অসীম শৃঙ্খলটাই তো ব্যাখ্যা হয়ে গেল - আলাদা করে কোনো \"প্রথম কারণ\" খোঁজার দরকার কী? প্রতিটা ইট যদি তার পাশের ইটের ওপর দাঁড়িয়ে থাকে, তাহলে পুরো দেয়ালটাকে দাঁড় করানোর জন্য বাড়তি কিছু লাগে না, তেমনি। আকুইনাসের অনুসারীরা - যেমন আধুনিক থোমিস্ট দার্শনিক এডওয়ার্ড ফেজার (Edward Feser) - এই তুলনাটা প্রত্যাখ্যান করেন। তাদের যুক্তি, এখানে প্রশ্নটা ইটের সারি নিয়ে না, বরং \"ধার করা শক্তি\"র শৃঙ্খল নিয়ে - আমাদের এক্সটেনশন কর্ডের উদাহরণেই যেমন দেখা যায়, যদি প্রতিটা কর্ডই শুধু আগেরটা থেকে বিদ্যুৎ পাস করে দেয়, নিজে কিছু তৈরি না করে, তাহলে কর্ডের সংখ্যা যত বেশিই হোক, শেষ পর্যন্ত একটা আসল উৎস (জেনারেটর বা সকেট) না থাকলে গোটা শৃঙ্খলেই কোনো বিদ্যুৎ থাকবে না। সংখ্যা অসীম হলেও এই সমস্যাটা মেটে না, বরং আরও প্রকট হয়।", "তৃতীয় আপত্তিটা আসে আধুনিক কোয়ান্টাম পদার্থবিজ্ঞান থেকে। কিছু পদার্থবিজ্ঞানী বলেন, তেজস্ক্রিয় পরমাণুর ক্ষয় (radioactive decay) বা শূন্যস্থানে \"ভার্চুয়াল কণা\" (virtual particles) হুট করে তৈরি হওয়ার মতো ঘটনায় কোনো নির্দিষ্ট, শনাক্তযোগ্য কারণ খুঁজে পাওয়া যায় না - এগুলো সম্ভাব্যতার নিয়মে চলে, নির্দিষ্ট কার্যকারণ সম্পর্কে না। যদি প্রকৃতিতেই সত্যিকারের কারণহীন ঘটনা থাকতে পারে, তাহলে \"সবকিছুরই একটা কারণ থাকতে হবে\" - এই প্রাথমিক ধারণাটাই প্রশ্নের মুখে পড়ে। এর জবাবে দার্শনিকরা বলেন, বিষয়টা এখনও বিতর্কিত - কোয়ান্টাম ঘটনার \"কারণহীনতা\" আসলে আমাদের জ্ঞানের সীমাবদ্ধতা (আমরা কারণটা মাপতে পারি না) নাকি সত্যিই প্রকৃতিতে কারণহীন ঘটনা ঘটে, এই প্রশ্নে পদার্থবিজ্ঞানীদের মধ্যেই ঐকমত্য নেই। তা ছাড়া, আকুইনাসের যুক্তি মূলত সাধারণ অভিজ্ঞতার বস্তু নিয়ে, কোয়ান্টাম স্তরের সম্ভাব্যতাও শেষ পর্যন্ত কোনো অন্তর্নিহিত নিয়ম বা কাঠামোর মধ্যেই ঘটে বলে তারা মনে করিয়ে দেন। উপরন্তু, ‘শূন্যস্থানে’ ভার্চুয়াল কণা আবির্ভূত হওয়া মিশে যাওয়া এবং একটি কো-অর্ডিনেটেড সিস্টেমের অস্থিত্বে আসার মধ্যে আকাশ-পাতাল তফাৎ।", "চতুর্থ আপত্তিটা আগের পর্বে যেমন বলেছিলাম, সেই \"অনন্যতার সমস্যা\"রই একটা সংস্করণ - এমনকি যদি মেনেও নিই একটা প্রথম কারণ থাকতে হবে, যুক্তিটা কোথাও প্রমাণ করে না এই কারণ একটাই, বা এটার বুদ্ধি-ইচ্ছা-ব্যক্তিত্ব আছে। আকুইনাস নিজে বলতেন, পাঁচটি পথ শুধু শুরুর ধাপ - সুম্মা থিওলজিকার পরের অংশে তিনি আলাদাভাবে দেখান কেন এই প্রথম কারণ একটাই হতে হবে এবং কেন তার মধ্যে বুদ্ধিমত্তার মতো গুণ থাকতে হবে। সমালোচকরা মনে করেন এই পরের ধাপগুলো প্রথম পাঁচটা পথের মতো সোজাসাপ্টা না, আরও অনেক অতিরিক্ত অনুমানের ওপর দাঁড়িয়ে আছে।", "শেষ কথা", "আকুইনাসের এই দ্বিতীয় পথ আমাদের এমন একটা প্রশ্নের সামনে দাঁড় করায় যা এড়ানো কঠিন - আমাদের চারপাশের প্রতিটা জিনিসই যখন তার অস্তিত্ব বা কার্যক্ষমতা অন্য কারো কাছ থেকে \"ধার\" করে নিচ্ছে বলে মনে হয়, তখন কোথাও কি এমন কিছু থাকা দরকার যে নিজেই নিজের অস্তিত্বের উৎস, যার কাছে আর কারো কাছে ধার চাইতে হয় না? নাকি পুরো ব্যাপারটাকেই আমরা একটা মৌলিক সত্য হিসেবে মেনে নিতে পারি, যার পেছনে আর কোনো \"কেন\" খোঁজার দরকার নেই? এই বিতর্ক আটশো বছর পরেও দর্শনের সামনের সারিতে জীবন্ত - পদার্থবিজ্ঞান, যুক্তিবিজ্ঞান আর ধর্মতত্ত্ব - তিন জায়গা থেকেই এখনও এটা নিয়ে আলোচনা চলছে।"], "source": "philosophy"}, {"id": "ai-2026-09-22", "date": "2026-09-22", "title": "AI in healthcare research — a few things from today's reading — 22 September 2026", "excerpt": "Today's LLM findings were largely about where language models help and where they don't yet match clinicians. GPT-4, validated against specialist consensus diagnoses for…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DigitalHealth", "HealthTech"], "body": ["Today's LLM findings were largely about where language models help and where they don't yet match clinicians. GPT-4, validated against specialist consensus diagnoses for 101 patients with systemic autoimmune disease, reached 97.03% overall diagnostic accuracy — climbing from 82.18% on history alone once immunological results were added, and hitting 100% for lupus, Sjögren's syndrome, and three other conditions. In a head-to-head against real-world Medscape respondents on 1,426 case-challenge questions, GPT-4o and o1 scored 88.4% and 94.3% versus 85.0% for the human respondents. But context still matters: ChatGPT-4o's radiology accuracy swung from 19.9% on images alone to 80.9% once clinical data and answer options were added, and a 64-clinician evaluation found GPT-4 clearly ahead of GPT-3.5 on spinal neurosurgery and physical therapy scenarios. On the patient-facing side, a randomized trial of 1,297 parents found a brief GPT-4o chatbot boosted HPV vaccination intent as much as standard public health materials in the short term, but the effect faded by 45 days while the materials' effect held.", "On the ML/DL side, today's papers clustered around ICU and cancer mortality prediction. Random forest and XGBoost models are now routinely matching or beating classic scores: random forest hit AUROC 0.8423 for general ICU mortality (vs 0.736 for SOFA), and a coronary artery disease model reached AUC 0.914 on external validation for 28-day mortality across nearly 16,000 patients. Random survival forest also outperformed Cox regression and XGBoost for both colorectal cancer disease-free survival (5-year AUC 0.799) and pulmonary large cell carcinoma overall survival (5-year AUC 0.863). Not every added-complexity model paid off, though — a machine learning mortality model for over a million pediatric surgery encounters performed no better than a simple existing regression score, a useful counterpoint to the pattern.", "Together, today's studies reinforce a familiar theme: LLMs are creeping toward reliable diagnostic support in well-scoped clinical contexts, while ML risk models keep demonstrating strong discrimination in ICU and oncology settings — though not automatically better than simpler existing tools."], "refs": [{"title": "GPT-4 validated for systemic autoimmune disease diagnosis (97.03% accuracy)", "url": "https://pubmed.ncbi.nlm.nih.gov/41429305/"}, {"title": "GPT-4o and o1 vs Medscape respondents on clinical case challenges", "url": "https://pubmed.ncbi.nlm.nih.gov/41578521/"}, {"title": "ChatGPT-4o radiology accuracy by input type (image vs clinical data vs options)", "url": "https://pubmed.ncbi.nlm.nih.gov/40977631/"}, {"title": "LLM chatbot vs public health materials for HPV vaccination intent, RCT", "url": "https://pubmed.ncbi.nlm.nih.gov/42258213/"}, {"title": "Random forest ICU mortality model vs SOFA/APACHE II", "url": "https://pubmed.ncbi.nlm.nih.gov/42147703/"}, {"title": "Random forest model for coronary artery disease ICU mortality, multicenter", "url": "https://pubmed.ncbi.nlm.nih.gov/41982544/"}, {"title": "Random survival forest vs Cox/XGBoost for colorectal cancer survival", "url": "https://pubmed.ncbi.nlm.nih.gov/42178520/"}, {"title": "Machine learning mortality model for pediatric noncardiac surgery vs regression score", "url": "https://pubmed.ncbi.nlm.nih.gov/42648281/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-21", "date": "2026-09-21", "title": "AI in healthcare research — a few things from today's reading — 21 September 2026", "excerpt": "Today's LLM papers leaned toward diagnostic reasoning and clinical documentation rather than new model benchmarks. A reasoning-tuned open-source LLM (RaDaR, 32B…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DiagnosticAI", "DigitalHealth"], "body": ["Today's LLM papers leaned toward diagnostic reasoning and clinical documentation rather than new model benchmarks. A reasoning-tuned open-source LLM (RaDaR, 32B parameters) built for rare disease diagnosis outperformed the much larger 671B DeepSeek-R1 across public benchmarks, and in a retrospective cohort it flagged the correct final diagnosis before clinicians documented their own suspicion in 61.1% of cases — a potential 1.87-month head start. On the diagnostic-support side, ChatGPT-4o matched or beat expert oral medicine specialists at Top-1 differential accuracy for 80 salivary gland cases (86.7% vs 50.0%), while a purpose-built diagnostic LLM (ClinDiag-GPT), trained on 4,421 real cases, outperformed GPT-4o and Claude-3-Haiku on procedural diagnostic accuracy — with human-AI collaboration beating either working alone. A more cautious note came from a 15-model, 468-case benchmark testing iterative evidence-seeking rather than static Q&A: diagnostic accuracy dropped 12.75% once models had to ask their own follow-up questions, suggesting today's LLM benchmarks may overstate real-world clinical decision support performance.", "On the ML/DL side, imaging and risk models continued to post strong discrimination. A CT bone-window deep learning model for spinal tuberculosis reached AUC 0.92 internally and 0.87-0.94 across three external test sites. A meta-analysis of five studies (12,545 radiographs) found deep learning models detect peri-implant bone loss at 88% sensitivity, 91% specificity, and AUC 0.95. In critical care, an XGBoost model for COPD readmission and mortality (AUC 0.77) clearly outperformed the standard CODEX score (AUC 0.59), while a multi-hospital-pooled XGBoost model for ICU readmission/mortality showed only modest generalizability (weighted AUROC ~71%) when tested externally — a reminder that locally-trained risk models don't always travel well.", "Together, today's findings point to LLMs edging toward genuine diagnostic utility in narrow domains, alongside a growing recognition that evaluation methodology — interactive vs. static, external vs. internal validation — matters as much as raw accuracy."], "refs": [{"title": "RaDaR reasoning LLM for rare disease diagnosis, randomized trial", "url": "https://arxiv.org/abs/2606.24510"}, {"title": "ChatGPT-4o vs oral medicine specialists on salivary gland disease diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/41466068/"}, {"title": "ClinDiag-GPT grounded diagnostic LLM vs GPT-4o/Claude-3-Haiku", "url": "https://pubmed.ncbi.nlm.nih.gov/41881991/"}, {"title": "Multi-turn evidence-seeking reduces LLM diagnostic accuracy 12.75%", "url": "https://arxiv.org/abs/2605.22047"}, {"title": "Deep learning CT model for spinal tuberculosis diagnosis (multi-center)", "url": "https://pubmed.ncbi.nlm.nih.gov/41459642/"}, {"title": "Deep learning meta-analysis for peri-implant marginal bone loss detection", "url": "https://pubmed.ncbi.nlm.nih.gov/41562630/"}, {"title": "XGBoost model for COPD readmission/mortality vs CODEX score", "url": "https://pubmed.ncbi.nlm.nih.gov/40777144/"}, {"title": "Multi-hospital ICU readmission/mortality model generalizability study", "url": "https://pubmed.ncbi.nlm.nih.gov/41180106/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-20", "date": "2026-09-20", "title": "AI in healthcare research — a few things from today's reading — 20 September 2026", "excerpt": "Today's LLM papers centered on documentation and diagnostic support rather than new model releases. A blinded comparison of 99 emergency department encounters found…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "DiagnosticAI", "ClinicalAI", "DigitalHealth"], "body": ["Today's LLM papers centered on documentation and diagnostic support rather than new model releases. A blinded comparison of 99 emergency department encounters found LLM-generated one-liner summaries preferred over physician-authored ones 50.5% of the time versus 38.4% for physicians. A similar prompt-engineered LLM assistant for hepatology referral triage cut clinician review time by about 60% while keeping hallucination rates low. On the diagnostic side, ChatGPT-4o and GPT-5 reached 77.1% and 57.6% partial concordance respectively against true diagnoses in 33 pediatric tumor pathology cases, and a four-version ChatGPT comparison on 50 complex oral and maxillofacial cases was benchmarked directly against experienced dentists. A separate study of general-use AI chatbots classifying impacted mandibular third molars found none reached acceptable agreement with expert consensus, a useful reminder that diagnostic imitation and diagnostic reliability are not the same thing.", "On the ML/DL side, imaging models again showed strong discrimination across a range of conditions. A deep learning-enabled single breath-hold abbreviated MRI protocol for hepatocellular carcinoma matched conventional full MRI (sensitivity 77.9-88.7% vs. 84.4-92.5%) while cutting scan time by more than 15 minutes and removing the need for contrast. A CNN-based diagnostic model for laryngoscopy images, trained and externally validated across five countries, reached AUC 0.85-0.90 and outperformed both general practitioners and ChatGPT-4o. A CNN using dynamic cervical radiographs predicted spinal cord compression (AUC 0.888) as a lower-cost alternative to MRI, and a multi-signal model combining CT deep learning, radiomics, and blood immune profiling raised lung cancer diagnosis AUC from 0.69-0.73 (individual signals) to 0.81 combined. On the risk-prediction front, a random forest model beat standard clinical scores for ulcerative colitis readmission, and a SHAP-interpretable analysis of 12,041 type 2 diabetes patients showed readmission risk factors shift over time — age matters most at 30 days, inflammatory markers and length of stay at 60 days, chronic complications by 365 days.", "Today's findings lean toward incremental validation work: LLMs proving useful for documentation and triage support, and imaging/ML models continuing to post strong but not universally reliable diagnostic accuracy."], "refs": [{"title": "LLM-generated ED clinical summaries, blinded comparison", "url": "https://pubmed.ncbi.nlm.nih.gov/42424264/"}, {"title": "LLM assistant for hepatology referral summarization (60% faster triage)", "url": "https://pubmed.ncbi.nlm.nih.gov/41504326/"}, {"title": "ChatGPT-4o vs GPT-5 diagnostic concordance in pediatric tumor pathology", "url": "https://pubmed.ncbi.nlm.nih.gov/41467543/"}, {"title": "Chatbots vs experts classifying impacted mandibular third molars", "url": "https://pubmed.ncbi.nlm.nih.gov/40996614/"}, {"title": "DL abbreviated single breath-hold MRI protocol for hepatocellular carcinoma", "url": "https://pubmed.ncbi.nlm.nih.gov/42159476/"}, {"title": "Multicenter AI diagnostic model for laryngoscopy images", "url": "https://pubmed.ncbi.nlm.nih.gov/41696998/"}, {"title": "CT deep learning + radiomics + blood immune profiling for lung cancer diagnosis (AUC 0.81)", "url": "https://pubmed.ncbi.nlm.nih.gov/41719793/"}, {"title": "SHAP-interpretable ML model for time-varying type 2 diabetes readmission risk", "url": "https://pubmed.ncbi.nlm.nih.gov/42440445/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-19", "date": "2026-09-19", "title": "AI in healthcare research — a few things from today's reading — 19 September 2026", "excerpt": "Today's LLM papers focused mostly on chatbots supporting care delivery and communication. A GPT-4.0 mini-based chatbot (PreA) co-designed with clinical stakeholders…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "DiagnosticAI", "DigitalHealth", "ClinicalAI"], "body": ["Today's LLM papers focused mostly on chatbots supporting care delivery and communication. A GPT-4.0 mini-based chatbot (PreA) co-designed with clinical stakeholders reduced physician consultation time by 28.7% for primary-to-specialist care transitions in a randomized trial of 2,069 patients. A fully offline multimodal system, MedChat, paired an LLM with a diffusion-driven avatar for structured patient anamnesis while keeping patient data isolated from model inference, running at under 3 seconds average latency. Comparing five chatbots (ChatGPT, Gemini, Copilot, DeepSeek, Grok-3) against medical information scientists on 45 clinical PICO questions found no significant difference between models, with only 20.9% of the 225 total answers reaching full alignment with expert evidence summaries. On the evaluation side, a systematic review catalogued persistent limitations in LLM-generated healthcare content, and a differential-privacy fine-tuning framework (MedDP) mapped the trade-off between model utility and patient-data privacy leakage on medical QA benchmarks.", "On the ML/DL side, several imaging and lab-based models reported strong discrimination for diagnosis and risk stratification. A ResNet-50 model for stroke risk in carotid plaque reached an AUC of 0.982, a 9.7-point improvement over the best traditional ML model, while a diffusion-weighted-imaging-only deep learning model detected acute ischemic infarcts with 90.8% accuracy and AUC 0.93 in under a second per scan. For pancreatic cancer, deep learning models matched or beat a six-reader average (AUC 0.99 on contrast CT) and showed much higher sensitivity for small tumors (98% vs. 82.6% on CECT). A multimodal ultrasound-plus-clinical-data model improved breast lesion classification to AUC 0.852 from 0.757 with imaging alone, and a hybrid ResNet-attention-recurrent network classified Alzheimer's stages with 94.5% accuracy. Lab-based models included a random forest for early sepsis-induced coagulopathy (AUCs 0.76-0.79) and a gradient boosting model for diabetic microvascular complication risk.", "Today's mix skewed toward imaging-based deep learning for diagnosis alongside LLM chatbots aimed at reducing clinician workload rather than replacing clinical judgment."], "refs": [{"title": "PreA LLM chatbot RCT for care transitions (28.7% shorter consultations)", "url": "https://pubmed.ncbi.nlm.nih.gov/41555035/"}, {"title": "MedChat offline multimodal AI for clinical anamnesis", "url": "https://pubmed.ncbi.nlm.nih.gov/42080058/"}, {"title": "Five generative AI chatbots vs. medical information scientists", "url": "https://pubmed.ncbi.nlm.nih.gov/41040708/"}, {"title": "MedDP differentially-private LLM framework for sensitive healthcare", "url": "https://pubmed.ncbi.nlm.nih.gov/42262952/"}, {"title": "ResNet-50 deep learning stroke risk model for carotid plaque (AUC 0.982)", "url": "https://pubmed.ncbi.nlm.nih.gov/42094969/"}, {"title": "DWI-only deep learning model for acute ischemic infarct detection", "url": "https://pubmed.ncbi.nlm.nih.gov/42138578/"}, {"title": "Deep learning detection of pancreatic cancer on CT", "url": "https://pubmed.ncbi.nlm.nih.gov/42301012/"}, {"title": "Multimodal ultrasound deep learning model for breast lesion classification", "url": "https://pubmed.ncbi.nlm.nih.gov/42122082/"}], "lang": "en", "source": "ai"}, {"id": "ph-2026-09-11-argument-from-change", "date": "2026-09-18", "title": "পরিবর্তনের যুক্তি: অ্যাকুইনাসের প্রথম পথ", "title_en": "The Argument from Change (Aquinas's Five Ways)", "excerpt": "পরিবর্তনের যুক্তি: এক কাপ চা ঠান্ডা হওয়া থেকে আকুয়াইনাসের প্রথম পথ পর্যন্ত", "theme": "faith", "cats": ["স্রষ্টার অস্তিত্বের যুক্তি", "দর্শন"], "body": ["পরিবর্তনের যুক্তি: এক কাপ চা ঠান্ডা হওয়া থেকে আকুয়াইনাসের প্রথম পথ পর্যন্ত", "আপনার সামনে রাখা এক কাপ গরম চা একটু পরেই ঠান্ডা হয়ে যায়। বরফ গলে পানি হয়ে যায়। একটা শিশু বড় হয়ে যুবক হয়, তারপর বৃদ্ধ। আশেপাশে তাকালে দেখবেন, প্রতিটা মুহূর্তে কিছু না কিছু বদলাচ্ছে - কোনো কিছুই একই অবস্থায় স্থির থাকছে না। এই এত সাধারণ, এত রোজকার একটা ঘটনা - \"পরিবর্তন\" - এটা নিয়ে কখনো গভীরভাবে ভেবেছেন? জিনিসটা কি নিজে নিজেই বদলায়, নাকি প্রতিটা পরিবর্তনের পেছনে কিছু একটা কাজ করে? প্রায় আটশো বছর আগে খ্রিস্টান দার্শনিক-ধর্মতাত্ত্বিক থমাস আকুয়াইনাস (Thomas Aquinas) এই সহজ প্রশ্ন থেকেই শুরু করেছিলেন এমন একটা যুক্তি, যেটা তার বিখ্যাত \"পাঁচটি পথ\" (Five Ways)-এর প্রথমটা, আর আজও দর্শনের জগতে সমান প্রাসঙ্গিক। চলুন আজ সহজ ভাষায় বোঝার চেষ্টা করি যুক্তিটা আসলে কী বলে, আর কোথায় এটা নিয়ে বিতর্ক আছে।", "যুক্তিটা কোথা থেকে এলো", "থমাস আকুয়াইনাস ছিলেন ত্রয়োদশ শতাব্দীর একজন ইতালীয় সন্ন্যাসী আর দার্শনিক, যিনি তার বিশাল গ্রন্থ \"সুম্মা থিওলজিকা\" (Summa Theologica)-তে ঈশ্বরের অস্তিত্বের পক্ষে পাঁচটি যুক্তি হাজির করেন - এগুলোকেই বলা হয় \"পাঁচটি পথ\"। প্রথম পথটা শুরু হয় \"পরিবর্তন\" (change বা motion) দিয়ে - আকুয়াইনাস নিজে বলেছিলেন, এটাই সবচেয়ে স্পষ্ট আর সহজবোধ্য পথ, কারণ পরিবর্তন আমাদের চোখের সামনে প্রতিনিয়ত ঘটছে, এটা অস্বীকার করার উপায় নেই। এই যুক্তির শিকড় অবশ্য আরও পুরনো - প্রাচীন গ্রিক দার্শনিক অ্যারিস্টটল তার \"ফিজিক্স\" আর \"মেটাফিজিক্স\" গ্রন্থে \"অপরিবর্তনীয় পরিবর্তক\" (Unmoved Mover) নামে একটা ধারণা হাজির করেছিলেন। আকুয়াইনাস অ্যারিস্টটলের এই কাঠামোটা নিয়ে সেটাকে একটা ধর্মতাত্ত্বিক ভিত্তির ওপর দাঁড় করান।", "মূল ধারণা: সম্ভাবনা আর বাস্তবতা", "এই যুক্তিটা বুঝতে হলে প্রথমে দুইটা শব্দ বুঝতে হবে, যেগুলো অ্যারিস্টটল আর আকুয়াইনাস দুজনেই ব্যবহার করেছেন - \"সম্ভাবনা\" (potentiality) আর \"বাস্তবতা\" বা \"কার্যকারিতা\" (actuality)। ব্যাপারটা আসলে খুব জটিল না। ধরুন আপনার সামনে এক কাপ ঠান্ডা চা আছে। এই চায়ের মধ্যে \"গরম হওয়ার সম্ভাবনা\" আছে - অর্থাৎ এটা গরম হতে পারে, এমন প্রবণতা তার মধ্যে লুকিয়ে আছে। কিন্তু চা নিজে থেকে গরম \"হয়ে যায় না\" - এটা গরম হওয়ার জন্য দরকার আগুন বা চুলা, যেটা ইতিমধ্যে \"বাস্তবে গরম\" (actually hot)। একইভাবে, একটা কাঠের গুঁড়ির মধ্যে \"আগুন হয়ে ওঠার সম্ভাবনা\" আছে, কিন্তু সেই সম্ভাবনাকে বাস্তবে রূপ দিতে দরকার হয় এমন কিছু, যেটা ইতিমধ্যে বাস্তবে জ্বলছে - যেমন একটা দেশলাইয়ের আগুন। আকুয়াইনাসের মূল দাবিটা হলো - কোনো কিছু নিজের সম্ভাবনাকে নিজে নিজে বাস্তবে পরিণত করতে পারে না। চা নিজেকে নিজে গরম করতে পারে না; কাঠ নিজেকে নিজে জ্বালাতে পারে না। যা \"সম্ভাবনায়\" আছে, তাকে বাস্তবে আনতে হলে এমন কিছু লাগবে যেটা ইতিমধ্যে \"বাস্তবে\" সেই গুণটা ধারণ করে আছে।", "যুক্তির কাঠামো", "এই ধারণা থেকেই যুক্তিটা দাঁড় করানো যায়, মোটামুটি এভাবে:", "১) আমরা চোখের সামনে দেখি, জগতে জিনিস পরিবর্তিত হচ্ছে (অর্থাৎ সম্ভাবনা থেকে বাস্তবতায় রূপান্তরিত হচ্ছে)।", "২) যা কিছু পরিবর্তিত হয়, তা নিজে নিজে পরিবর্তিত হতে পারে না - তাকে অন্য কিছু দিয়ে পরিবর্তিত করতে হয়, যা ইতিমধ্যে বাস্তবে সেই গুণ ধারণ করে।", "৩) এই \"পরিবর্তনকারী\"ও যদি নিজে পরিবর্তনশীল হয়, তাহলে তাকেও আবার অন্য কিছু পরিবর্তিত করছে - আর এভাবে একটা শৃঙ্খল তৈরি হয়।", "৪) এই শৃঙ্খল অসীম পর্যন্ত পেছাতে পারে না, কারণ তাহলে শুরুতেই কোনো প্রকৃত কার্যকারিতা (actuality) থাকবে না, যা থেকে বাকি সব শক্তি পাবে।", "৫) সুতরাং শেষ পর্যন্ত এমন একটা সত্তা থাকতে হবে, যে নিজে পরিবর্তিত হয় না, কিন্তু বাকি সবকিছুকে পরিবর্তিত করে - এটাই \"অপরিবর্তনীয় পরিবর্তক\" (Unmoved Mover), যাকে আকুয়াইনাস চিহ্নিত করেন ঈশ্বর হিসেবে।", "হাত, লাঠি আর পাথর - একটা জরুরি পার্থক্য", "এখানে একটা জিনিস স্পষ্ট করে বোঝা দরকার, কারণ এটা প্রায়ই ভুল বোঝা হয়। আকুয়াইনাস যে \"অসীম শৃঙ্খল সম্ভব না\" বলছেন, সেটা কোনো সময়ের হিসেবে অতীতের দিকে পেছানো শৃঙ্খল না (যেমনটা \"কালাম\" যুক্তিতে ছিল, যেখানে প্রশ্ন ছিল মহাবিশ্বের সময়ের শুরু আছে কিনা)। এখানে প্রশ্নটা ভিন্ন - এটা একই মুহূর্তে, এখনই ঘটে চলা একটা নির্ভরতার শৃঙ্খল নিয়ে। আকুয়াইনাস নিজে একটা উদাহরণ দিয়েছিলেন - একটা হাত একটা লাঠি দিয়ে একটা পাথরকে নাড়াচ্ছে। এখানে পাথরটা নড়ছে লাঠির কারণে, লাঠিটা নড়ছে হাতের কারণে - কিন্তু লাঠির নিজের মধ্যে নড়ানোর কোনো ক্ষমতা নেই, সে শুধু হাত থেকে ধার করা শক্তি দিয়ে পাথরটা নাড়াচ্ছে। যদি হাতটা থেমে যায়, লাঠিও থেমে যাবে, পাথরও থেমে যাবে - সব একসাথে, এখনই। এই তিনটা জিনিস একই সময়ে ঘটছে, একটা আরেকটার ওপর নির্ভরশীল। এটাকে বলা হয় \"essentially ordered\" শৃঙ্খল। এর বিপরীতে আছে \"accidentally ordered\" শৃঙ্খল - যেমন একজন ব্যক্তি একটা সন্তানের জন্ম দেন, সেই সন্তান বড় হয়ে আরেকটা সন্তানের জন্ম দেন - এখানে প্রথম ব্যক্তি মারা গেলেও দ্বিতীয় প্রজন্মের সন্তান জন্ম নিতে কোনো বাধা নেই, কারণ প্রতিটা প্রজন্ম নিজের মধ্যেই জন্ম দেওয়ার সম্পূর্ণ ক্ষমতা ধারণ করে। কালাম যুক্তি কথা বলে দ্বিতীয় ধরনের শৃঙ্খল নিয়ে - অতীতের দিকে সময় ধরে পেছানো একটা লাইন। আর আকুয়াইনাসের এই যুক্তি কথা বলে প্রথম ধরনের শৃঙ্খল নিয়ে - এখন, এই মুহূর্তে, একটা জিনিস আরেকটার ওপর নির্ভর করে টিকে থাকার আর কাজ করার শক্তি পাচ্ছে কিনা। আকুয়াইনাসের মতে, এই ধরনের নির্ভরতার শৃঙ্খল অসীম হতে পারে না, কারণ যদি প্রতিটা সদস্যই শুধু ধার করা শক্তি নিয়ে চলে, তাহলে কোথাও না কোথাও এমন একটা উৎস থাকতে হবে যে নিজে থেকেই শক্তিশালী, ধার করা না।", "সবচেয়ে শক্তিশালী সমর্থন কী", "এই যুক্তির আকর্ষণ হলো এটা শুরু হয় এমন একটা পর্যবেক্ষণ থেকে যা কেউ অস্বীকার করতে পারে না - পরিবর্তন সত্যিই ঘটে, এটা নিয়ে কোনো তর্ক নেই। আর \"কোনো কিছু নিজেকে নিজে দিতে পারে না যা তার নেই\" - এই স্বজ্ঞাটাও (intuition) বেশ শক্তিশালী। একটা খালি ব্যাংক অ্যাকাউন্ট থেকে আপনি নিজে নিজে টাকা বের করতে পারবেন না; কাউকে না কাউকে সেখানে টাকা জমা দিতে হবে। একইভাবে, যার নিজের মধ্যে কোনো গুণ \"বাস্তবে\" নেই, সে সেই গুণ অন্য কাউকে দিতে পারে না। এই সাধারণ যুক্তিসংগত নীতিটাকে বিজ্ঞান আর দর্শন দুই জায়গাতেই মেনে চলা হয় - কার্যকারণ সম্পর্ক (causation) নিয়ে আমাদের প্রতিদিনের চিন্তাভাবনার ভিত্তিই এটা।", "এবার আসি সমালোচনার দিকে", "প্রথম আর সবচেয়ে পরিচিত আপত্তিটা আসে আধুনিক পদার্থবিজ্ঞান থেকে। নিউটনের জড়তার সূত্র (law of inertia) বলে, গতিশীল কোনো বস্তু বাইরের কোনো বল ছাড়াই সমবেগে চলতে থাকতে পারে - তাকে চলতে থাকার জন্য কোনো \"ক্রমাগত পরিবর্তনকারী\"র দরকার নেই। তাহলে কি আকুয়াইনাসের প্রথম প্রস্তাবনা - \"যা নড়ে, তা অন্য কিছুর দ্বারা নড়ে\" - ভুল প্রমাণিত হয় না? আকুয়াইনাসের সমর্থকরা জবাবে বলেন, আকুয়াইনাস শুধু স্থান পরিবর্তনের (locomotion) কথা বলছেন না, বরং তার চেয়ে অনেক বিস্তৃত অর্থে \"পরিবর্তন\" বলতে বোঝাচ্ছেন - সম্ভাবনা থেকে বাস্তবতায় যেকোনো রূপান্তর, যেমন তাপমাত্রা বদলানো, রং বদলানো, অস্তিত্বে আসা। সমান বেগে সরল রেখায় চলা একটা বস্তুর ক্ষেত্রে বলা যায় এটা আসলে একটা \"অবস্থা\" (state), পরিবর্তন নয় - তাই জড়তার সূত্র এই যুক্তির মূল দাবিটাকে সরাসরি খণ্ডন করে না বলে তারা মনে করেন। সমালোচকরা অবশ্য এই জবাবেও পুরোপুরি সন্তুষ্ট নন, আর এই বিতর্ক এখনও চলমান।", "দ্বিতীয় আপত্তিটা তোলেন সমসাময়িক দার্শনিক গ্রাহাম অপি (Graham Oppy)-এর মতো চিন্তাবিদরা - \"অনন্যতার সমস্যা\" (uniqueness problem)। তাদের প্রশ্ন - ধরে নিলাম শৃঙ্খলের শেষে একটা \"অপরিবর্তনীয় উৎস\" থাকতে হবে, কিন্তু যুক্তির কোনো অংশে তো বলা হয়নি এই উৎস একটাই, বা এটাই সবার জন্য একই সত্তা। একাধিক আলাদা আলাদা \"প্রথম কারণ\" থাকলেও তো যুক্তিটা মেনে নেওয়া যায় - তাহলে এখান থেকে একেশ্বরবাদী ঈশ্বরের ধারণায় পৌঁছানো কীভাবে যৌক্তিক হয়?", "তৃতীয় আপত্তিটা আরও বিস্তৃত - একে বলা যায় \"বহু-লাফের সমস্যা\" (many non-sequiturs)। সমালোচকরা বলেন, ধরে নিলাম একটা \"প্রথম পরিবর্তক\" প্রমাণিত হলো - কিন্তু সেখান থেকে এই সত্তার বুদ্ধিমত্তা, ইচ্ছাশক্তি, মঙ্গলময়তা, বা ব্যক্তিত্ব আছে - এইসব বৈশিষ্ট্যে পৌঁছানো একেবারে আলাদা একটা কাজ, যেটা মূল যুক্তির তিন-চারটা লাইনে হয় না। আকুয়াইনাস নিজে অবশ্য সুম্মা থিওলজিকা-র পরবর্তী অংশে আলাদাভাবে এই বৈশিষ্ট্যগুলো প্রমাণের চেষ্টা করেছেন - তার মতে পাঁচটি পথ শুধু শুরুর ধাপ, পুরো যুক্তি না। এডওয়ার্ড ফেজার (Edward Feser)-এর মতো আধুনিক থোমিস্ট দার্শনিকরা জোর দিয়ে বলেন, পাঁচটি পথকে বিচ্ছিন্নভাবে বিচার করা ভুল - এগুলো আসলে একটা অনেক বড় দার্শনিক কাঠামোর অংশ মাত্র।", "চতুর্থ আপত্তি আসে \"অসীম শৃঙ্খল আসলেই কেন অসম্ভব\" - এই প্রশ্ন থেকে। অনেক সমালোচক বলেন, গাণিতিকভাবে অসীম সেট নিয়ে কোনো সমস্যা নেই, তাহলে বাস্তবেও একটা অসীম নির্ভরতার শৃঙ্খল থাকতে বাধা কোথায়? ফেজারের মতো সমর্থকরা জবাবে বলেন, এই শৃঙ্খলটা তো নিছক গণনার প্রশ্ন না - এটা এই মুহূর্তে প্রতিটা সদস্য আরেকজনের কাছ থেকে শক্তি ধার করছে কিনা, সেই প্রশ্ন। যদি প্রতিটা সদস্যই শুধু ধারকৃত শক্তি নিয়ে চলে, আর নিজস্ব কোনো শক্তির উৎস না থাকে, তাহলে পুরো শৃঙ্খলটাতেই আসলে কোনো প্রকৃত শক্তি নেই - সংখ্যাটা অসীম হোক বা সসীম, তাতে কিছু আসে যায় না। এই তর্কও এখনও দর্শনের বৃত্তে জীবন্ত।", "শেষ কথা", "আকুয়াইনাসের পরিবর্তনের যুক্তি আমাদের চারপাশের সবচেয়ে সাধারণ অভিজ্ঞতা থেকে শুরু হয়ে সবচেয়ে গভীর প্রশ্নে গিয়ে পৌঁছায় - জগতে যা কিছু বদলাচ্ছে, তার পেছনে কি সত্যিই এমন কিছু থাকতে হবে যে নিজে অপরিবর্তনীয়? নাকি পরিবর্তনের শৃঙ্খলটা এমনিতেই, কোনো চূড়ান্ত ব্যাখ্যা ছাড়াই চলতে পারে? এই প্রশ্নের উত্তর সহজ না, আর আটশো বছর ধরে দার্শনিকরা এটা নিয়ে তর্ক করে চলেছেন, তবুও কোনো একক উত্তরে পৌঁছাননি। হয়তো এটাই এই ধরনের প্রশ্নের সৌন্দর্য - এগুলো আমাদের ভাবতে বাধ্য করে, তাড়াহুড়ো করে সিদ্ধান্তে পৌঁছাতে দেয় না।", "তবে শুধু একটি যুক্তিতে নির্ভর না করে, আমরা যদি সম্মিলিত ভাবে অনেকগুলো দার্শনিক যুক্তি নিয়ে চিন্তা করি, সাথে রিলিজিয়াস টেক্সগুলোকে গাইড হিসেবে ব্যবহার করি, তা আমাদের চূড়ান্তের সত্যের কাছাকাছি পৌছাতে সাহায্য করতে পারে।"], "source": "philosophy"}, {"id": "ai-2026-09-18", "date": "2026-09-18", "title": "AI in healthcare research — a few things from today's reading — 18 September 2026", "excerpt": "Today's LLM papers centered on diagnostic reasoning and patient communication across specialties. A multi-LLM cardiology system (Llama 3.1 8B with retrieval-augmented…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "DiagnosticAI", "DigitalHealth", "ClinicalAI"], "body": ["Today's LLM papers centered on diagnostic reasoning and patient communication across specialties. A multi-LLM cardiology system (Llama 3.1 8B with retrieval-augmented generation) reached 0.796 accuracy and 0.807 F1 on cardiac diagnostic reasoning tasks, while an EHR-based mortality model combining LLM-extracted risk information with a Bi-GRU cross-attention layer outperformed ML, deep learning, and LLM-only baselines on three public ICU datasets. In musculoskeletal care, an LLM given patient-described symptoms disagreed with the treating specialist's diagnosis in 45% of 140 new outpatients, with most disagreement traced to genuine diagnostic ambiguity rather than patient factors. GPT-5 showed complete concordance with verbatim German guideline text in oral oncology, and a paired GPT-3.5-to-GPT-5.2 comparison across 216 neurology questions found a significant, though uneven, improvement across subspecialties. On decision support, GPT-5 outperformed Gemini on 60 bariatric surgery vignettes (87.3% vs 72.4% accuracy), and a community-codesigned primary care chatbot raised objective health awareness scores in a 2,113-participant randomized trial in China (2.95 vs 2.34, p<0.001).", "On the ML/DL side, several diagnostic and prognostic models targeted specific cancers and acute conditions with strong discrimination. A random forest model reached AUC 0.940 for identifying malignant pleural effusion from routine pleural fluid markers, and another random forest model hit 96.6% sensitivity and 90.5% specificity differentiating pelvic chondrosarcoma non-invasively. An interpretable model for invasive pulmonary aspergillosis in severe fever with thrombocytopenia syndrome patients reached AUC 0.871, while a random forest/neural network osteosarcoma model achieved AUCs of 0.826 and 0.766 in training and validation. A deep learning framework for lung cancer CT classification reported 91% accuracy, beating LSTM, FNN, and RNN baselines, and a jointly-trained deep learning network for thyroid disorder and PCOS risk reached AUROCs of 0.98 and 0.97 respectively.", "Across both threads, today's studies leaned toward comparative benchmarking — testing newer model generations, multiple LLMs head-to-head, or ML algorithms against each other — rather than single-model deployments."], "refs": [{"title": "Cardiology-Chat multi-LLM system for cardiac diagnostic reasoning", "url": "https://pubmed.ncbi.nlm.nih.gov/41970942/"}, {"title": "HiRMD: LLM-based mortality prediction from EHRs", "url": "https://pubmed.ncbi.nlm.nih.gov/42224317/"}, {"title": "LLM diagnostic concordance with musculoskeletal specialists", "url": "https://pubmed.ncbi.nlm.nih.gov/42299823/"}, {"title": "GPT-5 vs Gemini decision support for bariatric surgery", "url": "https://pubmed.ncbi.nlm.nih.gov/42284583/"}, {"title": "Community-codesigned LLM chatbot for primary care (RCT)", "url": "https://pubmed.ncbi.nlm.nih.gov/41659358/"}, {"title": "Random forest model for malignant pleural effusion diagnosis (AUC 0.940)", "url": "https://pubmed.ncbi.nlm.nih.gov/42306669/"}, {"title": "Random forest model for pelvic chondrosarcoma diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/42147252/"}, {"title": "Deep learning CT-based lung cancer prediction (91% accuracy)", "url": "https://pubmed.ncbi.nlm.nih.gov/41449566/"}, {"title": "Gated multi-task deep learning network for thyroid/PCOS risk", "url": "https://pubmed.ncbi.nlm.nih.gov/42428003/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-17", "date": "2026-09-17", "title": "AI in healthcare research — a few things from today's reading — 17 September 2026", "excerpt": "Today's LLM papers focused mainly on diagnostic accuracy in imaging and specialist domains, plus documentation support. On orofacial pain, a comparison of four chatbots…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "DiagnosticAI", "DigitalHealth", "ClinicalAI"], "body": ["Today's LLM papers focused mainly on diagnostic accuracy in imaging and specialist domains, plus documentation support. On orofacial pain, a comparison of four chatbots (ChatGPT 5.5, Claude Opus 4.1, Gemini 3 Flash, Grok 4) across 30 ICOP-based scenarios found Grok 4 scoring highest overall, though the other three did not differ significantly, and subclassification accuracy trailed primary diagnosis accuracy across the board. In neurosurgery, ChatGPT-4 led a five-model comparison on 148 clinical vignettes with 74% diagnostic accuracy, ahead of AtlasGPT (63%), ChatGPT-3.5 (53%), Copilot (48%), and Gemini (36%). Two brain tumor studies showed a similar pattern: GPT-4o reached 76% final-diagnosis and 83% differential-diagnosis accuracy when given structured findings instead of images alone, and LLM assistance lifted human readers' top-three differential accuracy (radiologists 80.7% to 90.2%, trainees 62.5% to 81.1%). On the workflow side, an LLM-based inpatient documentation tool scored 4.68/5 across quality domains from clinicians at three hospitals, and a simulated LLM-CDS platform improved tumor-board summary efficiency for 26 oncologists working synthetic breast cancer cases.", "On the ML/DL side, several prognostic and diagnostic models targeted specific cancers and acute conditions. An XGBoost model for hepatocellular carcinoma showed robust cross-center generalizability for predicting early recurrence after hepatectomy, while random forest-based ensembles were identified as the strongest approach for uncovering breast cancer prognostic factors, and a SEER-database model added population-level risk stratification for liver cancer. In acute care, an interpretable CatBoost model built on 85,886 pediatric pneumonia cases flagged chloride and glucose as novel biomarkers for simultaneous severe-pneumonia diagnosis and progression prediction, and a deep learning ensemble reached AUC 0.9388 (87.29% accuracy) classifying mpox from skin lesion images. A separate comparison of five lightweight deep learning architectures (CNN, LSTM, MLP, CNN-MLP, ConvLSTM) benchmarked ECG-based cardiovascular disease classification for accuracy against computational cost, and a new online tool targets one-year mortality risk in 601 maintenance hemodialysis patients.", "Across both threads, today's work leaned toward models built for deployment — web tools, calibrated risk scores, and documentation aids — rather than isolated benchmark exercises."], "refs": [{"title": "Four LLMs compared on ICOP-based orofacial pain diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/42439775/"}, {"title": "ChatGPT-4 leads five-model comparison on neurosurgery vignettes", "url": "https://pubmed.ncbi.nlm.nih.gov/41650460/"}, {"title": "GPT-4o feasibility study for brain tumor diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/41549106/"}, {"title": "LLM assistance improves radiologist/trainee brain tumor diagnostic accuracy", "url": "https://pubmed.ncbi.nlm.nih.gov/41753360/"}, {"title": "LLM-based inpatient documentation summarization quality assessment", "url": "https://pubmed.ncbi.nlm.nih.gov/42133622/"}, {"title": "Simulated LLM clinical decision support platform in oncology", "url": "https://pubmed.ncbi.nlm.nih.gov/41604603/"}, {"title": "XGBoost explainable model for HCC recurrence after hepatectomy", "url": "https://pubmed.ncbi.nlm.nih.gov/42383233/"}, {"title": "Interpretable CatBoost model for pediatric severe pneumonia risk", "url": "https://pubmed.ncbi.nlm.nih.gov/41317958/"}, {"title": "Deep learning ensemble for mpox image classification (AUC 0.94)", "url": "https://pubmed.ncbi.nlm.nih.gov/42430461/"}, {"title": "Deep learning architecture comparison for ECG-based cardiovascular diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/41794983/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-16", "date": "2026-09-16", "title": "AI in healthcare research — a few things from today's reading — 16 September 2026", "excerpt": "Today's LLM findings were largely about benchmarking against clinical reality rather than case-by-case wins. A study of 20 landmark NEJM trials found ChatGPT's…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalDecisionSupport", "DiagnosticAI", "DigitalHealth"], "body": ["Today's LLM findings were largely about benchmarking against clinical reality rather than case-by-case wins. A study of 20 landmark NEJM trials found ChatGPT's conclusions matched published findings 100% of the time, ahead of Gemini (84%), Grok3 (72%), and Claude (68%) — though the authors caution this may partly reflect prior training exposure to well-known trials. Separately, a Nature Medicine evaluation found frontier general-purpose LLMs (GPT-5.2, Gemini 3.1 Pro, Claude Opus 4.6) outperformed two specialized clinical AI tools across three benchmarks, with the clinical tools performing only on par with Google's AI Overview. On diagnosis, ChatGPT-4o reached 65.5% leading-diagnosis accuracy on complex polyneuropathy cases (comparable to non-specialist neurologists at 63.0%, below specialists at 74.0%), while ChatGPT 5.1 hit 97.1% sensitivity and 79.3% specificity classifying colorectal lesions from optical descriptions, and three chatbots (ChatGPT o4-mini, Gemini 2.5 Flash, DeepSeek-R1) showed 90-96% diagnostic agreement on age-related macular degeneration.", "On the ML/DL side, several interpretable models posted strong discrimination on well-scoped prediction tasks. A gradient boosting model for Crohn's disease diagnosis reached AUROC 0.954 internally and 0.944 on external validation, and an XGBoost model for early acute myocardial infarction risk hit 93.2% accuracy across 108 clinical features. A random forest model combining ultrasound and clinical data for diabetic peripheral neuropathy achieved AUC 0.852, while an interpretable model for MASLD detection using only routine non-invasive labs reached AUC 0.873. On the prognostic side, a logistic regression model identified eight independent predictors of 30-day mortality in severe cirrhosis (each unit rise in INR: +42.3% mortality risk), and a lung cancer EGFR-TKI study built both a mortality classifier (AUC ~0.82) and a survival-time model (concordance index ~0.66) from multi-institution EHR data.", "Across both threads, today's papers skew toward rigorous benchmarking — LLMs measured against real trial outcomes and specialist judgment, ML models validated externally with calibration checks — rather than isolated proof-of-concept results."], "refs": [{"title": "ChatGPT vs. Gemini/Grok3/Claude concordance with 20 landmark NEJM trial conclusions", "url": "https://pubmed.ncbi.nlm.nih.gov/41922554/"}, {"title": "Frontier LLMs outperform specialized clinical AI tools on medical benchmarks (Nature Medicine)", "url": "https://pubmed.ncbi.nlm.nih.gov/42286322/"}, {"title": "ChatGPT-4o vs. neurologists on complex polyneuropathy diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/42243282/"}, {"title": "ChatGPT 5.1 optical characterization of colorectal lesions", "url": "https://pubmed.ncbi.nlm.nih.gov/42504357/"}, {"title": "Three AI chatbots on age-related macular degeneration diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/42270292/"}, {"title": "Gradient boosting machine model + web tool for Crohn's disease diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/42068965/"}, {"title": "Interpretable XGBoost model for early acute myocardial infarction risk", "url": "https://pubmed.ncbi.nlm.nih.gov/42172727/"}, {"title": "Multimodal ML model (ultrasound + clinical) for diabetic peripheral neuropathy", "url": "https://pubmed.ncbi.nlm.nih.gov/41860757/"}, {"title": "Interpretable ML model for early detection of MASLD", "url": "https://pubmed.ncbi.nlm.nih.gov/42454348/"}, {"title": "ML mortality and survival-time models for lung cancer patients on EGFR-TKIs", "url": "https://pubmed.ncbi.nlm.nih.gov/42174863/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-15", "date": "2026-09-15", "title": "AI in healthcare research — a few things from today's reading — 15 September 2026", "excerpt": "Today's LLM findings leaned toward decision support and documentation rather than raw diagnosis. A retrospective cohort of 10,344 emergency department encounters found…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalDecisionSupport", "DiagnosticAI", "DigitalHealth"], "body": ["Today's LLM findings leaned toward decision support and documentation rather than raw diagnosis. A retrospective cohort of 10,344 emergency department encounters found ambient AI scribes cut on-shift documentation time by 72.6 seconds per encounter, roughly 24 minutes over an 8-hour, 20-encounter shift, while a separate non-inferiority study found GPT-4o matched hematology residents on documentation quality (88.9 vs 89.6) while reducing time from 14.9 minutes to 40.1 seconds. On the decision-support side, results were mixed: ChatGPT-5 showed only fair concordance with gynecologic oncology tumor boards (kappa 0.258-0.334) and was fully consistent across repeated queries in just 37.2% of cases, and ChatGPT-4o in a urological tumour board matched final recommendations only 79.2% of the time, below the study's benchmark. A pilot study on previously misdiagnosed dermatology cases found Gemini 3 led multimodal diagnostic accuracy at 60.0%, ahead of ChatGPT-5.2 (56.7%) and Claude 4.5 Sonnet (33.3%), and a large-scale analysis of 620,699 public ChatGPT conversations found mental-health-related content prevalence swung 23-fold (0.21% to 4.90%) depending on definition alone.", "ML/DL models continued to post strong, narrow discrimination on well-defined prediction tasks. An XGBoost model distinguishing malignant from benign pleural effusion reached AUC 0.988, and an explainable XGBoost model for cerebral small vessel disease achieved 88.0% accuracy with a companion nomogram. A gradient-boosting framework for in-hospital mortality in acute ischemic stroke hit external AUC 0.871 using high-granularity bedside data, and a similar interpretable GBM model for sepsis-induced myocardial injury mortality reached AUC 0.751 with a deployed web calculator. A 401-patient multicenter JASA study built a modernized prognostic score for spinal metastases using LASSO regression, addressing the fact that older scoring systems predate current oncologic therapies.", "Across both threads, LLMs are increasingly being tested where they're meant to assist — documentation and second-opinion support — rather than replace clinical judgment, while purpose-built ML models keep delivering high discrimination on tightly scoped, single-outcome prediction problems."], "refs": [{"title": "Ambient AI scribes reduce ED documentation burden (10,344 encounters)", "url": "https://pubmed.ncbi.nlm.nih.gov/42391625/"}, {"title": "GPT-4o vs residents on medical history documentation quality and speed", "url": "https://pubmed.ncbi.nlm.nih.gov/40438356/"}, {"title": "ChatGPT-5 concordance with gynecologic oncology tumor boards", "url": "https://pubmed.ncbi.nlm.nih.gov/42355621/"}, {"title": "ChatGPT-4o as decision support in a urological tumour board (prospective)", "url": "https://pubmed.ncbi.nlm.nih.gov/42611131/"}, {"title": "Multimodal LLMs on previously misdiagnosed dermatology cases", "url": "https://pubmed.ncbi.nlm.nih.gov/42340682/"}, {"title": "Prevalence of mental health discussions in public ChatGPT conversations (JAMA Network Open)", "url": "https://pubmed.ncbi.nlm.nih.gov/42635990/"}, {"title": "XGBoost model for diagnosing malignant pleural effusion (AUC 0.988)", "url": "https://pubmed.ncbi.nlm.nih.gov/42676367/"}, {"title": "Interpretable ML framework for in-hospital mortality in acute ischemic stroke", "url": "https://pubmed.ncbi.nlm.nih.gov/42648602/"}, {"title": "Gradient boosting model for mortality in sepsis-induced myocardial injury", "url": "https://pubmed.ncbi.nlm.nih.gov/42459190/"}, {"title": "JASA multicenter machine learning-based prognostic scoring for spinal metastases", "url": "https://pubmed.ncbi.nlm.nih.gov/41532870/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-14", "date": "2026-09-14", "title": "AI in healthcare research — a few things from today's reading — 14 September 2026", "excerpt": "Today's LLM findings centered on diagnostic accuracy benchmarking across specialties, with mixed results. GPT-5 approached clinician-level sensitivity for STEMI…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalDecisionSupport", "DiagnosticAI", "RiskPrediction"], "body": ["Today's LLM findings centered on diagnostic accuracy benchmarking across specialties, with mixed results. GPT-5 approached clinician-level sensitivity for STEMI diagnosis from 12-lead ECGs but was undermined by a very high false-positive rate, while GPT-4 with Vision reached 76% accuracy on neuroradiology board-style cases, well above prior GPT-4V radiology benchmarks (43%). ChatGPT-4o's ophthalmic diagnostic accuracy dropped from 80.1% with full clinical context to 54.7% on images alone, and four LLMs compared on 100 real otolaryngology cases scored 92-99% on diagnosis but far lower on treatment recommendations. A red-teaming study of 222 patient-posed medical questions found unsafe response rates of 5-13% across four major chatbots, while a smaller feasibility study found a GPT-4o-based PICU chatbot for parents was 99.3% accurate across 1,225 generated sentences.", "ML/DL risk-prediction models again delivered strong, narrow discrimination on well-defined clinical questions. A stacked ensemble using just 10 physical-exam parameters predicted coronary heart disease risk with AUC 0.977 internally and 0.929 on external validation, and an XGBoost model predicted postherpetic neuralgia risk with AUC 0.826-0.840 across training and external cohorts. A next-generation model built on 382,589 patients and 3.9 million EHR encounters reached AUC 0.869 for 6- and 12-month acute myocardial infarction risk, and a UK Biobank study of over 500,000 participants produced an improved risk model for incident diabetic foot complications. In oncology, a deep learning model trained on routine pathology slides from 591 pancreatic cancer patients predicted postoperative recurrence using only histology images, with external validation on 302 additional patients.", "The pattern from recent weeks continues: general-purpose LLMs perform unevenly on diagnostic tasks and struggle more with treatment decisions and safety than with pattern recognition, while purpose-built ML/DL models keep achieving high discrimination on specific, well-scoped prediction problems."], "refs": [{"title": "GPT-5 and GPT-4o accuracy diagnosing STEMI from 12-lead ECGs", "url": "https://pubmed.ncbi.nlm.nih.gov/41797077/"}, {"title": "GPT-4 with Vision diagnostic accuracy on neuroradiology board-style cases", "url": "https://pubmed.ncbi.nlm.nih.gov/42078574/"}, {"title": "Four LLMs compared on real-world otolaryngology diagnosis and treatment", "url": "https://pubmed.ncbi.nlm.nih.gov/42026294/"}, {"title": "Large language models and unsafe answers to patient-posed medical questions", "url": "https://pubmed.ncbi.nlm.nih.gov/41688533/"}, {"title": "Coronary heart disease risk prediction from simple physical-exam parameters (AUC 0.977/0.929)", "url": "https://pubmed.ncbi.nlm.nih.gov/42147060/"}, {"title": "Next-generation acute myocardial infarction risk model, multi-centre cohort (AUC 0.869)", "url": "https://pubmed.ncbi.nlm.nih.gov/42317965/"}, {"title": "UK Biobank risk model for incident diabetic foot complications", "url": "https://pubmed.ncbi.nlm.nih.gov/42253099/"}, {"title": "Machine learning on routine histology slides predicts pancreatic cancer recurrence", "url": "https://pubmed.ncbi.nlm.nih.gov/41507565/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-13", "date": "2026-09-13", "title": "AI in healthcare research — a few things from today's reading — 13 September 2026", "excerpt": "Today's LLM findings clustered around clinical decision support and diagnostic reasoning. ChatGPT-4o with retrieval-augmented generation outperformed 290 practicing…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalDecisionSupport", "DiagnosticAI", "OncologyAI"], "body": ["Today's LLM findings clustered around clinical decision support and diagnostic reasoning. ChatGPT-4o with retrieval-augmented generation outperformed 290 practicing neurologists on guideline adherence for MS and NMOSD management (80.5% vs. lower rates), and a small open-source model, Qwen2.5-14B with RAG, approached GPT-4-turbo's performance on 98 breast cancer guideline questions. GPT-4o showed moderate appropriateness for routine cataract lens selection but struggled on complex cases, while three LLMs (GPT-4o, Grok-3, DeepSeek) showed mixed but promising results interpreting dental caries guidelines. On the research side, RaDaR, a 32B-parameter open-source reasoning model trained on real and synthetic rare-disease cases, beat the much larger 671B DeepSeek-R1 and flagged the correct rare-disease diagnosis a median 1.87 months before clinical suspicion in a retrospective cohort.", "ML/DL diagnostic and prognostic models kept posting strong, narrow performance. A LightGBM model distinguishing Kawasaki disease from febrile mimics in 4,469 children hit an AUC of 0.979 (93.4% accuracy). An explainable model combining inflammatory markers and traditional risk factors diagnosed coronary artery disease in 4,656 angiography patients (AUC 0.815), and a deep learning mammography risk model outperformed breast density at stratifying future breast cancer risk across 123,091 screening exams. In oncology prognosis, a multimodal transformer fusing pathology, ultrasound, and clinical data reached a C-index of 0.840 for recurrence risk in 768 HR+/HER2- breast cancer patients, while deep learning-derived MRI subtypes improved 5-year recurrence-free survival prediction in rectal cancer (AUC 0.799 to 0.834).", "Across both areas, general-purpose LLMs are increasingly being benchmarked directly against clinicians on guideline-based decisions, while disease-specific ML/DL models continue to deliver high-discrimination results on narrower diagnostic and prognostic tasks."], "refs": [{"title": "ChatGPT-4o with RAG vs. 290 neurologists on MS/NMOSD guideline adherence", "url": "https://pubmed.ncbi.nlm.nih.gov/41993106/"}, {"title": "Small open-source LLMs with RAG vs. GPT-4 for breast cancer clinical decision support", "url": "https://pubmed.ncbi.nlm.nih.gov/42361285/"}, {"title": "RaDaR: 32B reasoning LLM for rare disease diagnosis, randomized physician-assistance trial", "url": "https://arxiv.org/abs/2606.24510"}, {"title": "LightGBM diagnostic model for Kawasaki disease (AUC 0.979, n=4,469)", "url": "https://pubmed.ncbi.nlm.nih.gov/42266873/"}, {"title": "Explainable ML model for coronary artery disease diagnosis in non-AMI patients", "url": "https://pubmed.ncbi.nlm.nih.gov/42236130/"}, {"title": "Deep learning breast cancer risk model vs. breast density for supplemental screening", "url": "https://pubmed.ncbi.nlm.nih.gov/42081242/"}, {"title": "Multimodal deep learning recurrence risk model for HR+/HER2- breast cancer (C-index 0.840)", "url": "https://pubmed.ncbi.nlm.nih.gov/41919095/"}, {"title": "Deep learning MRI radiomics subtypes and recurrence risk in rectal cancer", "url": "https://pubmed.ncbi.nlm.nih.gov/42350713/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-12", "date": "2026-09-12", "title": "AI in healthcare research — a few things from today's reading — 12 September 2026", "excerpt": "Today's LLM papers largely centered on diagnostic benchmarking against imaging and specialty scenarios. On 800 fundus photographs across eight retinal conditions,…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "DiagnosticAI", "ClinicalAI", "OncologyAI"], "body": ["Today's LLM papers largely centered on diagnostic benchmarking against imaging and specialty scenarios. On 800 fundus photographs across eight retinal conditions, ChatGPT-4o reached 75% diagnostic accuracy versus 14-18% for Claude, Gemini, and Grok. In otolaryngology, four models scored 92-99% across 100 real cases (ChatGPT-5 highest at 99%), while on 218 anogenital skin lesion images Gemini led with 76.2% accuracy for STI classification. An agentic GPT-5.0 system reached 91.0% accuracy on acid-base disorder cases in a critical care simulation, ahead of GPT-4o (78.0%), Gemini (74.5%), and human specialists (83.0%). A new benchmark, PhysAssistBench, found that leading LLMs handle single turns of physician-patient-EHR interaction well but reliability collapses across full multi-turn sessions built from 1,296 MIMIC-IV-derived scenarios.", "On the ML/DL side, imaging-based risk models continued to post strong discrimination: a multimodal deep learning algorithm combining retinal fundus photos and OCT reached AUCs of 0.91-0.995 for coronary heart disease risk across 505 patients, and a YOLOv11/ResNet-18 cholangioscopy system hit 91.2% precision for malignant biliary stricture detection across 174 patients. Survival modeling remained active in oncology, with a six-model comparison in 337 gastroenteropancreatic neuroendocrine tumor patients favoring Extra Trees and DeepSurv, and a 10-gene machine learning signature distinguishing early hepatocellular carcinoma with AUC >0.9 while also predicting differential response to sorafenib versus TACE. Elsewhere, narrower risk models targeted ICU mortality, enteral feeding intolerance in sepsis, interstitial lung disease prognosis, and disorders-of-consciousness outcomes.", "The pattern holds: LLM studies are still mostly measuring how far general-purpose models can go on diagnostic and interactive tasks they weren't purpose-built for, while disease-specific ML/DL models keep reporting strong, narrower performance on prognosis and risk stratification."], "refs": [{"title": "Multimodal LLMs for retinal disease diagnosis from fundus photos (75% vs 14-18% accuracy)", "url": "https://pubmed.ncbi.nlm.nih.gov/42640646/"}, {"title": "Four-LLM comparison for otolaryngology diagnosis/treatment decisions", "url": "https://pubmed.ncbi.nlm.nih.gov/42026294/"}, {"title": "Agentic GPT-5.0 vs standard LLMs and human experts in critical care", "url": "https://pubmed.ncbi.nlm.nih.gov/42104391/"}, {"title": "PhysAssistBench: LLM reliability across multi-turn physician-patient-EHR sessions", "url": "https://arxiv.org/abs/2606.18613"}, {"title": "Multimodal deep learning (fundus + OCT) for coronary heart disease risk (AUC up to 0.995)", "url": "https://pubmed.ncbi.nlm.nih.gov/42432531/"}, {"title": "Deep learning CADe/CADx system for malignant biliary stricture on cholangioscopy", "url": "https://pubmed.ncbi.nlm.nih.gov/42588629/"}, {"title": "Six-model survival comparison for gastroenteropancreatic neuroendocrine tumors", "url": "https://pubmed.ncbi.nlm.nih.gov/42661703/"}, {"title": "10-gene ML signature for HCC diagnosis, prognosis, and treatment response", "url": "https://pubmed.ncbi.nlm.nih.gov/41787910/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-11", "date": "2026-09-11", "title": "AI in healthcare research — a few things from today's reading — 11 September 2026", "excerpt": "Today's LLM papers focused on diagnostic benchmarking across specialties. A new agentic model, DxDirector-7B, drove full diagnostic workflows across 160 cases in 9…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "DiagnosticAI", "RiskPrediction"], "body": ["Today's LLM papers focused on diagnostic benchmarking across specialties. A new agentic model, DxDirector-7B, drove full diagnostic workflows across 160 cases in 9 departments and outperformed larger general-purpose and medical LLMs despite its smaller size. A head-to-head comparison of DeepSeek-V3, GPT-4o, GPT-4o mini, and Claude 3.5 Sonnet on 50 real-world cases found DeepSeek-V3 and GPT-4o tied for the highest diagnostic accuracy (82%), with Claude trailing at 76%; a separate five-model comparison across 405 internal medicine cases similarly found Claude the weakest performer, while all models struggled with differential diagnosis and respiratory disease management. In pediatrics, newer LLMs outperformed both earlier models and 78 human clinicians on rare-disease recognition across 50 real clinical cases. On the deployment side, an LLM-augmented sepsis prediction system (COMPOSER-LLM) improved clinical acceptance of alerts across 2,500 ED encounters (72.1% sensitivity, 0.0087 false alarms per patient-hour).", "On the ML side, mortality and risk prediction remained the dominant use case. A multivariable model for acute aortic syndrome reached internal/external AUCs of 0.85–0.90 and 0.73–0.85 across 929 patients and three hospitals, while an XGBoost model for ARDS achieved AUCs of 0.69–0.75 for 28- and 90-day mortality. For dizziness triage, four ML models trained on 6,637 ED patients matched or exceeded existing risk scores (AUC up to 0.97) while projecting 53–85% reductions in CT utilization. Elsewhere, models targeted breast cancer risk in BI-RADS 4 lesions, diabetic kidney disease, medication harm, and pulmonary embolism mortality, continuing the pattern of narrow, disease-specific models reporting strong discrimination on retrospective data.", "Taken together, today's studies reinforce a now-familiar split: LLMs are being pushed hardest on general diagnostic reasoning and clinical communication, while purpose-built ML models keep posting strong numbers on well-defined mortality and risk-prediction tasks."], "refs": [{"title": "DxDirector-7B agentic LLM for full-process clinical diagnosis", "url": "https://pubmed.ncbi.nlm.nih.gov/42026083/"}, {"title": "DeepSeek vs ChatGPT vs Claude diagnostic benchmarking (ICD-10-CM framework)", "url": "https://pubmed.ncbi.nlm.nih.gov/42168963/"}, {"title": "Five-LLM comparative study for internal medicine decision-making", "url": "https://pubmed.ncbi.nlm.nih.gov/41907359/"}, {"title": "LLMs vs. 78 pediatric clinicians on rare and common diagnoses", "url": "https://pubmed.ncbi.nlm.nih.gov/42358891/"}, {"title": "COMPOSER-LLM sepsis prediction and alert acceptance", "url": "https://pubmed.ncbi.nlm.nih.gov/42552440/"}, {"title": "ML models for dizziness triage and imaging reduction in the ED (AUC 0.97)", "url": "https://pubmed.ncbi.nlm.nih.gov/42383526/"}, {"title": "ML mortality prediction for acute aortic syndrome (AUC 0.85-0.90)", "url": "https://pubmed.ncbi.nlm.nih.gov/41624614/"}, {"title": "XGBoost mortality prediction in ARDS", "url": "https://pubmed.ncbi.nlm.nih.gov/42394040/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-10", "date": "2026-09-10", "title": "AI in healthcare research — a few things from today's reading — 10 September 2026", "excerpt": "Today's LLM papers cluster around emergency and urgent-care triage. A seven-month comparative study found an LLM-based ED triage architecture outperforming NLP and…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "ClinicalAI", "EmergencyMedicine", "RiskPrediction"], "body": ["Today's LLM papers cluster around emergency and urgent-care triage. A seven-month comparative study found an LLM-based ED triage architecture outperforming NLP and joint-embedding models and current nurse triage (F1 0.900, AUC-ROC 0.879), though the authors flagged severe overfitting and called for external validation before deployment. In trauma, GPT-5.2, Gemini 3.0 Flash, and Claude 4.5 Opus showed strong overall discrimination on 150 vignettes but undertriaged geriatric and blunt-trauma cases disproportionately, and 11.2% of repeated prompts shifted triage category under minor wording changes. A cardiology-specific model, TriageMaster-70B, processed acute coronary syndrome triage 39% faster than cardiologist review across over 16,000 retrospective cases, while a broader meta-analysis of LLMs for ED triage found only moderate accuracy and limited sensitivity for the highest-acuity cases — a reminder that speed and headline accuracy don't always mean the models are ready to act alone.", "On the prediction side, readmission and mortality modeling was the theme. An XGBoost model predicted 12-month heart failure readmission with AUC 0.861 in a 14,131-patient multicenter ED trial, and a separate SHAP-interpreted Boruta-XGBoost model reached AUC 0.873 for readmission or death in elderly heart failure patients during the vulnerable post-discharge phase. A multimodal deep learning model combining CT imaging, biomarkers, and clinical data improved 5-year mortality risk stratification in high-risk stage II colorectal cancer, and a separate multimodal model for non-small cell lung cancer reached a C-index of 0.71 for 5-year prognosis while also identifying novel biomarkers. Not every model held up equally well: a pediatric ICU readmission model saw AUC drop from 0.70-0.73 internally to as low as 0.60 on external validation, and an Australian cardiac-surgery registry model showed only limited predictive power, underscoring how much generalizability still varies by task and dataset.", "Across both threads, today's papers show narrow, well-specified models continuing to post strong discrimination, while triage- and deployment-facing LLM systems are being stress-tested harder for consistency, not just accuracy."], "refs": [{"title": "LLM-based ED triage architecture vs. NLP/JEPA models (F1 0.900)", "url": "https://pubmed.ncbi.nlm.nih.gov/41805589/"}, {"title": "Prompt fragility and undertriage risk in frontier LLMs for trauma triage", "url": "https://pubmed.ncbi.nlm.nih.gov/42214316/"}, {"title": "TriageMaster-70B for acute coronary syndrome triage", "url": "https://pubmed.ncbi.nlm.nih.gov/42310091/"}, {"title": "Meta-analysis of LLM diagnostic accuracy for ED triage", "url": "https://pubmed.ncbi.nlm.nih.gov/42298434/"}, {"title": "XGBoost model for 12-month heart failure readmission (AUC 0.861)", "url": "https://pubmed.ncbi.nlm.nih.gov/42330738/"}, {"title": "SHAP-interpreted model for elderly heart failure readmission/death (AUC 0.873)", "url": "https://pubmed.ncbi.nlm.nih.gov/42293329/"}, {"title": "Multimodal deep learning model for colorectal cancer 5-year mortality", "url": "https://pubmed.ncbi.nlm.nih.gov/42069945/"}, {"title": "Multimodal deep learning for NSCLC survival and biomarker discovery (C-index 0.71)", "url": "https://pubmed.ncbi.nlm.nih.gov/41703583/"}, {"title": "Pediatric ICU readmission model, internal vs. external validation", "url": "https://pubmed.ncbi.nlm.nih.gov/42238388/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-09", "date": "2026-09-09", "title": "AI in healthcare research — a few things from today's reading — 9 September 2026", "excerpt": "Several papers this cycle focus on how far patient-facing LLM chatbots have actually gotten. A GPT-4o chatbot answering parents' questions in the PICU produced 1,225…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "DigitalHealth", "ClinicalAI", "RiskPrediction"], "body": ["Several papers this cycle focus on how far patient-facing LLM chatbots have actually gotten. A GPT-4o chatbot answering parents' questions in the PICU produced 1,225 responses that were 99.3% accurate, with parents rating it highly (Net Promoter Score +57) after just 10-minute sessions. A separate multilingual evaluation of a similar GPT-4o-based primary care chatbot tested it across English, Mandarin, Spanish, and Hindi to check whether performance holds up outside its native language. On the more cautious side, a review argues LLMs are not yet safe for autonomous clinical triage with no clinician in the loop, and a prompt-sensitivity study found that even minor phrasing changes could shift the clinical advice given by both general-purpose and medical-specific models.", "On the prediction side, several new risk models reported strong discrimination on well-defined tasks. A deep learning model for alcohol use disorder in adolescents reached an AUC of 0.85 on independent validation. A Transformer-based model jointly predicting malignancy in thyroid and breast nodules reached AUCs of 0.932 and 0.917, respectively. A multimodal deep learning model combining histopathology, genomics, and clinical data for prostate cancer prognosis reached a C-index of 0.774, outperforming standard NCCN risk stratification. A hybrid framework paired a CNN-based cardiovascular risk model with a retrieval-augmented LLM to turn predicted MACE risk into personalized, guideline-based recommendations — an example of the two approaches being combined rather than compared.", "Taken together, today's batch reinforces a familiar pattern: LLM chatbots are being tested carefully for real patient-facing use, evaluators remain cautious about full autonomy, and narrow ML/DL risk models keep posting strong AUCs on specific clinical prediction tasks — sometimes now paired with an LLM layer for communicating results."], "refs": [{"title": "LLM chatbot for parental understanding in the PICU (99.3% accuracy)", "url": "https://pubmed.ncbi.nlm.nih.gov/41860987/"}, {"title": "Multilingual evaluation of a GPT-4o primary care chatbot", "url": "https://pubmed.ncbi.nlm.nih.gov/42245029/"}, {"title": "Why LLMs are not yet safe for autonomous clinical decision support", "url": "https://arxiv.org/abs/2607.28677"}, {"title": "LLM sensitivity to prompt variations in healthcare", "url": "https://arxiv.org/abs/2606.07237"}, {"title": "Deep learning model for alcohol use disorder risk (AUC 0.85)", "url": "https://pubmed.ncbi.nlm.nih.gov/41748155/"}, {"title": "Deep learning model for thyroid/breast nodule malignancy (AUC 0.932/0.917)", "url": "https://pubmed.ncbi.nlm.nih.gov/41672617/"}, {"title": "Multimodal deep learning prognostic model for prostate cancer (C-index 0.774)", "url": "https://pubmed.ncbi.nlm.nih.gov/41456225/"}, {"title": "Hybrid deep learning + LLM framework for MACE risk and recommendations", "url": "https://pubmed.ncbi.nlm.nih.gov/42662215/"}], "lang": "en", "source": "ai"}, {"id": "ai-2026-09-08", "date": "2026-09-08", "title": "AI in healthcare research — a few things from today's reading — 8 September 2026", "excerpt": "A few studies worth noting from today's screening. A benchmark comparison found that general-purpose LLMs (GPT-5.2, Gemini 3.1 Pro, Claude Opus 4.6) performed better…", "theme": "ai", "cats": ["AI in health research", "AIinHealthcare", "MachineLearning", "LLM", "DigitalHealth", "ClinicalAI", "HealthTech"], "body": ["A few studies worth noting from today's screening. A benchmark comparison found that general-purpose LLMs (GPT-5.2, Gemini 3.1 Pro, Claude Opus 4.6) performed better than specialized clinical AI tools, including UpToDate's own AI, on real physician queries. Separately, a comparison of four LLMs against 20 landmark NEJM trials found ChatGPT matched the published conclusions in every case tested.", "Not every result favored LLMs working alone, though. A study on perioperative anticoagulation management found LLM performance modest on its own, with meaningful improvement only after pairing the model with structured clinical decision support.", "On the diagnostic side, purpose-built ML/DL models continue to perform well in narrower, well-defined tasks: a deep learning model reached 96% positive predictive value diagnosing seven ocular surface diseases, an MRI-based classifier matched radiologist-level accuracy for Alzheimer's diagnosis, and a sepsis outcome model reached an AUC of 0.983.", "Taken together, it's a reasonable snapshot of where things stand: LLMs are increasingly competitive on reasoning and communication-heavy tasks, while dedicated ML/DL models still lead on narrow, high-stakes diagnostic prediction."], "refs": [{"title": "General-purpose LLMs outperform specialized clinical AI tools", "url": "https://pubmed.ncbi.nlm.nih.gov/42286322/"}, {"title": "Benchmarking LLM agreement with NEJM trial conclusions", "url": "https://pubmed.ncbi.nlm.nih.gov/41922554/"}, {"title": "LLM + clinical decision support in anticoagulation management", "url": "https://pubmed.ncbi.nlm.nih.gov/42070385/"}, {"title": "Deep learning diagnostic model for ocular surface diseases", "url": "https://pubmed.ncbi.nlm.nih.gov/41748055/"}, {"title": "MRI-based Alzheimer's classifier vs. radiologists", "url": "https://pubmed.ncbi.nlm.nih.gov/42211832/"}, {"title": "Explainable ML for sepsis outcome prediction", "url": "https://arxiv.org/abs/2604.04698"}], "lang": "en", "source": "ai"}];
